INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1088, NULL, '2026-10-29 11:03:03.585987', 'Người đàn ông Anh dành tình yêu đặc biệt cho thương hiệu ôtô Proton của Malaysia, sở hữu bộ sưu tập lên tới 34 chiếc.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/ProtonSaga2-1793173672-6287-1793174624.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=VXJgUTeuJPYNTo30wvWX0A', '2026-10-28 22:00:00', NULL, 'Doanh nhân Anh sưu tầm gần 40 ôtô thương hiệu Đông Nam Á', 'https://vnexpress.net/doanh-nhan-anh-suu-tam-gan-40-oto-thuong-hieu-dong-nam-a-5137733.html', 12, 16, 'https://vnexpress.net/doanh-nhan-anh-suu-tam-gan-40-oto-thuong-hieu-dong-nam-a-5137733.html', 'CRAWLER', '2026-10-29 11:07:47.773601', '2026-10-29 11:03:03.585987');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1091, NULL, '2026-10-29 11:03:03.595991', 'Chiếc Xiaomi cháy khi đang chạy và chiếc Tesla bị thiêu rụi khi đang đỗ ở Trung Quốc đều có nguyên nhân giống xe buýt cháy ở Hà Nội ngày 27/10.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/bus1179316254118081793162788-1-4311-5538-1793164449.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=8qllclqjGGtc9z0iiBNKpA', '2026-10-28 05:14:30', NULL, 'Nắp cống - ''sát thủ'' âm thầm của xe điện', 'https://vnexpress.net/nap-cong-sat-thu-am-tham-cua-xe-dien-5137752.html', 12, 16, 'https://vnexpress.net/nap-cong-sat-thu-am-tham-cua-xe-dien-5137752.html', 'CRAWLER', '2026-10-29 11:07:47.797623', '2026-10-29 11:03:03.595991');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1086, NULL, '2026-10-29 11:03:03.56799', 'Năm 2025, các hãng ra mắt khoảng 8 mẫu hybrid sạc ngoài (PHEV) mới, sang 2026, số lượng khoảng 15 mẫu tính đến cuối năm.', 'https://i1-vnexpress.vnecdn.net/2026/10/29/wm1bydsealion17903504061790381-9486-3222-1793221933.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=g2xfVlu6BImUA0ne7rZi5A', '2026-10-29 02:45:43', NULL, 'Ôtô vừa cắm điện vừa đổ xăng bắt đầu nở rộ ở Việt Nam', 'https://vnexpress.net/oto-vua-cam-dien-vua-do-xang-bat-dau-no-ro-o-viet-nam-5137786.html', 12, 16, 'https://vnexpress.net/oto-vua-cam-dien-vua-do-xang-bat-dau-no-ro-o-viet-nam-5137786.html', 'CRAWLER', '2026-10-29 11:07:47.733569', '2026-10-29 11:03:03.56799');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1090, NULL, '2026-10-29 11:03:03.591988', 'Biên lợi nhuận ngành ôtô Trung Quốc xuống 1,4% trong tháng 9, khi mỗi xe bán ra chỉ mang về khoảng 1.650 USD lợi nhuận trong chín tháng qua.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/byds-new-energy-vehicles-manuf-2971-8055-1793199054.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=PNbc7c8BskgKHt00WeLYjA', '2026-10-28 23:00:00', NULL, 'Cuộc đua giảm giá bào mòn lợi nhuận của ôtô Trung Quốc', 'https://vnexpress.net/cuoc-dua-giam-gia-bao-mon-loi-nhuan-cua-oto-trung-quoc-5138066.html', 10, 16, 'https://vnexpress.net/cuoc-dua-giam-gia-bao-mon-loi-nhuan-cua-oto-trung-quoc-5138066.html', 'CRAWLER', '2026-10-29 11:07:48.936219', '2026-10-29 11:07:48.936219');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1092, NULL, '2026-10-29 11:03:03.597989', 'Mẫu xe gầm cao cỡ B mới tinh chỉnh thiết kế, lắp động cơ xăng hút khí tự nhiên, trang bị nhiều tính năng, giá cao nhất 18.900 USD.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/hyundaibayon20261-1793091722-2647-1793154470.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=JJhilfTOLd7vpzWeC2sSAQ', '2026-10-28 04:30:58', NULL, 'Hyundai Bayon thế hệ mới ra mắt, giá từ 10.500 USD', 'https://vnexpress.net/hyundai-bayon-the-he-moi-ra-mat-gia-tu-10-500-usd-5137506.html', 12, 16, 'https://vnexpress.net/hyundai-bayon-the-he-moi-ra-mat-gia-tu-10-500-usd-5137506.html', 'CRAWLER', '2026-10-29 11:07:47.802984', '2026-10-29 11:03:03.597989');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1093, NULL, '2026-10-29 11:03:03.600987', 'Hãng xe Nhật đặt mục tiêu doanh thu khoảng 1,7 tỷ USD mỗi năm từ mảng cung cấp động cơ và công nghệ hybrid cho các đối tác từ 2032.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/Toyota1-1793153606-7250-1793153776.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=4KZjiuJRF5szTFMnWCswDA', '2026-10-28 03:37:28', NULL, 'Toyota muốn bán động cơ thế hệ mới cho các hãng xe đối thủ', 'https://vnexpress.net/toyota-muon-ban-dong-co-the-he-moi-cho-cac-hang-xe-doi-thu-5137665.html', 12, 16, 'https://vnexpress.net/toyota-muon-ban-dong-co-the-he-moi-cho-cac-hang-xe-doi-thu-5137665.html', 'CRAWLER', '2026-10-29 11:07:47.807985', '2026-10-29 11:03:03.600987');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1094, NULL, '2026-10-29 11:03:03.602984', 'Người đi xe máy tạt ngang qua đầu ôtô bị đâm ngã văng về phía trước, hôm 27/10 tại Đường tỉnh 774, An Tây, Bình Dương.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/ezgif406379be12e2af97-17930872-4512-2211-1793087300.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=h3g9LzjVFtB36C0HvnM6cw&t=image', '2026-10-27 23:33:00', NULL, 'Bất ngờ chuyển hướng, xe máy bị ôtô húc văng', 'https://vnexpress.net/bat-ngo-chuyen-huong-xe-may-bi-oto-huc-vang-5137467.html', 12, 16, 'https://vnexpress.net/bat-ngo-chuyen-huong-xe-may-bi-oto-huc-vang-5137467.html', 'CRAWLER', '2026-10-29 11:07:47.814986', '2026-10-29 11:03:03.602984');
