INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1149, NULL, '2026-10-29 11:03:03.81505', '1h30 sáng, Hoàng Minh gửi xong báo cáo quý thì điện thoại lại sáng với 4 tin nhắn công việc. Anh với tay bóc hai viên kẹo dẻo melatonin nhai vội: "Không nhai thì không ngủ được".', 'https://i1-suckhoe.vnecdn.net/2026/10/26/screenshot-at-1793000771-6837-1793002351.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=alsEbVtwitdv1eq3jO6rwA', '2026-10-28 23:00:00', NULL, 'Gen Z cưỡng ép giấc ngủ bằng ''thần dược kẹo'' an thần', 'https://vnexpress.net/gen-z-cuong-ep-giac-ngu-bang-than-duoc-keo-an-than-5136484.html', 10, 17, 'https://vnexpress.net/gen-z-cuong-ep-giac-ngu-bang-than-duoc-keo-an-than-5136484.html', 'CRAWLER', '2026-10-29 11:07:48.930246', '2026-10-29 11:07:48.930246');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1151, NULL, '2026-10-29 11:03:03.822061', 'Cố làm việc khi đang ốm, ăn nhiều đồ ngọt, thường xuyên bỏ bữa hoặc ít hoạt động trí óc có thể ảnh hưởng đến trí nhớ và khả năng tập trung.', 'https://i1-suckhoe.vnecdn.net/2026/10/14/ba-nh-ngo-t-jpeg-1791967673-7200-1791967745.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=vDbRRQ9WOntmJ3eQxtvOJw', '2026-10-28 20:03:00', NULL, 'Những thói quen tưởng bình thường nhưng không tốt cho não', 'https://vnexpress.net/nhung-thoi-quen-tuong-binh-thuong-nhung-khong-tot-cho-nao-5131868.html', 16, 17, 'https://vnexpress.net/nhung-thoi-quen-tuong-binh-thuong-nhung-khong-tot-cho-nao-5131868.html', 'CRAWLER', '2026-10-29 11:07:48.225197', '2026-10-29 11:03:03.822061');
