INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1159, NULL, '2026-10-29 11:03:03.855057', 'Ông Tú, 50 tuổi, đau bụng, phát hiện tổn thương trong gan tưởng khối u song xét nghiệm xác định viêm do sán.', 'https://i1-suckhoe.vnecdn.net/2026/10/29/lagan-1793235798-1394-1793236074.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=hOpVTkn958lZdeE6mAqO1Q', '2026-10-29 01:00:00', NULL, 'Tưởng u gan hóa nhiễm sán', 'https://vnexpress.net/tuong-u-gan-hoa-nhiem-san-5138107.html', 10, 17, 'https://vnexpress.net/tuong-u-gan-hoa-nhiem-san-5138107.html', 'CRAWLER', '2026-10-29 11:07:48.860221', '2026-10-29 11:07:48.860221');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1163, NULL, '2026-10-29 11:03:03.87005', 'Người đàn ông 66 tuổi ngã vào bụi tre bị mảnh cây dài 10 cm đâm vào cổ, ba tháng sau mới phẫu thuật lấy ra.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/858501809122210499944844035150-4655-3366-1793181934.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=T_ZEQg7_8Py3h14N6SPMZw', '2026-10-28 11:37:35', NULL, 'Mảnh tre dài 10 cm nằm 3 tháng trong cổ người đàn ông', 'https://vnexpress.net/manh-tre-dai-10-cm-nam-3-thang-trong-co-nguoi-dan-ong-5138002.html', 16, 17, 'https://vnexpress.net/manh-tre-dai-10-cm-nam-3-thang-trong-co-nguoi-dan-ong-5138002.html', 'CRAWLER', '2026-10-29 11:07:48.275082', '2026-10-29 11:03:03.87005');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1164, NULL, '2026-10-29 11:03:03.873064', 'Sau tai nạn giao thông, thiếu niên không ghi nhận biểu hiện thần kinh bất thường, sau một đêm đột ngột liệt nửa người, bác sĩ phát hiện đột quỵ, nguy kịch.', 'https://i1-suckhoe.vnecdn.net/2026/10/28/eb7d2ecca7d-e97c56c862e1-17931-1474-1172-1793174214.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=gZkje05_GwK257jbPZh_nw', '2026-10-28 10:00:00', NULL, 'Thiếu niên 16 tuổi đột quỵ não từ chấn thương tưởng nhẹ', 'https://vnexpress.net/thieu-nien-16-tuoi-dot-quy-nao-tu-chan-thuong-tuong-nhe-5137914.html', 16, 17, 'https://vnexpress.net/thieu-nien-16-tuoi-dot-quy-nao-tu-chan-thuong-tuong-nhe-5137914.html', 'CRAWLER', '2026-10-29 11:07:48.281082', '2026-10-29 11:03:03.873064');
