INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1212, NULL, '2026-10-29 11:03:04.135631', 'Loạt ngành ở nhiều lĩnh vực như kỹ thuật, công nghệ, sức khỏe hệ trung cấp, cao đẳng dự kiến được đưa vào danh mục khó tuyển sinh nhưng xã hội có nhu cầu - thuộc diện miễn học phí.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/wm1-wm1-233a9317-1793155251-3552-1793155311.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Z6gaCErr39ehIaedi-bPbQ', '2026-10-28 04:42:04', NULL, 'Dự kiến 35 ngành, nghề khó tuyển sinh được miễn 100% học phí', 'https://vnexpress.net/du-kien-35-nganh-nghe-kho-tuyen-sinh-duoc-mien-100-hoc-phi-5137728.html', 17, 18, 'https://vnexpress.net/du-kien-35-nganh-nghe-kho-tuyen-sinh-duoc-mien-100-hoc-phi-5137728.html', 'CRAWLER', '2026-10-29 11:07:48.521085', '2026-10-29 11:03:04.135631');
