INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1214, NULL, '2026-10-29 11:03:04.144542', 'Nằm ở khu vực địa chấn rất mạnh, liệu Nhật Bản có phải quốc gia có nhiều động đất nhất thế giới?', 'https://i1-vnexpress.vnecdn.net/2026/10/28/jakarta-1793187247-2197-1793187267.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=LjAjcegbWhu7--jy4lG0qA', '2026-10-28 14:08:53', NULL, 'Nước nào có nhiều động đất nhất thế giới?', 'https://vnexpress.net/nuoc-nao-co-nhieu-dong-dat-nhat-the-gioi-5138031.html', 17, 18, 'https://vnexpress.net/nuoc-nao-co-nhieu-dong-dat-nhat-the-gioi-5138031.html', 'CRAWLER', '2026-10-29 11:07:48.535083', '2026-10-29 11:03:04.144542');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1207, NULL, '2026-10-29 11:03:04.115554', 'Trước yêu cầu mặc áo dài nhiều buổi trong tuần hoặc phải thay đồng phục thể dục khi đến tiết học, nhiều học sinh, phụ huynh thấy bất tiện, phản ứng.', 'https://i1-vnexpress.vnecdn.net/2026/10/09/798724606214428741646496916052-4923-1368-1791517623.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=VDuN2CSpbV-YU8TzNb7sOw', '2026-10-28 23:36:14', NULL, 'Nhiều học sinh than ''bí bách'' vì đồng phục', 'https://vnexpress.net/nhieu-hoc-sinh-than-bi-bach-vi-dong-phuc-5130300.html', 10, 18, 'https://vnexpress.net/nhieu-hoc-sinh-than-bi-bach-vi-dong-phuc-5130300.html', 'CRAWLER', '2026-10-29 11:07:48.896236', '2026-10-29 11:07:48.896236');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1216, NULL, '2026-10-29 11:03:04.152161', 'Herbalife góp phần giúp sinh viên phát huy ý tưởng, rèn luyện kỹ năng và triển khai các dự án vì cộng đồng tại mùa thứ 4 của chương trình.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/image001-1793164963-1536-1793165035.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=6I2-wcGUlIhm6c8_8Tnb1w', '2026-10-28 07:00:00', NULL, 'Herbalife hỗ trợ sinh viên sáng tạo và phát triển dự án cộng đồng', 'https://vnexpress.net/herbalife-ho-tro-sinh-vien-sang-tao-va-phat-trien-du-an-cong-dong-5137844.html', 17, 18, 'https://vnexpress.net/herbalife-ho-tro-sinh-vien-sang-tao-va-phat-trien-du-an-cong-dong-5137844.html', 'CRAWLER', '2026-10-29 11:07:48.541099', '2026-10-29 11:03:04.152161');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1217, NULL, '2026-10-29 11:03:04.1561', 'Bộ Giáo dục và Đào tạo lần đầu đề xuất "quy định cứng" về số giờ làm việc với giáo viên phổ thông là 8 giờ mỗi ngày, có thể ở trường nếu đủ cơ sở vật chất.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/cva-of-1793092229-2986-1793113247.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=GtGiOVio7BA_0vaiUucu_Q', '2026-10-27 15:08:40', NULL, 'Giáo viên có thể làm việc 8 giờ mỗi ngày ở trường', 'https://vnexpress.net/giao-vien-co-the-lam-viec-8-gio-moi-ngay-o-truong-5137190.html', 17, 18, 'https://vnexpress.net/giao-vien-co-the-lam-viec-8-gio-moi-ngay-o-truong-5137190.html', 'CRAWLER', '2026-10-29 11:07:48.544086', '2026-10-29 11:03:04.1561');
