INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1227, NULL, '2026-10-29 11:03:04.191175', 'Giáo sư về trường Đại học Sao Đỏ sẽ nhận khoản hỗ trợ 550 triệu đồng, còn tiến sĩ là 350 triệu đồng, chưa kể lương, phụ cấp, thu nhập tăng thêm hàng tháng.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/dh-sao-do-1793005812-8502-1793005903.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=FwsUUmcpJQznhlZFNwUpnQ', '2026-10-26 09:23:38', NULL, 'Đại học ''tặng'' 550 triệu đồng mời giáo sư về làm việc', 'https://vnexpress.net/dai-hoc-tang-550-trieu-dong-moi-giao-su-ve-lam-viec-5137064.html', 17, 18, 'https://vnexpress.net/dai-hoc-tang-550-trieu-dong-moi-giao-su-ve-lam-viec-5137064.html', 'CRAWLER', '2026-10-29 11:07:48.572816', '2026-10-29 11:03:04.191175');
