INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1229, NULL, '2026-10-29 11:03:04.199166', 'Trung bình thu nhập của giảng viên Đại học Quốc gia TP HCM (VNUHCM) có sự phân hóa rõ rệt, tùy trường và học vị, học hàm, cao nhất là 115 triệu đồng/tháng.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/6506e4106243454a8c409fc8f8e57b-7833-8764-1793074101.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=SZ4bw_VcfjM3vHu84IGHrw', '2026-10-26 01:03:00', NULL, 'Thu nhập giảng viên ĐH Quốc gia TP HCM cao nhất 115 triệu mỗi tháng', 'https://vnexpress.net/luong-thu-nhap-giang-vien-8-truong-dai-hoc-quoc-gia-tp-hcm-bao-nhieu-5134770.html', 17, 18, 'https://vnexpress.net/luong-thu-nhap-giang-vien-8-truong-dai-hoc-quoc-gia-tp-hcm-bao-nhieu-5134770.html', 'CRAWLER', '2026-10-29 11:07:48.579777', '2026-10-29 11:03:04.199166');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1230, NULL, '2026-10-29 11:03:04.202156', 'Để học sinh mỗi tỉnh, thành thi chung đề cuối kỳ sẽ hạn chế chênh lệch điểm, trả lại giá trị cho học bạ; song đi kèm là nỗi lo về áp lực tổ chức và vai trò của giáo viên bị thu hẹp.', 'https://i1-vnexpress.vnecdn.net/2026/10/24/233a2112-1792817401-3610-1792817615.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=bh6vNH16vjvufsO9qS6BfQ', '2026-10-25 22:59:52', NULL, 'Thi chung đề - ''liều thuốc'' trị lạm phát điểm, học bạ ảo', 'https://vnexpress.net/thi-chung-de-lieu-thuoc-tri-lam-phat-diem-hoc-ba-ao-5136368.html', 17, 18, 'https://vnexpress.net/thi-chung-de-lieu-thuoc-tri-lam-phat-diem-hoc-ba-ao-5136368.html', 'CRAWLER', '2026-10-29 11:07:48.582791', '2026-10-29 11:03:04.202156');
