INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1232, NULL, '2026-10-29 11:03:04.208165', 'Người nước này giành 34 giải Nobel, nhiều nhất châu Á và đứng thứ 5 thế giới. Đây là quốc gia nào?', 'https://i1-vnexpress.vnecdn.net/2026/10/25/soai-1792926298-4078-1792926321.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=mW7B7d93Xfv2EIhRJo6NNg', '2026-10-25 13:00:00', NULL, 'Nước nào sở hữu nhiều giải Nobel nhất châu Á?', 'https://vnexpress.net/nuoc-nao-so-huu-nhieu-giai-nobel-nhat-chau-a-5136684.html', 17, 18, 'https://vnexpress.net/nuoc-nao-so-huu-nhieu-giai-nobel-nhat-chau-a-5136684.html', 'CRAWLER', '2026-10-29 11:07:48.587793', '2026-10-29 11:03:04.208165');
