INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1235, NULL, '2026-10-29 11:03:04.219075', 'Ở tuổi 31, Jamie Beaton nắm trong tay loạt bằng thạc sĩ, tiến sĩ từ nhiều trường Ivy League, và điều hành một hãng tư vấn du học trị giá hơn 600 triệu USD.', 'https://i1-vnexpress.vnecdn.net/2026/10/24/jamie-1792815014-3096-1792815234.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=vN-gAIeGbyjpd9HHyUzSjQ', '2026-10-24 17:02:00', NULL, 'Lấy hàng chục bằng thạc sĩ, tiến sĩ danh tiếng ở tuổi 31', 'https://vnexpress.net/lay-hang-chuc-bang-thac-si-tien-si-danh-tieng-o-tuoi-31-5136160.html', 17, 18, 'https://vnexpress.net/lay-hang-chuc-bang-thac-si-tien-si-danh-tieng-o-tuoi-31-5136160.html', 'CRAWLER', '2026-10-29 11:07:48.596804', '2026-10-29 11:03:04.219075');
