INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1238, NULL, '2026-10-29 11:03:04.230071', 'Ngoài đổi mới tuyển sinh, đào tạo để nâng cao chất lượng, trường Sư phạm trọng điểm còn cần trở thành trung tâm nghiên cứu, đổi mới sáng tạo, theo Phó thủ tướng Lê Tiến Châu.', 'https://i1-vnexpress.vnecdn.net/2026/10/24/wm1-wm1-pho-thu-tuong-chau-1792815-5935-5756-1792819335.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Bc6kfA-z6SLLZUF01L428w', '2026-10-24 07:20:32', NULL, 'Phó thủ tướng: Sứ mệnh của trường Sư phạm không chỉ là đào tạo thầy, cô giỏi', 'https://vnexpress.net/pho-thu-tuong-su-menh-cua-truong-su-pham-khong-chi-la-dao-tao-thay-co-gioi-5136325.html', 17, 18, 'https://vnexpress.net/pho-thu-tuong-su-menh-cua-truong-su-pham-khong-chi-la-dao-tao-thay-co-gioi-5136325.html', 'CRAWLER', '2026-10-29 11:07:48.603777', '2026-10-29 11:03:04.230071');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1239, NULL, '2026-10-29 11:03:04.234065', 'Sau khi sắp xếp, Đã Nẵng có 11 trường có quy mô trên 100 lớp, có nơi điểm lẻ nằm cách trụ sở chính tới 50-70 km.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/dsc06026-jpg-1792755381-4215-1792755412.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=IR5Es-pJ7ACcfM8nilHK8Q', '2026-10-24 02:20:32', NULL, '11 trường có trên 100 lớp sau sắp xếp ở Đà Nẵng', 'https://vnexpress.net/11-truong-co-tren-100-lop-sau-sap-xep-o-da-nang-5136188.html', 17, 18, 'https://vnexpress.net/11-truong-co-tren-100-lop-sau-sap-xep-o-da-nang-5136188.html', 'CRAWLER', '2026-10-29 11:07:48.606797', '2026-10-29 11:03:04.234065');
