INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1241, NULL, '2026-10-29 11:03:04.243063', 'Thí sinh đăng ký xét tuyển đại học từ tháng 7/2027, các trường phải công bố phương án tuyển sinh trước 31/12 để các em chủ động học và ôn thi.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/wm1-wm1-dsc05298-1792762947-5243-1792763000.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=En0Iina3jIrHD_mmlRJZCw', '2026-10-23 13:59:11', NULL, 'Công bố lịch xét tuyển đại học năm 2027', 'https://vnexpress.net/lich-tuyen-sinh-dai-hoc-2027-chi-tiet-cap-nhat-nhat-tu-bo-giao-duc-va-dao-tao-5136204.html', 17, 18, 'https://vnexpress.net/lich-tuyen-sinh-dai-hoc-2027-chi-tiet-cap-nhat-nhat-tu-bo-giao-duc-va-dao-tao-5136204.html', 'CRAWLER', '2026-10-29 11:07:48.616805', '2026-10-29 11:03:04.243063');
