INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1249, NULL, '2026-10-29 11:03:04.282062', 'Đại học IE (Tây Ban Nha) và Đại học California, Berkeley (Mỹ) cùng mở chương trình trải nghiệm công nghệ, hướng dẫn để sinh viên dùng AI nhưng không đánh mất khả năng phán đoán.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/ieucb-1792685454-1318-1792685496.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Bbu8Xns_4VReddx-paOwCw', '2026-10-22 16:58:19', NULL, 'Hai đại học hàng đầu bắt tay dạy sinh viên ứng dụng AI', 'https://vnexpress.net/hai-dai-hoc-hang-dau-bat-tay-day-sinh-vien-ung-dung-ai-5135800.html', 17, 18, 'https://vnexpress.net/hai-dai-hoc-hang-dau-bat-tay-day-sinh-vien-ung-dung-ai-5135800.html', 'CRAWLER', '2026-10-29 11:07:48.647794', '2026-10-29 11:03:04.282062');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1250, NULL, '2026-10-29 11:03:04.287061', 'Với độ pH khoảng 0,9-1,5, loại quả này có độ axit cao hơn nhiều so với các loại chanh, dứa, được mệnh danh chua nhất thế giới.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/ignartonosbgbilimbi76132871920-8421-7583-1792663957.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=uPZXe3OiF4rCr-3V8Ov7JQ', '2026-10-22 13:05:38', NULL, 'Quả nào ''chua nhất thế giới''?', 'https://vnexpress.net/qua-nao-chua-nhat-the-gioi-5135705.html', 17, 18, 'https://vnexpress.net/qua-nao-chua-nhat-the-gioi-5135705.html', 'CRAWLER', '2026-10-29 11:07:48.650797', '2026-10-29 11:03:04.287061');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1251, NULL, '2026-10-29 11:03:04.29106', 'Phụ huynh, giáo viên đồng loạt phản đối đề xuất đưa câu hỏi tự luận vào đề thi đại học, do lo ngại khó chấm điểm, tốn kém để luyện thi.', 'https://i1-vnexpress.vnecdn.net/2026/10/15/d50csat-1792057153-9968-1792057178.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=tQrmlaffaJnE0oknrDouvQ', '2026-10-22 09:05:56', NULL, 'Làn sóng phản đối đưa câu tự luận vào đề thi đại học', 'https://vnexpress.net/lan-song-phan-doi-dua-cau-tu-luan-vao-de-thi-dai-hoc-5132581.html', 17, 18, 'https://vnexpress.net/lan-song-phan-doi-dua-cau-tu-luan-vao-de-thi-dai-hoc-5132581.html', 'CRAWLER', '2026-10-29 11:07:48.653797', '2026-10-29 11:03:04.29106');
