INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1268, NULL, '2026-10-29 11:03:04.419657', 'Em sống và làm việc tại TP HCM, công việc ổn định, có những sở thích riêng và còn nhiều điều muốn học hỏi, trải nghiệm trong cuộc sống.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/GeminiGeneratedImagefr60x8fr60-5358-8787-1793173408.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=C0S-jr0gTWAj2uKMd2SeCQ', '2026-10-29 02:23:58', NULL, 'Tìm người cùng em viết tiếp những năm tháng đẹp nhất', 'https://vnexpress.net/tim-nguoi-cung-em-viet-tiep-nhung-nam-thang-dep-nhat-5137798.html', 10, 9, 'https://vnexpress.net/tim-nguoi-cung-em-viet-tiep-nhung-nam-thang-dep-nhat-5137798.html', 'CRAWLER', '2026-10-29 11:03:04.419657', '2026-10-29 11:03:04.419657');
