INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1260, NULL, '2026-10-29 11:03:04.326659', 'Giữa lúc nhiều trường lúng túng, cắt giảm các tiết STEM, Tiếng Anh liên kết, Vụ trưởng Giáo dục phổ thông nói không yêu cầu việc này, song cần rà soát, chấm dứt nếu không phù hợp.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/wm1-wm1-233a2021-1792551697-2979-1792551797.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=XJyU3qRkWgP9XvKQsfPPgQ', '2026-10-21 03:25:37', NULL, 'Bộ GD và ĐT: Không yêu cầu các trường dừng chương trình liên kết', 'https://vnexpress.net/bo-giao-duc-giai-thich-thong-tu-85-ve-chuong-trinh-tang-cuong-lien-ket-5134956.html', 17, 18, 'https://vnexpress.net/bo-giao-duc-giai-thich-thong-tu-85-ve-chuong-trinh-tang-cuong-lien-ket-5134956.html', 'CRAWLER', '2026-10-29 11:07:48.682795', '2026-10-29 11:03:04.326659');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1261, NULL, '2026-10-29 11:03:04.331658', 'Khi cô giáo đang giảng bài, nam sinh trường THPT Mạc Đĩnh Chi lao tới, đấm và đánh vào đầu, khiến cô bị thương, chảy nhiều máu.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/3ff35185-a459be02e14bab8eed-jf-7334-3673-1792549472.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Bbs89R-4uuOO-wCk-U3wUg', '2026-10-21 02:05:26', NULL, 'Nam sinh hành hung cô giáo trên bục giảng', 'https://vnexpress.net/nam-sinh-thpt-mac-dinh-chi-danh-co-giao-chay-mau-tren-buc-giang-5134824.html', 17, 18, 'https://vnexpress.net/nam-sinh-thpt-mac-dinh-chi-danh-co-giao-chay-mau-tren-buc-giang-5134824.html', 'CRAWLER', '2026-10-29 11:07:48.68579', '2026-10-29 11:03:04.331658');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1262, NULL, '2026-10-29 11:03:04.334656', 'Khoảng 98% trong 14.200 người du học bằng kinh phí nhà nước là giảng viên, sinh viên, vướng mắc chủ yếu là mức hỗ trợ không bù nổi chi phí sinh hoạt thực tế.', 'https://i1-vnexpress.vnecdn.net/2026/10/19/1787736463001afdec06d763b75fe7-9949-9658-1792426752.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=45qaGCRzs1v8lDexazN32Q', '2026-10-20 23:23:40', NULL, 'Hơn 14.200 người du học bằng ngân sách trong 5 năm', 'https://vnexpress.net/hon-14-200-nguoi-du-hoc-bang-ngan-sach-trong-5-nam-5130997.html', 17, 18, 'https://vnexpress.net/hon-14-200-nguoi-du-hoc-bang-ngan-sach-trong-5-nam-5130997.html', 'CRAWLER', '2026-10-29 11:07:48.688808', '2026-10-29 11:03:04.334656');
