INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1264, NULL, '2026-10-29 11:03:04.351657', 'Nhiều nữ sinh lúng túng, thậm chí sợ hãi khi kinh nguyệt xuất hiện, cũng không biết đây là dấu hiệu cơ thể bắt đầu có khả năng sinh sản, theo chuyên gia.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/diana-unicharm-1792583223-9093-1792583242.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=7Abp_H8ZU1D0Gx0_4hsVug', '2026-10-21 11:47:46', NULL, 'Nữ sinh ''mù mờ'', lúng túng về dấu hiệu dậy thì', 'https://vnexpress.net/nu-sinh-mu-mo-lung-tung-ve-dau-hieu-day-thi-5134593.html', 17, 18, 'https://vnexpress.net/nu-sinh-mu-mo-lung-tung-ve-dau-hieu-day-thi-5134593.html', 'CRAWLER', '2026-10-29 11:07:48.693782', '2026-10-29 11:03:04.351657');
