INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1310, NULL, '2026-10-29 11:03:04.689362', 'Cựu tiền đạo Thierry Henry khẳng định không có ý xúc phạm Lamine Yamal, Harry Kane hay bạn dẫn Kate Scott, sau khi bị chỉ trích vì những câu đùa tại gala Quả Bóng Vàng 2026.', 'https://i1-thethao.vnecdn.net/2026/10/29/a-nh-ma-n-hi-nh-lu-c-179322201-6786-1645-1793222067.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Ud_5o_eBVvbG5v2tJdaqZQ', '2026-10-28 22:57:02', NULL, 'Thierry Henry đáp trả chỉ trích về cách dẫn gala Quả Bóng Vàng', 'https://vnexpress.net/thierry-henry-dap-tra-chi-trich-ve-cach-dan-gala-qua-bong-vang-5138097.html', 18, 19, 'https://vnexpress.net/thierry-henry-dap-tra-chi-trich-ve-cach-dan-gala-qua-bong-vang-5138097.html', 'CRAWLER', '2026-10-29 11:07:49.047835', '2026-10-29 11:07:49.047835');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1311, NULL, '2026-10-29 11:03:04.69238', 'Trong thời đại Roger Federer, Rafael Nadal và Novak Djokovic thống trị, Stan Wawrinka vẫn giành ba Grand Slam, cả ba lần đều đánh bại tay vợt số một thế giới ở chung kết.', 'https://i1-thethao.vnecdn.net/2026/10/28/rolandgarrosnguoiphaptieptucda-4383-1206-1793187483.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=zBZOTz8fKmAzRw_9N93cyA', '2026-10-28 22:39:07', NULL, 'Stan Wawrinka - kẻ phá vỡ trật tự ''Big 3''', 'https://vnexpress.net/stan-wawrinka-ke-pha-vo-trat-tu-big-3-5138032.html', 18, 19, 'https://vnexpress.net/stan-wawrinka-ke-pha-vo-trat-tu-big-3-5138032.html', 'CRAWLER', '2026-10-29 11:07:49.050796', '2026-10-29 11:07:49.050796');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1312, NULL, '2026-10-29 11:03:04.700381', 'Thể Công không thắng 7 trận liền sau khi thua FC Seoul 0-5 ở lượt ba bảng E AFC Champions League Two 2026-2027 tối 28/10.', 'https://i1-thethao.vnecdn.net/2026/10/28/1793191589803d3f291cd82ea8400f-1296-8112-1793197838.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=fIA8mIGkoLOdevgbCfmN6Q', '2026-10-28 14:31:58', NULL, 'Thể Công thảm bại ở Cup châu Á', 'https://vnexpress.net/the-cong-tham-bai-o-cup-chau-a-5138052.html', 18, 19, 'https://vnexpress.net/the-cong-tham-bai-o-cup-chau-a-5138052.html', 'CRAWLER', '2026-10-29 11:07:49.066285', '2026-10-29 11:03:04.700381');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1300, NULL, '2026-10-29 11:03:04.5747', 'Tiền đạo Kylian Mbappe và Ousmane Dembele bị chuyên gia nghi thức chỉ trích vì không đứng dậy bắt tay Harry Kane, khi ngôi sao người Anh đến chào hỏi tại gala Quả Bóng Vàng 2026.', 'https://i1-thethao.vnecdn.net/2026/10/29/a-nh-ma-n-hi-nh-lu-c-179322025-9646-9025-1793220409.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=ovQAqDp37aoxrvgJ9NN2-g', '2026-10-28 23:04:40', NULL, 'Mbappe bị chê thiếu tôn trọng Kane ở gala Quả Bóng Vàng', 'https://vnexpress.net/mbappe-bi-che-thieu-ton-trong-kane-o-gala-qua-bong-vang-5138096.html', 18, 9, 'https://vnexpress.net/mbappe-bi-che-thieu-ton-trong-kane-o-gala-qua-bong-vang-5138096.html', 'CRAWLER', '2026-10-29 11:07:49.043799', '2026-10-29 11:07:49.043799');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1313, NULL, '2026-10-29 11:03:04.70347', 'HLV Michael Carrick và Bruno Fernandes đã nói chuyện riêng để giải quyết bất đồng tại Man Utd, mở đường cho thủ quân trở lại đội hình chính ở trận gặp Chelsea tại Ngoại hạng Anh cuối tuần này.', 'https://i1-thethao.vnecdn.net/2026/10/28/man-utd-carrick-1793190561-6294-1793190769.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=56vOcEWF8p1Yg4-ZfjCgGA', '2026-10-28 12:34:48', NULL, 'Carrick hòa giải với Fernandes', 'https://vnexpress.net/carrick-hoa-giai-voi-fernandes-5138042.html', 18, 19, 'https://vnexpress.net/carrick-hoa-giai-voi-fernandes-5138042.html', 'CRAWLER', '2026-10-29 11:07:49.070634', '2026-10-29 11:03:04.70347');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1314, NULL, '2026-10-29 11:03:04.707462', 'Stan Wawrinka khép lại sự nghiệp quần vợt kéo dài 24 năm sau khi thua Jiri Lehecka 5-7, 6-7(2) ở vòng một Swiss Indoors Basel ngày 27/10.', 'https://i1-thethao.vnecdn.net/2026/10/28/ap26300742879576-1793178840-8076-1793179782.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=d6gQNybspv2lievhHWHSTA', '2026-10-28 10:52:06', NULL, 'Wawrinka giải nghệ sau 24 năm thi đấu chuyên nghiệp', 'https://vnexpress.net/wawrinka-giai-nghe-sau-24-nam-thi-dau-chuyen-nghiep-5137988.html', 18, 19, 'https://vnexpress.net/wawrinka-giai-nghe-sau-24-nam-thi-dau-chuyen-nghiep-5137988.html', 'CRAWLER', '2026-10-29 11:07:49.074685', '2026-10-29 11:03:04.707462');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1315, NULL, '2026-10-29 11:03:04.711371', 'Những cô gái đeo thùng bia nặng 15 kg, liên tục lên xuống các bậc khán đài để phục vụ người hâm mộ đã trở thành nét văn hóa đặc trưng của bóng chày Nhật Bản, nhưng cũng gây tranh cãi vì những hành vi quá khích từ khách hàng.', 'https://i1-thethao.vnecdn.net/2026/10/28/download-1793178446-8860-1793179281.webp?w=1200&h=0&q=100&dpr=1&fit=crop&s=Q_AlCiSkTNznWfGOgQRoQg', '2026-10-28 09:22:46', NULL, 'Những cô gái bán bia trên khán đài bóng chày Nhật Bản', 'https://vnexpress.net/nhung-co-gai-ban-bia-tren-khan-dai-bong-chay-nhat-ban-5137980.html', 18, 19, 'https://vnexpress.net/nhung-co-gai-ban-bia-tren-khan-dai-bong-chay-nhat-ban-5137980.html', 'CRAWLER', '2026-10-29 11:07:49.080685', '2026-10-29 11:03:04.711371');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1316, NULL, '2026-10-29 11:03:04.715464', 'Câu nói đùa trong một trò chơi của Kylian Mbappe gây nên làn sóng phẫn nộ ở Trung Quốc, khiến ngôi sao của Real Madrid mất ít nhất ba hợp đồng quảng cáo, đồng thời các trận đấu của La Liga cũng bị cắt sóng ở quốc gia tỷ dân.', 'https://i1-thethao.vnecdn.net/2026/10/28/4d088a3ff95242dcb0236ce0e74007-8622-3107-1793172503.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=zxTyNfd3WoCsP7Xy-XNiSQ', '2026-10-28 07:29:03', NULL, 'Mbappe bị tẩy chay ở Trung Quốc', 'https://vnexpress.net/mbappe-bi-tay-chay-o-trung-quoc-5137890.html', 18, 19, 'https://vnexpress.net/mbappe-bi-tay-chay-o-trung-quoc-5137890.html', 'CRAWLER', '2026-10-29 11:07:49.084686', '2026-10-29 11:03:04.715464');
