INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1323, NULL, '2026-10-29 11:03:04.742363', 'Sau thất bại trước Harry Kane năm nay, tiền đạo Barca và đội tuyển Tây Ban Nha Lamine Yamal đăng thông điệp lấy lại niềm tin chiến thắng trong cuộc đua Quả Bóng Vàng.', 'https://i1-thethao.vnecdn.net/2026/10/28/yamal5jpg1-1793149829-5970-1793149923.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=-t-4-1AbwWXk8JdDWCfw7A', '2026-10-28 01:31:09', NULL, 'Yamal: ''Quả Bóng Vàng sẽ đến thôi''', 'https://vnexpress.net/yamal-qua-bong-vang-se-den-thoi-5137648.html', 18, 19, 'https://vnexpress.net/yamal-qua-bong-vang-se-den-thoi-5137648.html', 'CRAWLER', '2026-10-29 11:07:49.116913', '2026-10-29 11:03:04.742363');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1324, NULL, '2026-10-29 11:03:04.747362', 'Mounir Nasraoui, bố của Lamine Yamal, bị cáo buộc nhổ nước bọt vào mặt một nữ nhân viên quán cà phê, đánh người và dọa ném ghế tại sân bay Barcelona.', 'https://i1-thethao.vnecdn.net/2026/10/28/bo-yamal-1793147899-3585-1793148001.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=kwVSJCuvBaKDqM2QfbsNzQ', '2026-10-28 01:25:25', NULL, 'Bố Yamal gây náo loạn ở sân bay', 'https://vnexpress.net/bo-yamal-gay-nao-loan-o-san-bay-5137672.html', 18, 19, 'https://vnexpress.net/bo-yamal-gay-nao-loan-o-san-bay-5137672.html', 'CRAWLER', '2026-10-29 11:07:49.120913', '2026-10-29 11:03:04.747362');
