INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1335, NULL, '2026-10-29 11:03:04.790997', 'HLV Michael Carrick tạm giữ ghế tại Man Utd sau cuộc họp của lãnh đạo đội bóng ngày 26/10, một ngày sau trận thua Bournemouth 0-3.', 'https://i1-thethao.vnecdn.net/2026/10/27/ap26298580654812-1793072003-4183-1793072030.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=d_-AHGkwhxjpVPvMaBw41Q', '2026-10-27 04:47:04', NULL, 'Carrick tiếp tục dẫn dắt Man Utd sau cuộc họp khẩn', 'https://vnexpress.net/carrick-tiep-tuc-dan-dat-man-utd-sau-cuoc-hop-khan-5137351.html', 18, 19, 'https://vnexpress.net/carrick-tiep-tuc-dan-dat-man-utd-sau-cuoc-hop-khan-5137351.html', 'CRAWLER', '2026-10-29 11:07:49.168346', '2026-10-29 11:03:04.790997');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1336, NULL, '2026-10-29 11:03:04.797001', 'Thay vì tranh cãi như nhiều kỳ gần đây, tiền đạo Harry Kane nhận nhiều lời tán dương và chúc mừng sau khi trở thành cầu thủ Anh đầu tiên trong 25 năm giành Quả Bóng Vàng.', 'https://i1-thethao.vnecdn.net/2026/10/27/a-nh-ma-n-hi-nh-lu-c-179307373-9459-5935-1793073948.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=RmAXNrh-42tTAIWTlb0fEA', '2026-10-27 04:37:38', NULL, 'Kane được ngợi ca sau chiến thắng ở Quả Bóng Vàng 2026', 'https://vnexpress.net/kane-duoc-ngoi-ca-sau-chien-thang-o-qua-bong-vang-2026-5137367.html', 18, 19, 'https://vnexpress.net/kane-duoc-ngoi-ca-sau-chien-thang-o-qua-bong-vang-2026-5137367.html', 'CRAWLER', '2026-10-29 11:07:49.171326', '2026-10-29 11:03:04.797001');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1337, NULL, '2026-10-29 11:03:04.801994', 'Trả lời kênh L''Équipe TV sau lễ trao giải Quả Bóng Vàng 2026 tối 26/10, Tổng biên tập France Football Vincent Garcia hé lộ đôi điều về cuộc đua sít sao giữa Harry Kane và Kylian Mbappe.', 'https://i1-thethao.vnecdn.net/2026/10/27/screenshot-1793075204-9899-1793075211.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=N4N8z1vsRiuzZ1r5bpU78Q', '2026-10-27 04:26:51', NULL, 'Tổng biên tập France Football: ''Mbappe đã có lúc dẫn đầu cuộc đua''', 'https://vnexpress.net/tong-bien-tap-france-football-mbappe-da-co-luc-dan-dau-cuoc-dua-5137369.html', 18, 19, 'https://vnexpress.net/tong-bien-tap-france-football-mbappe-da-co-luc-dan-dau-cuoc-dua-5137369.html', 'CRAWLER', '2026-10-29 11:07:49.174341', '2026-10-29 11:03:04.801994');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1338, NULL, '2026-10-29 11:03:04.805984', 'Từng bị Arsenal loại khỏi học viện, trải qua bốn lần cho mượn và hơn một thập niên không danh hiệu, Harry Kane cuối cùng chạm đến đỉnh cao bóng đá thế giới khi đoạt Quả Bóng Vàng 2026 ở tuổi 33.', 'https://i1-thethao.vnecdn.net/2026/10/27/kane-1793074012-8035-1793074025.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=xFZ_2cZ7R-dXnj803ETxLA', '2026-10-27 04:07:43', NULL, 'Harry Kane - từ người không danh hiệu đến Quả Bóng Vàng', 'https://vnexpress.net/harry-kane-tu-nguoi-khong-danh-hieu-den-qua-bong-vang-5137372.html', 18, 19, 'https://vnexpress.net/harry-kane-tu-nguoi-khong-danh-hieu-den-qua-bong-vang-5137372.html', 'CRAWLER', '2026-10-29 11:07:49.176326', '2026-10-29 11:03:04.805984');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1339, NULL, '2026-10-29 11:03:04.809981', 'Harry Kane nghẹn ngào khi gửi lời cảm ơn đến gia đình, các đồng đội và ban huấn luyện cả trong quá khứ lẫn hiện tại, sau khi đoạt Quả Bóng Vàng 2026 tại Nhà hát London Palladium.', 'https://i1-thethao.vnecdn.net/2026/10/27/Screenshot20261027091211-17930-4572-3961-1793067752.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=4NkGoTCyylp3jjy0Or1sBw', '2026-10-27 03:08:18', NULL, 'Harry Kane: ''Hy vọng câu chuyện của tôi truyền cảm hứng cho tất cả''', 'https://vnexpress.net/harry-kane-hy-vong-cau-chuyen-cua-toi-truyen-cam-hung-cho-tat-ca-5137295.html', 18, 19, 'https://vnexpress.net/harry-kane-hy-vong-cau-chuyen-cua-toi-truyen-cam-hung-cho-tat-ca-5137295.html', 'CRAWLER', '2026-10-29 11:07:49.180354', '2026-10-29 11:03:04.809981');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1340, NULL, '2026-10-29 11:03:04.816147', 'Hai giải giao hữu của đội tuyển quốc gia và U23 trong tháng 11 là cơ hội để HLV Kim Sang-sik thử nghiệm, đánh giá lực lượng trước thềm Asian Cup 2027.', 'https://i1-thethao.vnecdn.net/2026/10/27/don-jpg-1793084353-8425-1793084528.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=wlIbdv-7Yp7z5kXEq4fwGQ', '2026-10-27 07:10:15', NULL, 'HLV Kim Sang-sik thử quân cho Asian Cup 2027', 'https://vnexpress.net/hlv-kim-sang-sik-thu-quan-cho-asian-cup-2027-5137439.html', 18, 19, 'https://vnexpress.net/hlv-kim-sang-sik-thu-quan-cho-asian-cup-2027-5137439.html', 'CRAWLER', '2026-10-29 11:07:49.183359', '2026-10-29 11:03:04.816147');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1342, NULL, '2026-10-29 11:03:04.826079', 'Dù vô địch World Cup 2026 cùng Tây Ban Nha và ghi 25 bàn cho Barca mùa trước, tiền đạo Lamine Yamal chỉ đứng thứ ba trong cuộc bầu chọn Quả Bóng Vàng, sau Harry Kane và Kylian Mbappe.', 'https://i1-thethao.vnecdn.net/2026/10/27/yamal-1793066954-9538-1793066964.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=zpe6IQxEl__28iHtwK4V7A', '2026-10-27 02:01:55', NULL, 'Vì sao Lamine Yamal tiếp tục lỡ Quả Bóng Vàng?', 'https://vnexpress.net/vi-sao-lamine-yamal-tiep-tuc-lo-qua-bong-vang-5137268.html', 18, 19, 'https://vnexpress.net/vi-sao-lamine-yamal-tiep-tuc-lo-qua-bong-vang-5137268.html', 'CRAWLER', '2026-10-29 11:07:49.188359', '2026-10-29 11:03:04.826079');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1343, NULL, '2026-10-29 11:03:04.832455', 'Lễ trao Quả Bóng Vàng 2026 tại London tối 26/10 bị chỉ trích vì tổ chức thiếu chuyên nghiệp, kéo dài lê thê, liên tục ngắt quãng quảng cáo và khiến khán giả la ó.', 'https://i1-thethao.vnecdn.net/2026/10/27/a-nh-ma-n-hi-nh-lu-c-179306078-9795-1792-1793060938.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=J8uoUCVweYocx_F22R_V7A', '2026-10-27 00:59:57', NULL, 'Những ''hạt sạn'' ở Gala Quả Bóng Vàng 2026', 'https://vnexpress.net/nhung-hat-san-o-gala-qua-bong-vang-2026-5137237.html', 18, 19, 'https://vnexpress.net/nhung-hat-san-o-gala-qua-bong-vang-2026-5137237.html', 'CRAWLER', '2026-10-29 11:07:49.190328', '2026-10-29 11:03:04.832455');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1344, NULL, '2026-10-29 11:03:04.838083', 'Tiền đạo Lamine Yamal lần thứ ba liên tiếp đoạt giải Kopa dành cho cầu thủ U21 hay nhất thế giới, nhưng cho rằng đồng đội Pau Cubarsi mới là người xứng đáng được vinh danh.', 'https://i1-thethao.vnecdn.net/2026/10/27/a-nh-ma-n-hi-nh-lu-c-179306216-6379-9711-1793062233.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Gtcyul1LDqD27pClj3K-8A', '2026-10-27 00:55:20', NULL, 'Yamal: ''Đáng lẽ giải Kopa phải thuộc về Cubarsi''', 'https://vnexpress.net/yamal-dang-le-giai-kopa-phai-thuoc-ve-cubarsi-5137247.html', 18, 19, 'https://vnexpress.net/yamal-dang-le-giai-kopa-phai-thuoc-ve-cubarsi-5137247.html', 'CRAWLER', '2026-10-29 11:07:49.19333', '2026-10-29 11:03:04.838083');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1345, NULL, '2026-10-29 11:03:04.842981', 'Trang web của tạp chí France Football bất ngờ đăng ba bài viết công bố Lamine Yamal, Kylian Mbappe và Harry Kane giành Quả Bóng Vàng 2026, chỉ vài giờ trước lễ trao giải.', 'https://i1-thethao.vnecdn.net/2026/10/27/6adf98051159e-1793059417-6381-1793059532.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=2z35pYZ5J_hciToE2W9jIQ', '2026-10-27 00:10:46', NULL, 'France Football gây xôn xao vì công bố ba người đoạt Quả Bóng Vàng 2026', 'https://vnexpress.net/france-football-gay-xon-xao-vi-cong-bo-ba-nguoi-doat-qua-bong-vang-2026-5137232.html', 18, 19, 'https://vnexpress.net/france-football-gay-xon-xao-vi-cong-bo-ba-nguoi-doat-qua-bong-vang-2026-5137232.html', 'CRAWLER', '2026-10-29 11:07:49.197324', '2026-10-29 11:03:04.842981');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1346, NULL, '2026-10-29 11:03:04.849088', 'Tiền đạo 33 tuổi người Anh Harry Kane lần đầu giành Quả Bóng Vàng, khi vượt qua Kylian Mbappe và Lamine Yamal trong lễ trao năm 2026 tại London.', 'https://i1-thethao.vnecdn.net/2026/10/27/kane-jpg-1793055388-2811-1793055399.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=GYKZcROSrz-ytq2Q8mbO-Q', '2026-10-26 15:00:00', NULL, 'Harry Kane đoạt Quả Bóng Vàng 2026', 'https://vnexpress.net/truc-tiep-le-trao-qua-bong-vang-2026-5137134-tong-thuat.html', 18, 19, 'https://vnexpress.net/truc-tiep-le-trao-qua-bong-vang-2026-5137134-tong-thuat.html', 'CRAWLER', '2026-10-29 11:07:49.200325', '2026-10-29 11:03:04.849088');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1348, NULL, '2026-10-29 11:03:04.859983', 'Việc Bruno Fernandes, Lisandro Martinez công khai bất đồng cùng phong độ bạc nhược của cả tập thể cho thấy HLV Michael Carrick đang đối mặt khủng hoảng quyền lực tại Man Utd, nơi sự mềm mỏng của ông không còn tác dụng.', 'https://i1-thethao.vnecdn.net/2026/10/26/carrick-bournemouth-1793001432-2776-1793001901.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Ig0Lrazafr9vtJhPl4a4hA', '2026-10-26 09:59:45', NULL, 'Vì sao cầu thủ Man Utd không còn nghe lời Carrick?', 'https://vnexpress.net/vi-sao-cau-thu-man-utd-khong-con-nghe-loi-carrick-5137050.html', 18, 19, 'https://vnexpress.net/vi-sao-cau-thu-man-utd-khong-con-nghe-loi-carrick-5137050.html', 'CRAWLER', '2026-10-29 11:07:49.206326', '2026-10-29 11:03:04.859983');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1349, NULL, '2026-10-29 11:03:04.866086', 'Cuộc đua Quả Bóng Vàng 2026 không chỉ được quyết định bằng màn trình diễn trên sân, mà còn chịu ảnh hưởng từ những chiến dịch truyền thông, sức mạnh mạng xã hội và lợi ích thương mại của các CLB.', 'https://i1-thethao.vnecdn.net/2026/10/25/mbappe-1792908431-1121-1792908442.webp?w=1200&h=0&q=100&dpr=1&fit=crop&s=sFlQXY3PMy_kZYKEJvYGDw', '2026-10-26 07:33:25', NULL, 'Quả Bóng Vàng và cuộc đua khốc liệt cả trong lẫn ngoài sân cỏ', 'https://vnexpress.net/qua-bong-vang-va-cuoc-dua-khoc-liet-ca-trong-lan-ngoai-san-co-5136596.html', 18, 19, 'https://vnexpress.net/qua-bong-vang-va-cuoc-dua-khoc-liet-ca-trong-lan-ngoai-san-co-5136596.html', 'CRAWLER', '2026-10-29 11:07:49.209326', '2026-10-29 11:03:04.866086');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1350, NULL, '2026-10-29 11:03:04.871076', 'Theo báo Tây Ban Nha AS, cách tiếp cận trận đấu và các phương án nhân sự của HLV Jose Mourinho đã phát huy hiệu quả tuyệt đối, giúp Real thắng thuyết phục Barca ở vòng 10 La Liga ngày 25/10.', 'https://i1-thethao.vnecdn.net/2026/10/26/ap26298802656353-1792999356-4016-1792999543.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=w3g1NVDwLrxOuiDv2BtF5g', '2026-10-26 07:25:43', NULL, 'Mưu lược của Mourinho ở El Clasico', 'https://vnexpress.net/muu-luoc-cua-mourinho-o-el-clasico-5136955.html', 18, 19, 'https://vnexpress.net/muu-luoc-cua-mourinho-o-el-clasico-5136955.html', 'CRAWLER', '2026-10-29 11:07:49.213349', '2026-10-29 11:03:04.871076');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1351, NULL, '2026-10-29 11:03:04.876987', 'Gia đình Mellerio, chủ sở hữu thương hiệu kim hoàn lâu đời nhất thế giới, nắm giữ một trong những bí mật lớn nhất bóng đá: danh tính chủ nhân Quả Bóng Vàng trước khi giải thưởng được công bố.', 'https://i1-thethao.vnecdn.net/2026/10/25/Mellerio-1792945689-8807-1792945823.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Y4AH-wCuuADj95S_iYCkBA', '2026-10-26 07:21:52', NULL, 'Gia tộc 500 năm tuổi nắm giữ bí mật Quả Bóng Vàng', 'https://vnexpress.net/gia-toc-500-nam-tuoi-nam-giu-bi-mat-qua-bong-vang-5136723.html', 18, 19, 'https://vnexpress.net/gia-toc-500-nam-tuoi-nam-giu-bi-mat-qua-bong-vang-5136723.html', 'CRAWLER', '2026-10-29 11:07:49.216341', '2026-10-29 11:03:04.876987');
