INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1362, NULL, '2026-10-29 11:03:05.029246', 'Bộ Tài chính đề xuất giảm 30-70% tiền phạt chậm nộp hồ sơ khai thuế cho doanh nghiệp đã ngừng hoạt động nhưng chưa đóng mã số thuế.', 'https://i1-kinhdoanh.vnecdn.net/2026/10/29/HUY6982-1793210004-2759-1793210193.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=bi_Lmd5wRc4iySpQ3gz9Jg', '2026-10-29 03:00:00', NULL, 'Đề xuất giảm tới 70% phạt chậm nộp tờ khai thuế cho doanh nghiệp ngưng hoạt động', 'https://vnexpress.net/de-xuat-giam-toi-70-phat-cham-nop-to-khai-thue-cho-doanh-nghiep-ngung-hoat-dong-5138089.html', 19, 20, 'https://vnexpress.net/de-xuat-giam-toi-70-phat-cham-nop-to-khai-thue-cho-doanh-nghiep-ngung-hoat-dong-5138089.html', 'CRAWLER', '2026-10-29 11:03:05.029246', '2026-10-29 11:03:05.029246');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1353, NULL, '2026-10-29 11:03:04.889086', 'Cristiano Ronaldo dẫn Lionel Messi 460-450 điểm trong bảng thống kê lịch sử Quả Bóng Vàng, theo nghiên cứu quy đổi kết quả bầu chọn của 69 kỳ trao giải từ năm 1956 đến 2025.', 'https://i1-thethao.vnecdn.net/2026/10/25/ronaldo-1792943554-6269-1792943837.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=UiUZzSP7BkmIKL2lCaQ5fg', '2026-10-26 04:40:52', NULL, 'Ronaldo vượt Messi ở bảng điểm lịch sử Quả Bóng Vàng', 'https://vnexpress.net/ronaldo-vuot-messi-o-bang-diem-lich-su-qua-bong-vang-5136721.html', 18, 19, 'https://vnexpress.net/ronaldo-vuot-messi-o-bang-diem-lich-su-qua-bong-vang-5136721.html', 'CRAWLER', '2026-10-29 11:07:49.222345', '2026-10-29 11:03:04.889086');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1354, NULL, '2026-10-29 11:03:04.894983', 'Việc HLV Michael Carrick cố tình để Bruno Fernandes dự bị suốt trận Man Utd thua Bournemouth 0-3 ở vòng 8 Ngoại hạng Anh đang gây ra nhiều tranh cãi.', 'https://i1-thethao.vnecdn.net/2026/10/26/carrick-vs-fernandes-179297748-3305-9037-1792977822.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Md4qJhiFWAqbOxTioVdvwA', '2026-10-26 04:21:35', NULL, 'Carrick cố tình làm bẽ mặt Fernandes?', 'https://vnexpress.net/carrick-co-tinh-lam-be-mat-fernandes-5136775.html', 18, 19, 'https://vnexpress.net/carrick-co-tinh-lam-be-mat-fernandes-5136775.html', 'CRAWLER', '2026-10-29 11:07:49.227329', '2026-10-29 11:03:04.894983');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1355, NULL, '2026-10-29 11:03:04.900345', 'Man Utd rục rịch thay Michael Carrick, Arsenal tìm về với "bóng chết" hay Man City đứt mạch toàn thắng... là những điểm đáng chú ý tại Ngoại hạng Anh tuần qua.', 'https://i1-thethao.vnecdn.net/2026/10/26/A-nh-ma-n-hi-nh-2026-10-26-lu-c-04-1792963817.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=NPMF486dqA7KBv3EqxM6iw', '2026-10-26 03:43:42', NULL, '8 điểm nhấn vòng 8 Ngoại hạng Anh', 'https://vnexpress.net/8-diem-nhan-vong-8-ngoai-hang-anh-5136737.html', 18, 19, 'https://vnexpress.net/8-diem-nhan-vong-8-ngoai-hang-anh-5136737.html', 'CRAWLER', '2026-10-29 11:07:49.230358', '2026-10-29 11:03:04.900345');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1356, NULL, '2026-10-29 11:03:04.905344', 'Thua Bournemouth 0-3 ở vòng 8 Ngoại hạng Anh, Man Utd trải qua khởi đầu tệ nhất trong 40 năm, đồng thời nối dài hàng loạt thống kê đáng quên về thành tích, khả năng phòng ngự và phong độ sân nhà.', 'https://i1-thethao.vnecdn.net/2026/10/26/a-nh-ma-n-hi-nh-lu-c-179298605-8714-2462-1792986170.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=1CzWda6929tlx3YFus7fKw', '2026-10-26 03:50:16', NULL, 'Những con số đáng báo động của Man Utd', 'https://vnexpress.net/nhung-con-so-dang-bao-dong-cua-man-utd-5136880.html', 18, 19, 'https://vnexpress.net/nhung-con-so-dang-bao-dong-cua-man-utd-5136880.html', 'CRAWLER', '2026-10-29 11:07:49.233347', '2026-10-29 11:03:04.905344');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1357, NULL, '2026-10-29 11:03:04.911243', 'Với cú đúp hạ Barca 2-1 ở El Clasico ngày 25/10, tiền đạo Kylian Mbappe có tròn 100 bàn cho Real sau 116 trận trên mọi đấu trường, qua đó gia nhập nhóm cầu thủ đạt mốc này nhanh nhất lịch sử bóng đá hiện đại.', 'https://i1-thethao.vnecdn.net/2026/10/26/ap26298743027368-1792986159-3080-1792986167.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=XI_Av1an8X3CSSU057DegQ', '2026-10-26 03:44:00', NULL, 'Mbappe chạm mốc 100 bàn cho Real Madrid', 'https://vnexpress.net/mbappe-cham-moc-100-ban-cho-real-madrid-5136879.html', 18, 19, 'https://vnexpress.net/mbappe-cham-moc-100-ban-cho-real-madrid-5136879.html', 'CRAWLER', '2026-10-29 11:07:49.235345', '2026-10-29 11:03:04.911243');
