INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1394, NULL, '2026-10-29 11:03:05.203666', 'Ngân hàng Sài Gòn Tài Lộc giảm hơn 4.200 nhân viên, tương đương 25% tổng nhân sự chỉ trong 9 tháng, đưa quy mô lao động xuống mức thấp nhất 10 năm qua.', 'https://i1-kinhdoanh.vnecdn.net/2026/10/27/sacombank1-1793103101-4937-1793103262.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=cA024Jg2OeKRklnN2cm_ig', '2026-10-27 14:19:56', NULL, 'Sacombank giảm nhân sự xuống thấp nhất 10 năm', 'https://vnexpress.net/sacombank-giam-nhan-su-xuong-thap-nhat-10-nam-5137594.html', 19, 20, 'https://vnexpress.net/sacombank-giam-nhan-su-xuong-thap-nhat-10-nam-5137594.html', 'CRAWLER', '2026-10-29 11:07:49.430757', '2026-10-29 11:03:05.203666');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1396, NULL, '2026-10-29 11:03:05.213565', 'Từ ngân hàng thường xuyên dẫn đầu lãi suất tiền gửi giai đoạn 2020-2022, SCB hiện chỉ trả lãi 0,1-0,7% một năm cho hầu hết kỳ hạn, thấp hơn nhiều so với mặt bằng chung.', 'https://i1-kinhdoanh.vnecdn.net/2026/10/27/SCB-1793090353-6767-1793091145.webp?w=1200&h=0&q=100&dpr=1&fit=crop&s=GUlZgDbQjajaL_EZrYkRUw', '2026-10-27 13:18:26', NULL, 'SCB giảm lãi suất tiết kiệm xuống gần 0%', 'https://vnexpress.net/scb-giam-lai-suat-tiet-kiem-xuong-gan-0-5137507.html', 19, 20, 'https://vnexpress.net/scb-giam-lai-suat-tiet-kiem-xuong-gan-0-5137507.html', 'CRAWLER', '2026-10-29 11:07:49.435766', '2026-10-29 11:03:05.213565');
