INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1398, NULL, '2026-10-29 11:03:05.221578', 'Trung tâm tài chính quốc tế muốn hút nguồn vốn cần đảm bảo nhà đầu tư mang USD vào, sau đó chuyển ngược về nước an toàn mà không gặp trở ngại thủ tục, theo CEO Dragon Capital.', 'https://i1-kinhdoanh.vnecdn.net/2026/10/27/ba-n-sao-cu-a-tr108968-jpg-179-8080-1502-1793083854.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=YKH2pCLDHeVG877YbRB4mA', '2026-10-27 09:12:23', NULL, 'Sếp Dragon Capital: Trung tâm tài chính phải đảm bảo ''ngoại tệ vào ra dễ dàng''', 'https://vnexpress.net/sep-dragon-capital-trung-tam-tai-chinh-phai-dam-bao-ngoai-te-vao-ra-de-dang-5137391.html', 19, 20, 'https://vnexpress.net/sep-dragon-capital-trung-tam-tai-chinh-phai-dam-bao-ngoai-te-vao-ra-de-dang-5137391.html', 'CRAWLER', '2026-10-29 11:07:49.440821', '2026-10-29 11:03:05.221578');
