INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1471, NULL, '2026-10-29 11:03:05.692835', 'Hàng chục nghìn fan ăn diện lộng lẫy, mang theo lightstick cổ vũ concert cuối của BigBang tại Hà Nội, tối 25/10.', 'https://i1-giaitri.vnecdn.net/2026/10/25/fan-bb-1792925286.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=-9jYWmQuFABnqtgBpEpdSQ', '2026-10-25 11:06:21', NULL, 'Fan đổ về sân vận động chờ concert BigBang ngày cuối', 'https://vnexpress.net/fan-do-ve-san-van-dong-cho-concert-bigbang-ngay-cuoi-5136683.html', 20, 21, 'https://vnexpress.net/fan-do-ve-san-van-dong-cho-concert-bigbang-ngay-cuoi-5136683.html', 'CRAWLER', '2026-10-29 11:07:49.762851', '2026-10-29 11:03:05.692835');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1472, NULL, '2026-10-29 11:03:05.69945', 'Một cặp vé concert BigBang hạng CAT 5 (giá gốc 2 triệu đồng) được phe vé rao bán 27 triệu, còn hạng cao nhất được rao tới 75 triệu.', 'https://i1-giaitri.vnecdn.net/2026/10/25/wm1-wm1-phe-ve-giao-dich-179292290-5520-1219-1792923103.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=b3C995NdRT1Dg5ZrG4iGPQ', '2026-10-25 10:28:55', NULL, 'Phe vé ''hét'' giá hàng chục triệu đồng tại concert BigBang', 'https://vnexpress.net/phe-ve-het-gia-hang-chuc-trieu-dong-tai-concert-bigbang-5136674.html', 20, 21, 'https://vnexpress.net/phe-ve-het-gia-hang-chuc-trieu-dong-tai-concert-bigbang-5136674.html', 'CRAWLER', '2026-10-29 11:07:49.765872', '2026-10-29 11:03:05.69945');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1473, NULL, '2026-10-29 11:03:05.705448', 'Ban tổ chức Miss Universe Vietnam cho biết Hoa hậu Quỳnh Anh sẽ không tham gia trình diễn sân khấu trong 6 tháng, sau ồn ào "nói xấu đồng nghiệp".', 'https://i1-giaitri.vnecdn.net/2026/10/25/833313011186352719820477576877-6976-2953-1792918642.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=W3yQXbwBgL3z5yeMH0_b8g', '2026-10-25 09:43:00', NULL, 'Miss Universe Vietnam phạt Hoa hậu Quỳnh Anh', 'https://vnexpress.net/miss-universe-vietnam-phat-hoa-hau-quynh-anh-5136659.html', 20, 21, 'https://vnexpress.net/miss-universe-vietnam-phat-hoa-hau-quynh-anh-5136659.html', 'CRAWLER', '2026-10-29 11:07:49.768853', '2026-10-29 11:03:05.705448');
