INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1475, NULL, '2026-10-29 11:03:05.716447', 'Trước khi vụt sáng ở "Anh trai vượt ngàn chông gai", nhạc sĩ Cheng từng chật vật làm nhạc suốt 10 năm, tên tuổi xa lạ với công chúng.', 'https://i1-giaitri.vnecdn.net/2026/10/24/839594129-n-1792841813-2327-1792842424.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=1rjR_zDFFbvedsdGhXGD5A', '2026-10-25 06:30:00', NULL, 'Cheng: ''Tôi từng hoài nghi bản thân''', 'https://vnexpress.net/cheng-toi-tung-hoai-nghi-ban-than-5136435.html', 20, 21, 'https://vnexpress.net/cheng-toi-tung-hoai-nghi-ban-than-5136435.html', 'CRAWLER', '2026-10-29 11:07:49.774852', '2026-10-29 11:03:05.716447');
