INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1487, NULL, '2026-10-29 11:03:05.847594', 'Công an tỉnh khởi tố vụ án sau vụ cháy nhà khiến hai cha con tử vong; người ông 81 tuổi bị nghi liên quan do mâu thuẫn gia đình.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/img-1793143869-6737-1793144195.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=8hI6GbMJqLKx9r2uNbI-pA', '2026-10-27 23:37:11', NULL, 'Khởi tố vụ cháy nhà 2 cha con tử vong ở Gia Lai', 'https://vnexpress.net/khoi-to-vu-chay-nha-2-cha-con-tu-vong-o-gia-lai-5137645.html', 21, 22, 'https://vnexpress.net/khoi-to-vu-chay-nha-2-cha-con-tu-vong-o-gia-lai-5137645.html', 'CRAWLER', '2026-10-29 11:07:49.8789', '2026-10-29 11:03:05.847594');
