INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1489, NULL, '2026-10-29 11:03:05.857608', 'Mang những khoản nợ lớn, mất nhà, gia đình tan vỡ, cuộc sống đang rất khổ sở... là bi kịch được nhiều bị hại nêu tại phiên tòa, mong những kẻ lừa đảo trong đường dây của Mr Pips trả lại tiền.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/2aobor891g29cz2dgwlnps3bofwkye-8686-7248-1793117377.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Sb6Q0eANQkee68hRSGsPeg', '2026-10-27 17:08:19', NULL, 'Tài khoản ''cháy'', những món nợ và bi kịch sau cú lừa của Mr Pips', 'https://vnexpress.net/tai-khoan-chay-nhung-mon-no-va-bi-kich-sau-cu-lua-cua-mr-pips-5137628.html', 21, 22, 'https://vnexpress.net/tai-khoan-chay-nhung-mon-no-va-bi-kich-sau-cu-lua-cua-mr-pips-5137628.html', 'CRAWLER', '2026-10-29 11:07:49.884909', '2026-10-29 11:03:05.857608');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1490, NULL, '2026-10-29 11:03:05.862594', 'Từ những cái chết bất thường tại nhiều tỉnh, cảnh sát lần theo dấu vết hóa chất, các khoản nợ và những mối quan hệ thân quen để phanh phui chuỗi án mạng rúng động.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/download-1793095532-9176-1793096056.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=KApGUB2H35Nx-TP_cSNJkA', '2026-10-27 17:00:00', NULL, 'Lòng tham sau vụ đầu độc 15 người bằng xyanua ở Thái Lan', 'https://vnexpress.net/long-tham-sau-vu-dau-doc-15-nguoi-bang-xyanua-o-thai-lan-5137570.html', 21, 22, 'https://vnexpress.net/long-tham-sau-vu-dau-doc-15-nguoi-bang-xyanua-o-thai-lan-5137570.html', 'CRAWLER', '2026-10-29 11:07:49.887897', '2026-10-29 11:03:05.862594');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1492, NULL, '2026-10-29 11:03:05.872552', 'Trước việc tài xế phản ánh quán cơm trên đường dẫn cao tốc tính nửa con gà luộc 300.000 đồng, tổng giá 4 món 640.000 đồng, công an vào cuộc xác minh.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/img-jpeg-1793101340-4976-1793101495.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=NtjTQaobuCnUVK3qZB0E0g', '2026-10-27 11:56:26', NULL, 'Công an xác minh vụ bữa cơm 640.000 đồng bên đường dẫn cao tốc', 'https://vnexpress.net/cong-an-xac-minh-vu-bua-com-640-000-dong-ben-duong-dan-cao-toc-5137597.html', 21, 22, 'https://vnexpress.net/cong-an-xac-minh-vu-bua-com-640-000-dong-ben-duong-dan-cao-toc-5137597.html', 'CRAWLER', '2026-10-29 11:07:49.893901', '2026-10-29 11:03:05.872552');
