INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1506, NULL, '2026-10-29 11:03:05.950647', 'Khoa Tran và Quynh (Isabelle) Nguyen, sống ở Toronto, lần lượt nhận án tù chung thân và 6 năm tù vì sát hại hàng xóm, vứt thi thể vào thùng rác và tìm cách che giấu án mạng.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/download-1793064161-5234-1793064216.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=IbbQqEHp_zgLZGZhMl3LEg', '2026-10-27 02:37:38', NULL, 'Đôi vợ chồng gốc Việt bị tuyên án vì hại hàng xóm sau mâu thuẫn ''khói nướng thịt''', 'https://vnexpress.net/doi-vo-chong-goc-viet-bi-tuyen-an-vi-hai-hang-xom-sau-mau-thuan-khoi-nuong-thit-5137261.html', 21, 22, 'https://vnexpress.net/doi-vo-chong-goc-viet-bi-tuyen-an-vi-hai-hang-xom-sau-mau-thuan-khoi-nuong-thit-5137261.html', 'CRAWLER', '2026-10-29 11:07:49.964913', '2026-10-29 11:03:05.950647');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1507, NULL, '2026-10-29 11:03:05.955773', 'Ông Quách Chí Lâm bị cáo buộc lợi dụng ảnh hưởng của mình để gặp, hứa hẹn cho tiền Bí thư Đảng ủy xã Hợp Kim nhằm giúp doanh nghiệp khai thác đất trái phép.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/1-1793065148-4495-1793065172.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=cdIgmuStNlV9bZXor4Q98A', '2026-10-27 01:53:58', NULL, '''Lợi dụng ảnh hưởng'' để tác động quan chức xã giúp doanh nghiệp', 'https://vnexpress.net/loi-dung-anh-huong-de-tac-dong-quan-chuc-xa-giup-doanh-nghiep-5137269.html', 21, 22, 'https://vnexpress.net/loi-dung-anh-huong-de-tac-dong-quan-chuc-xa-giup-doanh-nghiep-5137269.html', 'CRAWLER', '2026-10-29 11:07:49.968859', '2026-10-29 11:03:05.955773');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1508, NULL, '2026-10-29 11:03:05.961665', 'Chung sống với chồng từ trước năm 1975 nhưng không đăng ký kết hôn, bà Nguyễn, 79 tuổi, yêu cầu tòa hủy "kết hôn trái pháp luật" của ông với người sau và được chấp nhận.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/anhminhhoa-1793008204-8285-1793008560.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=cfqUU7DhtYliPcrQCDGAvQ', '2026-10-26 23:00:00', NULL, 'Cụ bà ở TP HCM yêu cầu hủy hôn nhân giữa chồng với ''người sau''', 'https://vnexpress.net/cu-ba-o-tp-hcm-yeu-cau-huy-hon-nhan-giua-chong-voi-nguoi-sau-5137094.html', 21, 22, 'https://vnexpress.net/cu-ba-o-tp-hcm-yeu-cau-huy-hon-nhan-giua-chong-voi-nguoi-sau-5137094.html', 'CRAWLER', '2026-10-29 11:07:49.973785', '2026-10-29 11:03:05.961665');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1509, NULL, '2026-10-29 11:03:05.967676', 'Xe đã bán nhưng chưa làm thủ tục sang tên cho người mua, khi bị phạt nguội thì chủ cũ đứng tên xe sẽ bị mời lên làm việc để giải trình với cơ quan công an.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/1-1792992141-6170-1792992157.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=aeg65eeO0BmY1Eb0aP4jzg', '2026-10-26 23:00:00', NULL, 'Các rắc rối pháp lý nếu bán xe mà chưa sang tên đổi chủ', 'https://vnexpress.net/cac-rac-roi-phap-ly-neu-ban-xe-ma-chua-sang-ten-doi-chu-5136951.html', 21, 22, 'https://vnexpress.net/cac-rac-roi-phap-ly-neu-ban-xe-ma-chua-sang-ten-doi-chu-5136951.html', 'CRAWLER', '2026-10-29 11:07:49.978785', '2026-10-29 11:03:05.967676');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1510, NULL, '2026-10-29 11:03:05.971679', 'Dối vợ lấy tiền tiết kiệm, vay nặng lãi và bố đẻ để nạp vào sàn của Mr Pips mong nhận lãi 20%/ngày, anh Đức giờ ngậm ngùi nhận "tham, ngu giống bao người".', 'https://i1-vnexpress.vnecdn.net/2026/10/26/toahn8-1793018583-8972-1793018886.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=lguHVDlMbjABDU9LZgTuSQ', '2026-10-26 17:00:00', NULL, 'Lời kể của bị hại giấu vợ mang sổ tiết kiệm, vay nóng để nạp tiền vào sàn của Mr Pips', 'https://vnexpress.net/loi-ke-cua-bi-hai-giau-vo-mang-so-tiet-kiem-vay-nong-de-nap-tien-vao-san-cua-mr-pips-5137127.html', 21, 22, 'https://vnexpress.net/loi-ke-cua-bi-hai-giau-vo-mang-so-tiet-kiem-vay-nong-de-nap-tien-vao-san-cua-mr-pips-5137127.html', 'CRAWLER', '2026-10-29 11:07:49.983916', '2026-10-29 11:03:05.971679');
