INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1519, NULL, '2026-10-29 11:03:06.020674', 'Biết người bạn 69 tuổi vừa bị lừa tiền điện tử, Vasudevan hứa giúp lấy lại nhưng chiếm đoạt thêm 112.500 SGD (2,3 tỷ đồng) cho khoản phí luật sư, thám tử.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/funixdaotiendientu2-1792994947-1134-1792994977.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=O67ZgKAb88Nf-dqQKihmpw', '2026-10-26 06:57:09', NULL, 'Bị lừa tiền ảo, mất thêm 112.500 SGD vì tin bạn giúp lấy lại', 'https://vnexpress.net/bi-lua-tien-ao-mat-them-112-500-sgd-vi-tin-ban-giup-lay-lai-5136966.html', 21, 22, 'https://vnexpress.net/bi-lua-tien-ao-mat-them-112-500-sgd-vi-tin-ban-giup-lay-lai-5136966.html', 'CRAWLER', '2026-10-29 11:07:50.016883', '2026-10-29 11:03:06.020674');
