INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1521, NULL, '2026-10-29 11:03:06.032676', 'Nguyễn Chí Công, 37 tuổi, bị cáo buộc giả danh phó giám đốc, làm bệnh án ung thư của bệnh viện Hàn Quốc để khiến bạn gái tin tưởng, chuyển hơn 337 triệu đồng.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/1792993479914-1792996373-8688-1792996405.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=tXr5D92XIl0tOKB4CedRMQ', '2026-10-26 06:34:13', NULL, 'Giả phó giám đốc mắc ung thư, lừa tiền bạn gái', 'https://vnexpress.net/gia-pho-giam-doc-mac-ung-thu-lua-tien-ban-gai-5136963.html', 21, 22, 'https://vnexpress.net/gia-pho-giam-doc-mac-ung-thu-lua-tien-ban-gai-5136963.html', 'CRAWLER', '2026-10-29 11:07:50.022821', '2026-10-29 11:03:06.032676');
