INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1525, NULL, '2026-10-29 11:03:06.054674', 'Nhiều chốt kiểm soát gồm cảnh sát cơ động, CSGT, hình sự... được lập trên các tuyến đường ở xã Diên Lâm và khu vực Khánh Vĩnh trong 4 ngày qua, truy tìm các phạm nhân trốn Trại giam A2.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/xuyendem-1792983424.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Wnz0P_RN4xQl7bMxlcb_nA', '2026-10-26 03:24:35', NULL, 'Hàng trăm cảnh sát chốt chặn xuyên đêm, truy lùng các phạm nhân trốn trại giam', 'https://vnexpress.net/hang-tram-canh-sat-chot-chan-xuyen-dem-truy-lung-cac-pham-nhan-tron-trai-giam-5136729.html', 21, 22, 'https://vnexpress.net/hang-tram-canh-sat-chot-chan-xuyen-dem-truy-lung-cac-pham-nhan-tron-trai-giam-5136729.html', 'CRAWLER', '2026-10-29 11:07:50.035802', '2026-10-29 11:03:06.054674');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1526, NULL, '2026-10-29 11:03:06.060665', 'Hai tài xế nam và nữ bị phạt mỗi người 900.000 đồng vì đỗ ôtô 5-7 chỗ tại ngã ba khi chở con đi học, gây cản trở giao thông.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/hai-o-to-do-sai-quy-dinh-17929-9595-5153-1792983816.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=SeJSD_P5UR5fy09QoRlb8Q', '2026-10-26 03:24:33', NULL, 'Đỗ ôtô chắn ngã ba khi đưa con đi học, phụ huynh bị phạt 1,8 triệu đồng', 'https://vnexpress.net/do-oto-chan-nga-ba-khi-dua-con-di-hoc-phu-huynh-bi-phat-1-8-trieu-dong-5136846.html', 21, 22, 'https://vnexpress.net/do-oto-chan-nga-ba-khi-dua-con-di-hoc-phu-huynh-bi-phat-1-8-trieu-dong-5136846.html', 'CRAWLER', '2026-10-29 11:07:50.039813', '2026-10-29 11:03:06.060665');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1527, NULL, '2026-10-29 11:03:06.066674', 'Nhóm 113 người nước ngoài thuê khách sạn Văn Hoa tổ chức mạng lưới lừa đảo trực tuyến tại nhiều quốc gia, trong số này 88 trường hợp đã bị khởi tố.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/15-1792978775-4876-1792978779.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=pQCdPwwa-3OgogMfITVyaA', '2026-10-26 02:01:03', NULL, 'Chiêu dẫn dụ của nhóm hơn 100 người nước ngoài đến Việt Nam lừa tiền qua mạng', 'https://vnexpress.net/chieu-dan-du-cua-nhom-hon-100-nguoi-nuoc-ngoai-den-viet-nam-lua-tien-qua-mang-5136782.html', 21, 22, 'https://vnexpress.net/chieu-dan-du-cua-nhom-hon-100-nguoi-nuoc-ngoai-den-viet-nam-lua-tien-qua-mang-5136782.html', 'CRAWLER', '2026-10-29 11:07:50.042355', '2026-10-29 11:03:06.066674');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1528, NULL, '2026-10-29 11:03:06.072679', 'Mr Pips Phó Đức Nam, Shark Nguyễn Hòa Bình và 186 người hôm nay ra tòa trong vụ lừa đảo ngoại hối, chứng khoán lớn nhất từng bị triệt phá, gây thiệt hại hơn 1.560 tỷ đồng.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/the-ba-ng-1792992342-6550-1792992354.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=3aWwvnAeucah3nogQP-7XQ', '2026-10-26 00:58:36', NULL, '''Siêu lừa'' Mr Pips, Shark Bình bắt đầu bị xét xử trong phiên tòa 15 ngày', 'https://vnexpress.net/sieu-lua-mr-pips-shark-binh-bat-dau-bi-xet-xu-trong-phien-toa-15-ngay-5136718.html', 21, 22, 'https://vnexpress.net/sieu-lua-mr-pips-shark-binh-bat-dau-bi-xet-xu-trong-phien-toa-15-ngay-5136718.html', 'CRAWLER', '2026-10-29 11:07:50.046344', '2026-10-29 11:03:06.072679');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1529, NULL, '2026-10-29 11:03:06.079663', 'Maria Delacruz, 33 tuổi, cáo buộc bị đội trưởng liên tục quấy rối, từ bình phẩm khiếm nhã về cơ thể, cố cưỡng hôn đến gửi tin nhắn khiêu dâm, sau khi bị cô cự tuyệt làm tình nhân.', 'https://i1-vnexpress.vnecdn.net/2026/10/25/261022-nypd-maria-de-la-179294-8402-3257-1792944587.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=kELkbrIXWPi6xfETTk5eSA', '2026-10-25 17:00:00', NULL, 'Nữ cảnh sát New York kiện cấp trên quấy rối tình dục', 'https://vnexpress.net/nu-canh-sat-new-york-kien-cap-tren-quay-roi-tinh-duc-5136722.html', 21, 22, 'https://vnexpress.net/nu-canh-sat-new-york-kien-cap-tren-quay-roi-tinh-duc-5136722.html', 'CRAWLER', '2026-10-29 11:07:50.049346', '2026-10-29 11:03:06.079663');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1530, NULL, '2026-10-29 11:03:06.085665', 'Nhóm người đi nhiều xe máy rượt đuổi, ép xe hai thanh niên trên đường Nguyễn Cơ Thạch, chém người cầm lái bị thương.', 'https://i1-vnexpress.vnecdn.net/2026/10/25/179293372591621486803112921729-7665-5617-1792937785.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=zWIbW9V3Y5Bw1JbiIrCnVw&t=image', '2026-10-25 14:22:38', NULL, 'Nhóm thanh thiếu niên ép xe, chém người ở TP HCM', 'https://vnexpress.net/nhom-thanh-thieu-nien-ep-xe-chem-nguoi-o-tp-hcm-5136700.html', 21, 22, 'https://vnexpress.net/nhom-thanh-thieu-nien-ep-xe-chem-nguoi-o-tp-hcm-5136700.html', 'CRAWLER', '2026-10-29 11:07:50.052343', '2026-10-29 11:03:06.085665');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1531, NULL, '2026-10-29 11:03:06.09168', 'Cảnh sát giao thông cùng công an cấp xã tại các địa phương đang thực hiện đợt cao điểm rà soát, cập nhật thông tin để làm sạch dữ liệu ôtô, xe máy.', 'https://i1-vnexpress.vnecdn.net/2026/10/25/1-1792905162-6793-1792905179.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Xz_TzmKADPY3qOMFZRc9dw', '2026-10-25 05:26:58', NULL, 'Công an đang mở cao điểm ''làm sạch'' dữ liệu ôtô, xe máy', 'https://vnexpress.net/cong-an-dang-mo-cao-diem-lam-sach-du-lieu-oto-xe-may-5136625.html', 21, 22, 'https://vnexpress.net/cong-an-dang-mo-cao-diem-lam-sach-du-lieu-oto-xe-may-5136625.html', 'CRAWLER', '2026-10-29 11:07:50.055344', '2026-10-29 11:03:06.09168');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1532, NULL, '2026-10-29 11:03:06.098674', 'Vào thời điểm ùn tắc giao thông, tôi thấy nhiều người điều khiển xe máy leo lên vỉa hè để đi cho nhanh.', 'https://i1-vnexpress.vnecdn.net/2026/10/25/233a5006-1792899265-2485-1792899406.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=3RUnNQ8QvxSxWJ_Mdfqu-g', '2026-10-25 03:38:48', NULL, 'Phải đi xe máy lên vỉa hè do tắc đường, tôi có được miễn phạt?', 'https://vnexpress.net/phai-di-xe-may-len-via-he-do-tac-duong-toi-co-duoc-mien-phat-5136589.html', 21, 22, 'https://vnexpress.net/phai-di-xe-may-len-via-he-do-tac-duong-toi-co-duoc-mien-phat-5136589.html', 'CRAWLER', '2026-10-29 11:07:50.057956', '2026-10-29 11:03:06.098674');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1533, NULL, '2026-10-29 11:03:06.103675', 'Thấy một tài xế bất tỉnh trong xe nghi do say rượu, cảnh sát kiểm tra thì phát hiện thi thể bạn gái cũ của anh ta trong thùng carton ở cốp xe.', 'https://i1-vnexpress.vnecdn.net/2026/10/25/holt-johnson-1792897730-6107-1792897970.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=9DEBHKJjfCYxyDuJHCmvOw', '2026-10-25 03:36:18', NULL, 'Kiểm tra tài xế say rượu, cảnh sát phát hiện thi thể trong cốp xe', 'https://vnexpress.net/kiem-tra-tai-xe-say-ruou-canh-sat-phat-hien-thi-the-trong-cop-xe-5136585.html', 21, 22, 'https://vnexpress.net/kiem-tra-tai-xe-say-ruou-canh-sat-phat-hien-thi-the-trong-cop-xe-5136585.html', 'CRAWLER', '2026-10-29 11:07:50.061942', '2026-10-29 11:03:06.103675');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1534, NULL, '2026-10-29 11:03:06.10971', 'Phát hiện chồng có quan hệ bất chính, chuyển 100.000 nhân dân tệ cho phụ nữ khác, người vợ kiện đòi lại tiền nhưng tòa án xác định đây là tiền mua dâm, không được pháp luật bảo vệ.', 'https://i1-vnexpress.vnecdn.net/2026/10/25/post662807602f674868ec3-179289-3778-5117-1792895781.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Jx1WPXP6WsSZJ9_4Y2gUug', '2026-10-25 02:54:59', NULL, 'Vợ kiện đòi lại tiền chồng mua dâm', 'https://vnexpress.net/vo-kien-doi-lai-tien-chong-mua-dam-5136577.html', 21, 22, 'https://vnexpress.net/vo-kien-doi-lai-tien-chong-mua-dam-5136577.html', 'CRAWLER', '2026-10-29 11:07:50.064973', '2026-10-29 11:03:06.10971');
