INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1538, NULL, '2026-10-29 11:03:06.191725', 'Trưa hôm ấy Dublin có nắng, một điều ít gặp ở thành phố này.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/20261026NguyenKien-1793031840-4742-1793031854.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=LLhVoZ4qNbyMU4iGHm_qUA', '2026-10-26 17:00:00', NULL, 'Hai phút chờ một ly bia', 'https://vnexpress.net/hai-phut-cho-mot-ly-bia-5137203.html', 25, 23, 'https://vnexpress.net/hai-phut-cho-mot-ly-bia-5137203.html', 'CRAWLER', '2026-10-29 11:07:50.181938', '2026-10-29 11:07:50.181938');
