INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1540, NULL, '2026-10-29 11:03:06.20371', 'Dưới làn nước xanh ngọc của quốc đảo Palau ở Tây Thái Bình Dương, một nghiên cứu thực hiện năm 2012 của Viện Khoa học biển Australia (AIMS) đưa ra phép so sánh đáng chú ý.', 'https://i1-vnexpress.vnecdn.net/2026/10/24/20261024MinhTruong-1792814164-4678-1792814207.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Pl7j8x2-2bbvcJuJe_7sEg', '2026-10-24 08:00:00', NULL, 'Phá núi hay cứu voọc?', 'https://vnexpress.net/pha-nui-hay-cuu-vooc-5136329.html', 25, 23, 'https://vnexpress.net/pha-nui-hay-cuu-vooc-5136329.html', 'CRAWLER', '2026-10-29 11:07:50.18794', '2026-10-29 11:07:50.18794');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1541, NULL, '2026-10-29 11:03:06.209709', 'Có một tiếng nhạc mà người Việt ở độ tuổi bốn mươi, dù sinh ở đâu, nghe ba nốt đầu đã biết. Tiếng đàn bầu buông ra như làn gió qua đồng nước, rồi câu hát cất lên về một mảnh đất - nơi những phận người dạt trôi.', 'https://i1-vnexpress.vnecdn.net/2026/10/24/20261024NguyenTienHuy-17928089-8924-4022-1792808924.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=_KbX-pFMJD9WiJ3OlUEa2Q', '2026-10-23 13:24:07', NULL, 'Đất phương Nam thương nhớ', 'https://vnexpress.net/dat-phuong-nam-thuong-nho-5136200.html', 25, 23, 'https://vnexpress.net/dat-phuong-nam-thuong-nho-5136200.html', 'CRAWLER', '2026-10-29 11:07:50.19094', '2026-10-29 11:07:50.19094');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1542, NULL, '2026-10-29 11:03:06.215723', 'Tôi không nghĩ một con số trên bảng điểm lại phức tạp đến thế, cho đến khi trải nghiệm bốn hệ thống giáo dục: Việt Nam, Singapore, Bỉ và Mỹ.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/20261023TrinhPhuongQuan1-17927-7381-8333-1792721628.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=_Ps4KddXUzRk2e2yTGIGiw', '2026-10-22 17:02:07', NULL, 'Lạm phát bằng xuất sắc', 'https://vnexpress.net/lam-phat-bang-xuat-sac-5135784.html', 25, 23, 'https://vnexpress.net/lam-phat-bang-xuat-sac-5135784.html', 'CRAWLER', '2026-10-29 11:07:50.196551', '2026-10-29 11:07:50.196551');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1543, NULL, '2026-10-29 11:03:06.221724', 'Minh - bạn tôi, một cô giáo cấp ba, giọng nghẹn lại: “Có ngày đi dạy về, cảm giác như vừa trải qua một trận chiến. Phía bên kia là học trò chứ ai”.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/20261022PhungNguyen3-179265123-7180-4059-1792651238.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=3cb3z0DydK_EzwxW1EDs1A', '2026-10-21 14:11:17', NULL, 'Sự bất kính của học trò', 'https://vnexpress.net/su-bat-kinh-cua-hoc-tro-5135323.html', 25, 23, 'https://vnexpress.net/su-bat-kinh-cua-hoc-tro-5135323.html', 'CRAWLER', '2026-10-29 11:07:50.200072', '2026-10-29 11:07:50.200072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1544, NULL, '2026-10-29 11:03:06.226715', 'Một lần ngồi ở quán cà phê vỉa hè tại Sài Gòn, tôi thấy một người đàn ông chở vợ con bằng xe máy ghé vào mua nước.', 'https://i1-vnexpress.vnecdn.net/2026/10/20/20261020NguyenNhatMinh-1792486-5316-1256-1792487275.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=-i237GCNh1zvp2qBppdRsQ', '2026-10-20 17:00:00', NULL, 'Ai ''buộc'' khói thuốc lại?', 'https://vnexpress.net/ai-buoc-khoi-thuoc-lai-5134673.html', 25, 23, 'https://vnexpress.net/ai-buoc-khoi-thuoc-lai-5134673.html', 'CRAWLER', '2026-10-29 11:07:50.203072', '2026-10-29 11:07:50.203072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1545, NULL, '2026-10-29 11:03:06.232729', 'Cuối cùng, đêm qua Ôbobun Grenette của tôi cũng bị đập cửa và trộm tiền.', 'https://i1-vnexpress.vnecdn.net/2026/10/19/20261019PhanVietPhong1-1792415-1281-1974-1792415579.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=pVjpZYuQwVPWcNTQxWjMRg', '2026-10-19 13:00:00', NULL, 'Kinh doanh giữa bạo loạn ở Pháp', 'https://vnexpress.net/kinh-doanh-giua-bao-loan-o-phap-5134332.html', 25, 23, 'https://vnexpress.net/kinh-doanh-giua-bao-loan-o-phap-5134332.html', 'CRAWLER', '2026-10-29 11:07:50.206072', '2026-10-29 11:07:50.206072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1546, NULL, '2026-10-29 11:03:06.238727', 'Một số người tự nhận đang làm ở Microsoft Việt Nam kể lại trên mạng xã hội rằng họ được mời dự cuộc họp "Cập nhật quan trọng về hoạt động kinh doanh". Yêu cầu có mặt trực tiếp. Có bộ phận nhân sự tham dự.', 'https://i1-vnexpress.vnecdn.net/2026/10/19/20261019HuynhThienTong-1792382-4048-6194-1792382250.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Xru1w3XDiCYxs5GkDF6gIw', '2026-10-18 13:52:15', NULL, 'Nếu ngày mai mất việc', 'https://vnexpress.net/neu-ngay-mai-mat-viec-5133874.html', 25, 23, 'https://vnexpress.net/neu-ngay-mai-mat-viec-5133874.html', 'CRAWLER', '2026-10-29 11:07:50.210074', '2026-10-29 11:07:50.210074');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1547, NULL, '2026-10-29 11:03:06.244712', 'Sáng 14/10, TP HCM tổ chức lễ truy điệu 731 hài cốt được tìm thấy tại Công viên Lê Thị Riêng, phần lớn là những người đã ngã xuống trong cuộc chiến Tết Mậu Thân năm 1968.', 'https://i1-vnexpress.vnecdn.net/2026/10/17/20261017VoTaHan-1792227899-8771-1792227903.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=QvjZTC-3Ow_7c54yEktKAg', '2026-10-17 08:20:46', NULL, 'Lá thư năm 1968', 'https://vnexpress.net/la-thu-nam-1968-5133614.html', 25, 23, 'https://vnexpress.net/la-thu-nam-1968-5133614.html', 'CRAWLER', '2026-10-29 11:07:50.214071', '2026-10-29 11:07:50.214071');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1549, NULL, '2026-10-29 11:03:06.256053', 'Tôi lớn lên ở miền Bắc Ấn Độ, trong một khu tập thể nhỏ dành cho công nhân đường sắt. Cha tôi làm việc trong ngành hỏa xa với mức lương khiêm tốn, vì vậy gia đình luôn phải chắt chiu từng đồng.', 'https://i1-vnexpress.vnecdn.net/2026/10/16/20261016VinodAhuja1-1792119584-4555-1792119588.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Cw-tp6ZjT9s6niUzihutLA', '2026-10-15 17:00:00', NULL, 'Ngon, bổ và đủ rẻ', 'https://vnexpress.net/ngon-bo-va-du-re-5132808.html', 25, 23, 'https://vnexpress.net/ngon-bo-va-du-re-5132808.html', 'CRAWLER', '2026-10-29 11:07:50.220072', '2026-10-29 11:07:50.220072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1550, NULL, '2026-10-29 11:03:06.262802', 'Nhà tôi trên phố Quán Sứ, bóng lá xanh đậm của cây sấu đã in sâu trong tâm trí tôi.', 'https://i1-vnexpress.vnecdn.net/2026/10/14/20261014QuanTheDan-1791985524-6023-1791985577.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=F8qLpzT3AbfPMFeB9ukxJw', '2026-10-14 13:41:08', NULL, 'Mùi phố Hà Nội', 'https://vnexpress.net/mui-pho-ha-noi-5132409.html', 25, 23, 'https://vnexpress.net/mui-pho-ha-noi-5132409.html', 'CRAWLER', '2026-10-29 11:07:50.22307', '2026-10-29 11:07:50.22307');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1551, NULL, '2026-10-29 11:03:06.268907', 'Cô bé bê một chồng bát từ khu rửa vào kệ. Vấp phải cái bậu cửa, nó mất thăng bằng, chồng bát rơi xuống đất, không còn cái nào nguyên vẹn.', 'https://i1-vnexpress.vnecdn.net/2026/10/13/20261013NguyenTheVinh-17918996-7409-7864-1791899681.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=B4ET-71hDdwBL4V5lknw_g', '2026-10-13 17:00:00', NULL, '''Nhà tù'' ngôn từ', 'https://vnexpress.net/nha-tu-ngon-tu-5131905.html', 25, 23, 'https://vnexpress.net/nha-tu-ngon-tu-5131905.html', 'CRAWLER', '2026-10-29 11:07:50.227073', '2026-10-29 11:07:50.227073');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1552, NULL, '2026-10-29 11:03:06.273902', 'Ba giờ chiều mỗi ngày, các nhà khoa học tại Kavli IPMU, một viện nghiên cứu thuộc Đại học Tokyo, có một cuộc hẹn đặc biệt. Họ rời bàn làm việc, xuống sảnh uống cà phê, trà xanh hay gạo rang, ăn bánh và chuyện trò.', 'https://i1-vnexpress.vnecdn.net/2026/10/12/20261012NguyenNhatMinh-1791819-3612-4663-1791819712.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=1DdCynofXzjsUbJ8-cQEFw', '2026-10-12 17:00:00', NULL, 'Tiệc trà ba giờ chiều', 'https://vnexpress.net/tiec-tra-ba-gio-chieu-5131479.html', 25, 23, 'https://vnexpress.net/tiec-tra-ba-gio-chieu-5131479.html', 'CRAWLER', '2026-10-29 11:07:50.231074', '2026-10-29 11:07:50.231074');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1553, NULL, '2026-10-29 11:03:06.280898', 'Hơn mười năm trước, sau khi về hưu và sống ở Nam California, tôi dự một buổi họp mặt của những người Việt từng du học tại Mỹ trước năm 1975.', 'https://i1-vnexpress.vnecdn.net/2026/10/10/20261010VoTaHan-1791601249-6726-1791601273.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Vs5TamSxQJlbrVaTtQ8JRA', '2026-10-11 17:00:00', NULL, 'Khúc ruột ngàn dặm', 'https://vnexpress.net/khuc-ruot-ngan-dam-5130629.html', 25, 23, 'https://vnexpress.net/khuc-ruot-ngan-dam-5130629.html', 'CRAWLER', '2026-10-29 11:07:50.234072', '2026-10-29 11:07:50.234072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1554, NULL, '2026-10-29 11:03:06.286818', 'Dưới bóng râm của một gầm cầu vượt tại quận Nam Từ Liêm (Hà Nội), Minh thả chân xuống, dừng đèn đỏ, mắt vẫn dán vào màn hình điện thoại gắn trước tay lái, đang chớp sáng ứng dụng gọi xe. Trả lời nốt câu hỏi của tôi, Minh nói anh có bằng Cử nhân Tài chính loại khá.', 'https://i1-vnexpress.vnecdn.net/2026/10/11/a20261011MinhTruong-1791686844-9464-1791686847.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Y5yTyuzOXt6IBqY7Oc1PAg', '2026-10-10 17:00:00', NULL, 'Thợ máy lương nghìn đô', 'https://vnexpress.net/tho-may-luong-nghin-do-5130826.html', 25, 23, 'https://vnexpress.net/tho-may-luong-nghin-do-5130826.html', 'CRAWLER', '2026-10-29 11:07:50.237072', '2026-10-29 11:07:50.237072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1555, NULL, '2026-10-29 11:03:06.291815', 'Nếu có điều gì đó làm ''loãng'' không khí căng thẳng của biểu tình ở Pháp, thì chính là lỗi chính tả trên các khẩu hiệu.', 'https://i1-vnexpress.vnecdn.net/2026/10/09/20261009VoNhatVinh-1791564366-1498-1791564552.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=FDe24qcwaTBgw9s080tojQ', '2026-10-09 17:00:16', NULL, 'Lỗi chính tả trên băng rôn biểu tình', 'https://vnexpress.net/loi-chinh-ta-tren-bang-ron-bieu-tinh-5130561.html', 25, 23, 'https://vnexpress.net/loi-chinh-ta-tren-bang-ron-bieu-tinh-5130561.html', 'CRAWLER', '2026-10-29 11:07:50.240071', '2026-10-29 11:07:50.240071');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1556, NULL, '2026-10-29 11:03:06.298916', 'Có lần tôi cùng một doanh nghiệp Nhật Bản đến gặp và hỗ trợ một doanh nghiệp xuất khẩu gạo của Việt Nam tìm kiếm khách hàng quốc tế.', 'https://i1-vnexpress.vnecdn.net/2026/10/08/20261008TranDangXuan-179147840-5427-4858-1791478414.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=c84f5VI6mlwDbvVtWQOZ2Q', '2026-10-08 17:01:10', NULL, 'Cái xua tay của người Nhật', 'https://vnexpress.net/cai-xua-tay-cua-nguoi-nhat-5130128.html', 25, 23, 'https://vnexpress.net/cai-xua-tay-cua-nguoi-nhat-5130128.html', 'CRAWLER', '2026-10-29 11:07:50.246073', '2026-10-29 11:07:50.246073');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1557, NULL, '2026-10-29 11:03:06.304915', 'SIGCOMM là một trong những hội nghị hàng đầu trong lĩnh vực truyền thông dữ liệu và mạng máy tính. Tại ACM SIGCOMM 2026, diễn ra ngày 17-21/8/2026 ở Denver, Colorado, Mỹ, giữa hàng loạt nghiên cứu về AI, hạ tầng mạng thế hệ mới và các hệ thống quy mô lớn, tôi lại dừng khá lâu ở một công trình cho phép truy cập web và tương tác với ChatGPT bằng sóng FM và tin nhắn SMS.', 'https://i1-vnexpress.vnecdn.net/2026/10/06/20261006NguyenKien-1791254620-5184-1791255594.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=M7-ke76B5V96WDnWjYlj1w', '2026-10-07 17:00:00', NULL, 'ChatGPT ở nơi không Internet', 'https://vnexpress.net/chatgpt-o-noi-khong-internet-5128830.html', 25, 23, 'https://vnexpress.net/chatgpt-o-noi-khong-internet-5128830.html', 'CRAWLER', '2026-10-29 11:07:50.250071', '2026-10-29 11:07:50.250071');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1558, NULL, '2026-10-29 11:03:06.310799', 'Cuối tháng 9/2026, cộng đồng game Việt Nam dậy sóng trước thông tin KRAFTON, nhà phát hành tựa game PUBG, khóa tài khoản và cấm thi đấu vĩnh viễn hai tuyển thủ Việt Nam Himass và TanVuu sau cáo buộc họ xem livestream của đối thủ tại một giải giao hữu.', 'https://i1-vnexpress.vnecdn.net/2026/10/07/20261007ThaiManhCuong-17913435-7935-5307-1791343591.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=YbCvDkowKkpGzQ3-Y0IROQ', '2026-10-06 17:00:01', NULL, 'Chặn cửa mưu sinh', 'https://vnexpress.net/chan-cua-muu-sinh-5129232.html', 25, 23, 'https://vnexpress.net/chan-cua-muu-sinh-5129232.html', 'CRAWLER', '2026-10-29 11:07:50.254072', '2026-10-29 11:07:50.254072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1559, NULL, '2026-10-29 11:03:06.317909', 'Đồng nghiệp của tôi 11h đêm mới về đến nhà, hôm 1/10. Anh cứ đứng đó thôi, không nhúc nhích được bao nhiêu trong dòng người mắc kẹt giữa các điểm ngập ở TP HCM.', 'https://i1-vnexpress.vnecdn.net/2026/10/05/20261005TrinhPhuongQuan-179120-2538-7241-1791206579.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=b6hE-ot7Bx-oAeoTz8y3jA', '2026-10-05 17:00:00', NULL, 'Thành phố bất động', 'https://vnexpress.net/thanh-pho-bat-dong-5128293.html', 25, 23, 'https://vnexpress.net/thanh-pho-bat-dong-5128293.html', 'CRAWLER', '2026-10-29 11:07:50.25709', '2026-10-29 11:07:50.25709');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1562, NULL, '2026-10-29 11:03:06.335959', 'Những câu thơ vui trong bài "Mèo con đi học" của Phan Thị Vàng Anh neo lại rất lâu trong tâm trí thế hệ học sinh 7x, 8x chúng tôi.', 'https://i1-vnexpress.vnecdn.net/2026/10/02/20261002BuiKhanhNguyen-1790958-3243-3287-1790958751.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=9xMn3V23j8m_vOCTfLQc9w', '2026-10-02 17:01:53', NULL, 'Tay không đến trường', 'https://vnexpress.net/tay-khong-den-truong-5127821.html', 25, 23, 'https://vnexpress.net/tay-khong-den-truong-5127821.html', 'CRAWLER', '2026-10-29 11:07:50.268072', '2026-10-29 11:07:50.268072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1563, NULL, '2026-10-29 11:03:06.342035', 'Đầu năm 2026, trong một bài viết về việc những vụ gây gổ, đánh nhau, cố ý gây thương tích ngày càng được xử lý quyết liệt, tôi nhận định:', 'https://i1-vnexpress.vnecdn.net/2026/10/01/20261001BuiPhuChau-1790873896-5872-1790873903.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=HwNUm8NuDLTwMVJCWe7FaQ', '2026-10-01 17:00:00', NULL, 'Cơn giận của ''ông chú vẫy xe''', 'https://vnexpress.net/con-gian-cua-ong-chu-vay-xe-5127374.html', 25, 23, 'https://vnexpress.net/con-gian-cua-ong-chu-vay-xe-5127374.html', 'CRAWLER', '2026-10-29 11:07:50.271071', '2026-10-29 11:07:50.271071');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1564, NULL, '2026-10-29 11:03:06.348029', 'Tôi ngồi chờ check-out tại sảnh một khách sạn ở Đồng Hới, cạnh một gia đình ba thế hệ. Đứa trẻ chừng 4 tuổi - đang chạy nhảy khá ồn ã, bỗng bị bà giữ lại - đã nổi cáu: “Bán bà sang Campuchia”.', 'https://i1-vnexpress.vnecdn.net/2026/10/01/20261001NguyenTheVinh-17908460-1114-6121-1790846048.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=BJ4XWZE--C4bYyZQ9LMW_w', '2026-09-30 17:00:42', NULL, 'Khi đứa con bất mãn', 'https://vnexpress.net/khi-dua-con-bat-man-5126759.html', 25, 23, 'https://vnexpress.net/khi-dua-con-bat-man-5126759.html', 'CRAWLER', '2026-10-29 11:07:50.27409', '2026-10-29 11:07:50.27409');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1566, NULL, '2026-10-29 11:03:06.36003', 'Là người đã dạy IELTS gần 20 năm, tôi vẫn đồng tình với đề xuất trong dự thảo quy chế tuyển sinh: bỏ điểm cộng chứng chỉ ngoại ngữ khi xét tuyển đại học từ năm 2027.', 'https://i1-vnexpress.vnecdn.net/2026/09/29/20260929KhoiMai-1790644318-4558-1790644320.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=PHfmRynNJb0LtYDgdAi45g', '2026-09-28 17:00:00', NULL, 'Khi 96% thí sinh chọn IELTS', 'https://vnexpress.net/khi-96-thi-sinh-chon-ielts-5125959.html', 25, 23, 'https://vnexpress.net/khi-96-thi-sinh-chon-ielts-5125959.html', 'CRAWLER', '2026-10-29 11:07:50.283095', '2026-10-29 11:07:50.283095');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1567, NULL, '2026-10-29 11:03:06.366097', 'Thuốc Đông y có hai dạng bào chế chính là thang và hoàn. Thuốc thang là các vị thuốc sắc lấy nước uống. Còn thuốc hoàn chế biến công phu hơn.', 'https://i1-vnexpress.vnecdn.net/2026/09/27/20260927QuanTheDan-1790501151-1870-1790501158.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=jfde_nPmBQ0hUkEOF_F7oQ', '2026-09-27 17:00:00', NULL, '''Thần dược'' An Cung', 'https://vnexpress.net/than-duoc-an-cung-5125372.html', 25, 23, 'https://vnexpress.net/than-duoc-an-cung-5125372.html', 'CRAWLER', '2026-10-29 11:07:50.286092', '2026-10-29 11:07:50.286092');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1568, NULL, '2026-10-29 11:03:06.373129', 'Hơn một nửa sinh viên năm cuối lớp Khoa học động vật, Đại học Texas A&M (Mỹ) bị đánh trượt thi, vì giáo sư cho rằng, họ dùng AI viết bài luận.', 'https://i1-vnexpress.vnecdn.net/2026/09/26/20260926BuiDucCuong-1790402299-7039-1790402306.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=0gXk3XZ2Et4p_Ai7P_mVww', '2026-09-26 17:00:00', NULL, 'AI ''chấm điểm'' con người', 'https://vnexpress.net/ai-cham-diem-con-nguoi-5124995.html', 25, 23, 'https://vnexpress.net/ai-cham-diem-con-nguoi-5124995.html', 'CRAWLER', '2026-10-29 11:07:50.289072', '2026-10-29 11:07:50.289072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1569, NULL, '2026-10-29 11:03:06.380034', 'Giữa tháng 9, Trung Quốc khánh thành và đưa vào vận hành kênh đào Bình Lục.', 'https://i1-vnexpress.vnecdn.net/2026/09/25/20260925DangDuong-1790353765-1120-1790354421.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=cm8ch27y0-iXkAQjFPEnyw', '2026-09-25 17:00:00', NULL, 'Từ chuyện Bình Lục 10 tỷ USD', 'https://vnexpress.net/tu-chuyen-binh-luc-10-ty-usd-5124909.html', 25, 23, 'https://vnexpress.net/tu-chuyen-binh-luc-10-ty-usd-5124909.html', 'CRAWLER', '2026-10-29 11:07:50.292072', '2026-10-29 11:07:50.292072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1570, NULL, '2026-10-29 11:03:06.387046', 'Nhà vật lý đoạt giải Nobel Richard Feynman kể lại - trong cuốn Surely You’re Joking, Mr. Feynman! (Feyman, chuyện thật như đùa) - cuộc thách đấu giữa ông và một chàng trai người Nhật chuyên tính nhanh bằng bàn tính, khi họ vô tình gặp nhau tại một quán ăn.', 'https://i1-vnexpress.vnecdn.net/2026/09/24/ba-1790268359-5845-1790268398.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=T07NNWJLaDTJHBbLeTGzlA', '2026-09-24 17:00:00', NULL, 'Toán nào mà không tư duy?', 'https://vnexpress.net/toan-nao-ma-khong-tu-duy-5124460.html', 25, 23, 'https://vnexpress.net/toan-nao-ma-khong-tu-duy-5124460.html', 'CRAWLER', '2026-10-29 11:07:50.297088', '2026-10-29 11:07:50.297088');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1571, NULL, '2026-10-29 11:03:06.394033', 'Nền tư pháp hình sự hiện đại ở gần 200 quốc gia trên thế giới ngày nay chịu ảnh hưởng mạnh từ bài luận Tội phạm và hình phạt (Dei delitti e delle pene) của một thanh niên người Italy - Cesare Bonesana di Beccaria - viết năm ông 26 tuổi.', 'https://i1-vnexpress.vnecdn.net/2026/09/24/20260923BuiPhuChau-1790226823-7795-1790226827.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=PimZ7aZ1UCguFyBkAzhG2A', '2026-09-23 17:03:41', NULL, 'Tội phạm và hình phạt', 'https://vnexpress.net/toi-pham-va-hinh-phat-5123983.html', 25, 23, 'https://vnexpress.net/toi-pham-va-hinh-phat-5123983.html', 'CRAWLER', '2026-10-29 11:07:50.300072', '2026-10-29 11:07:50.300072');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1572, NULL, '2026-10-29 11:03:06.401129', 'Dòng thông báo khẩn tìm người đàn ông bị cắn bởi một con chó vừa chết - nghi do bệnh dại - lan truyền trên mạng xã hội khiến tôi rùng mình.', 'https://i1-vnexpress.vnecdn.net/2026/09/22/20260922DaoHaiSu-1790090536-6075-1790090580.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=3Mq_wXX09MXEnwHi9jzq_Q', '2026-09-22 17:00:00', NULL, 'Tìm người bị chó cắn', 'https://vnexpress.net/tim-nguoi-bi-cho-can-5123475.html', 25, 23, 'https://vnexpress.net/tim-nguoi-bi-cho-can-5123475.html', 'CRAWLER', '2026-10-29 11:07:50.303104', '2026-10-29 11:07:50.303104');
