INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1577, NULL, '2026-10-29 11:03:06.43046', '“Trước đây 13 trường có 13 hiệu trưởng. Bây giờ chỉ còn một. Vậy khối lượng công việc thì sao, hiệu trưởng quản lý bằng cách nào?”.', 'https://i1-vnexpress.vnecdn.net/2026/09/17/20260917TruongDinhThang-178966-8862-9587-1789661104.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=83ACkN7g16a4p1_hyp3S0g', '2026-09-17 17:00:00', NULL, '''Siêu'' hiệu trưởng', 'https://vnexpress.net/sieu-hieu-truong-5121120.html', 25, 23, 'https://vnexpress.net/sieu-hieu-truong-5121120.html', 'CRAWLER', '2026-10-29 11:07:50.325071', '2026-10-29 11:07:50.325071');
