INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1594, NULL, '2026-10-29 11:03:06.527461', 'Tôi có cuộc trao đổi ngắn với một nhân viên trẻ đang làm việc tại một trường quốc tế ở Việt Nam. Câu nào của cô cũng ngắn, gần như bỏ trống chủ ngữ, hoàn toàn thiếu kính ngữ trong giao tiếp với người lớn tuổi hơn.', 'https://i1-vnexpress.vnecdn.net/2026/08/31/Dathua-1788143723-1961-1788143769.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=BhYBsfxaHYn0MuEyh92QRg', '2026-08-31 17:00:00', NULL, 'Tiếng ''dạ, thưa'' xa vắng', 'https://vnexpress.net/tieng-da-thua-xa-vang-5115325.html', 25, 23, 'https://vnexpress.net/tieng-da-thua-xa-vang-5115325.html', 'CRAWLER', '2026-10-29 11:07:50.390093', '2026-10-29 11:07:50.390093');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1595, NULL, '2026-10-29 11:03:06.533473', 'Hơn 20 năm trước, tôi được Sứ quán Việt Nam tại Washington DC giao cho một chiếc Toyota 7 chỗ để đưa đón các đoàn trong nước sang công tác tại Mỹ. Sau này, vì công việc, tôi cũng rong ruổi trên nhiều cao tốc và đường trường ở Anh, Campuchia rồi Đức, hiểu được tầm quan trọng của việc giữ khoảng cách và tốc độ an toàn trên cao tốc.', 'https://i1-vnexpress.vnecdn.net/2026/08/31/Minh-1788142575-4086-1788142579.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=LamecZjQ-DqhTO6vnnr1aw', '2026-08-30 17:00:00', NULL, 'Khoảng cách nào đáng phạt?', 'https://vnexpress.net/khoang-cach-nao-dang-phat-5115173.html', 25, 23, 'https://vnexpress.net/khoang-cach-nao-dang-phat-5115173.html', 'CRAWLER', '2026-10-29 11:07:50.394096', '2026-10-29 11:07:50.394096');
