INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1768, NULL, '2026-10-29 11:03:08.040114', 'Nhiều công ty trên thế giới đang đau đầu giải quyết mớ hỗn độn do vội vã ứng dụng AI khi công cụ chưa thực sự ổn định, dẫn đến mất thời gian của nhân viên, lộ bí mật thông tin và tăng chi phí.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/wm1-wm1-dsc09962-jpg-1793011313-9357-1793011378.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=68UBMn-53mCNOxSgF1y7gg', '2026-10-28 17:00:00', NULL, '''Vỡ mộng'' vì vội ứng dụng AI', 'https://vnexpress.net/vo-mong-vi-voi-ung-dung-ai-5137139.html', 24, 28, 'https://vnexpress.net/vo-mong-vi-voi-ung-dung-ai-5137139.html', 'CRAWLER', '2026-10-29 11:07:51.36604', '2026-10-29 11:03:08.040114');
