INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1776, NULL, '2026-10-29 11:03:08.126326', 'Đại diện Mỹ, Trung Quốc, Nhật Bản, Hàn Quốc, cùng nhiều quốc gia, khu vực đến Việt Nam, bàn về việc phát triển trí tuệ nhân tạo (AI).', 'https://i1-vnexpress.vnecdn.net/2026/10/28/wm1-tuan-le-so-2026-8-1793176557-1793176578.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=VW9TSiY6pCpPoxrOAB1n0g', '2026-10-28 12:06:58', NULL, 'Lãnh đạo khoa học công nghệ đến Việt Nam bàn về phát triển AI', 'https://vnexpress.net/lanh-dao-khoa-hoc-cong-nghe-den-viet-nam-ban-ve-phat-trien-ai-5137854.html', 24, 28, 'https://vnexpress.net/lanh-dao-khoa-hoc-cong-nghe-den-viet-nam-ban-ve-phat-trien-ai-5137854.html', 'CRAWLER', '2026-10-29 11:07:51.399485', '2026-10-29 11:03:08.126326');
