INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1778, NULL, '2026-10-29 11:03:08.144325', 'Bộ trưởng Vũ Hải Quân cho biết, để phát triển AI Việt Nam tập trung ba cam kết về hạ tầng, tạo môi trường cởi mở có chính sách hỗ trợ và hợp tác quốc tế.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/tuan-le-so-1793166203-1130-1793166266.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=NjWUyYt75RS9WQxRBvRtIA', '2026-10-28 05:45:03', NULL, 'Việt Nam tập trung ba cam kết phát triển AI', 'https://vnexpress.net/viet-nam-tap-trung-ba-cam-ket-phat-trien-ai-5137775.html', 24, 28, 'https://vnexpress.net/viet-nam-tap-trung-ba-cam-ket-phat-trien-ai-5137775.html', 'CRAWLER', '2026-10-29 11:07:51.406516', '2026-10-29 11:03:08.144325');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1780, NULL, '2026-10-29 11:03:08.162326', 'Giải thưởng Lãnh đạo Chính phủ 2026 của Hiệp hội Di động Toàn cầu (GSMA) ghi nhận Việt Nam về định hướng phát triển hạ tầng kết nối, chính sách thúc đẩy đầu tư viễn thông và các sáng kiến phổ cập kỹ năng số.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/wm1-wm1-lq-1793157099-7772-1793157107.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=59Rvkf-3kLX-46BaWV6_yA', '2026-10-28 03:33:56', NULL, 'Việt Nam nhận Giải thưởng Lãnh đạo Chính phủ của GSMA', 'https://vnexpress.net/viet-nam-nhan-giai-thuong-lanh-dao-chinh-phu-cua-gsma-5137751.html', 24, 28, 'https://vnexpress.net/viet-nam-nhan-giai-thuong-lanh-dao-chinh-phu-cua-gsma-5137751.html', 'CRAWLER', '2026-10-29 11:07:51.41518', '2026-10-29 11:03:08.162326');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1782, NULL, '2026-10-29 11:03:08.174335', 'Sử dụng mô hình nội bộ, OpenAI cho biết đã tạo ra ba kết quả nghiên cứu đột phá trong toán học, khoa học máy tính và vật lý.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/dsc00717-jpg-1793111046-6689-1793111175.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=BHra24EUrCguSUjCHBMxaw', '2026-10-27 23:04:48', NULL, 'OpenAI công bố loạt phát kiến khoa học nhờ AI', 'https://vnexpress.net/openai-cong-bo-loat-phat-kien-khoa-hoc-nho-ai-5137619.html', 24, 28, 'https://vnexpress.net/openai-cong-bo-loat-phat-kien-khoa-hoc-nho-ai-5137619.html', 'CRAWLER', '2026-10-29 11:07:51.422171', '2026-10-29 11:03:08.174335');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1783, NULL, '2026-10-29 11:03:08.181335', 'Tuần lễ Số 2026 diễn ra trong ba ngày tại Quảng Ninh, quy tụ 500 đại biểu, gồm đại diện cơ quan quản lý, tổ chức quốc tế và doanh nghiệp công nghệ trong và ngoài nước.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/wm1-wm1-dsc-jpg-1793090403-2190-1793090465.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=CYnl963mAUnq3GOoS8wwqQ', '2026-10-27 19:00:00', NULL, 'Hôm nay diễn ra Tuần lễ Số Quốc tế Việt Nam 2026', 'https://vnexpress.net/hom-nay-dien-ra-tuan-le-so-quoc-te-viet-nam-2026-5137461.html', 24, 28, 'https://vnexpress.net/hom-nay-dien-ra-tuan-le-so-quoc-te-viet-nam-2026-5137461.html', 'CRAWLER', '2026-10-29 11:07:51.425154', '2026-10-29 11:03:08.181335');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1784, NULL, '2026-10-29 11:03:08.187334', 'Nhu cầu làm mát Data Center, cùng sự phát triển của bất động sản, công nghiệp, tạo dư địa mở rộng mảng giải pháp không khí (HVAC) cho nhóm doanh nghiệp, theo ông Hyung Bin Joo.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/jooo-1793175875-2989-1793175960.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=T8256NF5J457P9yPS-yIKA', '2026-10-28 09:00:00', NULL, 'Chủ tịch Samsung Việt Nam: Đô thị hóa, AI ''mở khóa'' ngành HVAC', 'https://vnexpress.net/chu-tich-samsung-viet-nam-do-thi-hoa-ai-mo-khoa-nganh-hvac-5137933.html', 24, 28, 'https://vnexpress.net/chu-tich-samsung-viet-nam-do-thi-hoa-ai-mo-khoa-nganh-hvac-5137933.html', 'CRAWLER', '2026-10-29 11:07:51.430168', '2026-10-29 11:03:08.187334');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1785, NULL, '2026-10-29 11:03:08.194331', 'MacBook Pro 14 inch cùng iMac phiên bản 2026 nâng cấp vi xử lý lên Apple M6, pin 24 tiếng nhưng giữ nguyên kiểu dáng, các lựa chọn màu sắc.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/apple-macbook-pro-in-with-m-17-2119-9788-1793110075.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=mpjSTEcYJ-w0kPHXDxYEzQ', '2026-10-27 14:08:59', NULL, 'Apple nâng cấp iMac và MacBook Pro 14 inch với chip M6', 'https://vnexpress.net/apple-nang-cap-imac-va-macbook-pro-14-inch-voi-chip-m6-5137613.html', 24, 28, 'https://vnexpress.net/apple-nang-cap-imac-va-macbook-pro-14-inch-voi-chip-m6-5137613.html', 'CRAWLER', '2026-10-29 11:07:51.434184', '2026-10-29 11:03:08.194331');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1786, NULL, '2026-10-29 11:03:08.201335', 'Một doanh nhân người Trung Quốc cải tiến chiếc xe máy chạy hơn 40 km trên mặt sông Thần chảy qua tỉnh Hồ Nam, phá vỡ kỷ lục thế giới trước đó là 31,8 km.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/e42dd4c44dda4f8cad1b54064b69b9-6794-2200-1793089961.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=oz47duWm4HJhveAC9tsfsg&t=image', '2026-10-27 08:00:00', NULL, 'Xe máy cải tiến lập kỷ lục chạy trên mặt nước', 'https://vnexpress.net/xe-may-cai-tien-lap-ky-luc-chay-tren-mat-nuoc-5137396.html', 24, 28, 'https://vnexpress.net/xe-may-cai-tien-lap-ky-luc-chay-tren-mat-nuoc-5137396.html', 'CRAWLER', '2026-10-29 11:07:51.437168', '2026-10-29 11:03:08.201335');
