INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1790, NULL, '2026-10-29 11:03:08.22933', 'Việt Nam và Lào nghiên cứu phương án thí điểm công nhận lẫn nhau về chữ ký số, trước mắt trong lĩnh vực hải quan và xuất nhập khẩu hàng hóa.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/chu-ky-so-1793100878-4619-1793100939.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=okAeILSHjDkF7ZzCsklNQw', '2026-10-27 12:01:16', NULL, 'Việt Nam - Lào nghiên cứu công nhận chéo chữ ký số', 'https://vnexpress.net/viet-nam-lao-nghien-cuu-cong-nhan-cheo-chu-ky-so-5137596.html', 24, 28, 'https://vnexpress.net/viet-nam-lao-nghien-cuu-cong-nhan-cheo-chu-ky-so-5137596.html', 'CRAWLER', '2026-10-29 11:07:51.451328', '2026-10-29 11:03:08.22933');
