INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1849, NULL, '2026-10-29 11:03:08.735637', '5 tỷ đồng gửi ngân hàng, lãi tiết kiệm hơn 30 triệu một tháng, cao hơn cả mức lương đang nhận hiện tại, bạn tôi nói: ''Sao phải đi làm?''.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/wm37-wm37-capturejpg177414476041971-5024-8872-1792660663.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=i8iLOvQtBRSXTLxjedRsiQ', '2026-10-22 17:00:00', NULL, 'Tính toán nghỉ hưu sớm khi có 5 tỷ gửi tiết kiệm', 'https://vnexpress.net/tu-do-tai-chinh-fire-tinh-toan-nghi-huu-som-khi-co-5-ty-gui-tiet-kiem-5135679.html', 27, 29, 'https://vnexpress.net/tu-do-tai-chinh-fire-tinh-toan-nghi-huu-som-khi-co-5-ty-gui-tiet-kiem-5135679.html', 'CRAWLER', '2026-10-29 11:07:52.111008', '2026-10-29 11:07:52.111008');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1850, NULL, '2026-10-29 11:03:08.74245', '''Thi hai môn, việc cạnh tranh sẽ gay gắt hơn, từng chút điểm một. Chỉ một sơ suất nhỏ cũng khiến học sinh nguy cơ trượt lớp 10''.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/wm1wm12b571e59cd1d6e43370c1791-9395-4851-1792746530.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=9w2LLqrSwNQcFZgGS0Tu2g', '2026-10-23 12:00:00', NULL, 'Giằng co bỏ Tiếng Anh, chỉ thi Văn và Toán vào lớp 10', 'https://vnexpress.net/giang-co-bo-tieng-anh-chi-thi-van-va-toan-vao-lop-10-5136128.html', 27, 29, 'https://vnexpress.net/giang-co-bo-tieng-anh-chi-thi-van-va-toan-vao-lop-10-5136128.html', 'CRAWLER', '2026-10-29 11:07:52.119005', '2026-10-29 11:07:52.119005');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1852, NULL, '2026-10-29 11:03:08.757448', 'Dâu da, trứng cá, trúc đào, bồ hòn... bị Hà Nội cấm trồng nhưng hoa sữa, dù tạo ra tranh luận trái chiều, lại không nằm trong danh sách.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/179212161317921216268763179212-1436-5900-1792643470.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=7JqrYcrFzHRwUl8SFMgl4Q', '2026-10-22 12:00:00', NULL, 'Vì sao Hà Nội không cấm trồng hoa sữa?', 'https://vnexpress.net/vi-sao-ha-noi-khong-cam-trong-hoa-sua-5135539.html', 27, 29, 'https://vnexpress.net/vi-sao-ha-noi-khong-cam-trong-hoa-sua-5135539.html', 'CRAWLER', '2026-10-29 11:07:52.131324', '2026-10-29 11:07:52.131324');
