INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1859, NULL, '2026-10-29 11:03:08.807758', 'Người thỉnh thoảng đi ngang sẽ thấy mùi hoa sữa nồng nàn, người sống tại con phố đó sẽ thấy nồng nặc.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/12-9191-1792565108.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Y83Uf5BINlGZq51Y9giZGw', '2026-10-21 08:49:40', NULL, 'Mùi hoa sữa Hà Nội từ ''nồng nàn thành nồng nặc''', 'https://vnexpress.net/mui-hoa-sua-ha-noi-tu-nong-nan-thanh-nong-nac-5135085.html', 27, 29, 'https://vnexpress.net/mui-hoa-sua-ha-noi-tu-nong-nan-thanh-nong-nac-5135085.html', 'CRAWLER', '2026-10-29 11:07:52.167286', '2026-10-29 11:07:52.167286');
