INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1885, NULL, '2026-10-29 11:03:09.095349', 'Khát khao được là chính mình lớn đến mức có thời điểm, sự kiên nhẫn cạn kiệt đã đưa em đến một quyết định liều lĩnh.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/gemini-generated-image-pqy4nlp-7898-1734-1793175534.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=qEy6Aqc2FvzpoDxPzN87dw', '2026-10-28 10:00:00', NULL, 'Câu chuyện dám sống thật với bản thân ở tuổi 15', 'https://vnexpress.net/cau-chuyen-dam-song-that-voi-ban-than-o-tuoi-15-5137937.html', 28, 30, 'https://vnexpress.net/cau-chuyen-dam-song-that-voi-ban-than-o-tuoi-15-5137937.html', 'CRAWLER', '2026-10-29 11:07:52.326455', '2026-10-29 11:07:52.326455');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1886, NULL, '2026-10-29 11:03:09.10335', 'Dù cuối cùng có đi đến ly hôn hay không, tôi vẫn mong mọi việc được giải quyết văn minh, công bằng và không ảnh hưởng đến con.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/gemini-generated-image-j01gcsj-9661-8593-1793172737.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=sSyqd-3FdofyROukzY9baA', '2026-10-28 07:43:21', NULL, 'Tôi không phục cách vợ chia tiền tiết kiệm sau 6 năm chung sống', 'https://vnexpress.net/toi-khong-phuc-cach-vo-chia-tien-tiet-kiem-sau-6-nam-chung-song-5137762.html', 28, 30, 'https://vnexpress.net/toi-khong-phuc-cach-vo-chia-tien-tiet-kiem-sau-6-nam-chung-song-5137762.html', 'CRAWLER', '2026-10-29 11:07:52.331477', '2026-10-29 11:07:52.331477');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1888, NULL, '2026-10-29 11:03:09.120293', 'Tôi có nên nói cho bạn gái của anh ta biết anh ta là kẻ tồi, lừa dối phụ nữ không hay tôi cứ mặc kệ họ?', 'https://i1-vnexpress.vnecdn.net/2026/10/27/GeminiGeneratedImageexseatexse-4438-5665-1793092306.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Te-2aiz9kENff0EhwUQDng', '2026-10-27 17:00:00', NULL, 'Bạn trai bắt cá hai tay, tôi có nên nói cho cô gái kia biết?', 'https://vnexpress.net/ban-trai-bat-ca-hai-tay-toi-co-nen-noi-cho-co-gai-kia-biet-5137353.html', 28, 30, 'https://vnexpress.net/ban-trai-bat-ca-hai-tay-toi-co-nen-noi-cho-co-gai-kia-biet-5137353.html', 'CRAWLER', '2026-10-29 11:07:52.340454', '2026-10-29 11:07:52.340454');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1889, NULL, '2026-10-29 11:03:09.129196', 'Những thứ tạo thành tài sản dường như đều gắn với tên chồng, còn những nghĩa vụ tài chính và khoản nợ thì tôi lại trực tiếp gánh khá nhiều.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/PensiveDuskintheApartment-1793-5115-9528-1793089574.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=qxd9JR0KbXtq-Q7vu_uQyA', '2026-10-27 09:00:00', NULL, 'Nhà đất, ôtô đều đứng tên chồng, còn tôi đứng tên nợ', 'https://vnexpress.net/nha-dat-oto-deu-dung-ten-chong-con-toi-dung-ten-no-5137440.html', 28, 30, 'https://vnexpress.net/nha-dat-oto-deu-dung-ten-chong-con-toi-dung-ten-no-5137440.html', 'CRAWLER', '2026-10-29 11:07:52.346455', '2026-10-29 11:07:52.346455');
