INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1922, NULL, '2026-10-29 11:03:09.390515', 'Tôi đang sống chỗ mình không muốn ở, làm công việc mà mình không muốn làm, lại nhớ người yêu nữa.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/gemini-generated-image-lbg1ukl-4449-5575-1792590925.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=ozqeIn1bvlDEtz2C7tzTMA', '2026-10-22 02:00:00', NULL, 'Muốn từ bỏ công việc và ''cảnh ở nhờ'' để đi theo tiếng gọi tình yêu', 'https://vnexpress.net/muon-tu-bo-cong-viec-va-canh-o-nho-de-di-theo-tieng-goi-tinh-yeu-5133646.html', 28, 30, 'https://vnexpress.net/muon-tu-bo-cong-viec-va-canh-o-nho-de-di-theo-tieng-goi-tinh-yeu-5133646.html', 'CRAWLER', '2026-10-29 11:07:52.500886', '2026-10-29 11:07:52.500886');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1924, NULL, '2026-10-29 11:03:09.406142', 'Tôi không có bằng chứng cho thấy họ làm điều sai trái, nhưng đôi khi lo lắng khi tưởng tượng hai người trở nên thân thiết hơn mức cần thiết.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/gemini-generated-imagefu8895fu-6249-7670-1792652508.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=RAw7K4hyBtFJt9alrHJXJg', '2026-10-22 07:20:32', NULL, 'Không để bạn trai và bạn thân có nhiều cơ hội gặp gỡ riêng tư', 'https://vnexpress.net/khong-de-ban-trai-va-ban-than-co-nhieu-co-hoi-gap-go-rieng-tu-5135586.html', 28, 30, 'https://vnexpress.net/khong-de-ban-trai-va-ban-than-co-nhieu-co-hoi-gap-go-rieng-tu-5135586.html', 'CRAWLER', '2026-10-29 11:07:52.507869', '2026-10-29 11:07:52.507869');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1925, NULL, '2026-10-29 11:03:09.41414', 'Nghĩ đến việc rời xa anh, tôi không đành lòng; anh có những điểm tốt, từng nhịn chi tiêu để mua quà cho tôi và cũng quan tâm tôi lắm.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/gemini-generated-image-t03wnrt-7567-2816-1792654906.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=HAKjuK_lIBqB2bPX1jHYkQ', '2026-10-22 09:00:00', NULL, 'Chưa rõ bạn trai có con riêng không thì lại biết nhà anh nợ vài tỷ đồng', 'https://vnexpress.net/chua-ro-ban-trai-co-con-rieng-khong-thi-lai-biet-nha-anh-no-vai-ty-dong-5135613.html', 28, 30, 'https://vnexpress.net/chua-ro-ban-trai-co-con-rieng-khong-thi-lai-biet-nha-anh-no-vai-ty-dong-5135613.html', 'CRAWLER', '2026-10-29 11:07:52.512898', '2026-10-29 11:07:52.512898');
