INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1960, NULL, '2026-10-29 11:03:09.786066', 'Hãy quan sát thật kỹ từng nhân vật, thử suy luận bằng logic và đừng để vẻ ngoài đánh lừa nhé.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/gemini-generated-image-v3uzpvv-1986-4616-1792742190.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=fafrBEOqxnastjKouUsxSg', '2026-10-25 06:31:00', NULL, 'Ai mới là người thực sự nghèo?', 'https://vnexpress.net/ai-moi-la-nguoi-thuc-su-ngheo-5136053.html', 29, 31, 'https://vnexpress.net/ai-moi-la-nguoi-thuc-su-ngheo-5136053.html', 'CRAWLER', '2026-10-29 11:07:52.797621', '2026-10-29 11:07:52.797621');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1961, NULL, '2026-10-29 11:03:09.792919', 'Châu Á có ngọn núi cao nhất hành tinh gần 8.849 mét, nằm giữa những dãy núi hùng vĩ và là thử thách lớn của các nhà leo núi.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/1-1792549420-9856-1792549616.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=tMw_61qu-Eh1nri13BWbuA', '2026-10-25 05:00:00', NULL, 'Đỉnh núi nào cao gần 8.849 mét, cao nhất châu Á?', 'https://vnexpress.net/crossword-giai-o-chu-o-chu-dinh-nui-nao-cao-gan-8-849-met-cao-nhat-chau-a-5134947.html', 29, 31, 'https://vnexpress.net/crossword-giai-o-chu-o-chu-dinh-nui-nao-cao-gan-8-849-met-cao-nhat-chau-a-5134947.html', 'CRAWLER', '2026-10-29 11:07:52.802605', '2026-10-29 11:07:52.802605');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1962, NULL, '2026-10-29 11:03:09.800932', '''Đắt như tôm tươi'' là câu nói quen thuộc trong đời sống, nhưng không phải ai cũng hiểu vì sao món tôm tươi lại trở thành cách ví von này.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/gemini-generated-image-sn7gr1s-6694-5393-1792728580.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=DfbE1vvV7VY-Zc_WlGl-lA', '2026-10-25 02:45:00', NULL, 'Vì sao người Việt nói ''đắt như tôm tươi''?', 'https://vnexpress.net/vi-sao-nguoi-viet-noi-dat-nhu-tom-tuoi-5135963.html', 29, 31, 'https://vnexpress.net/vi-sao-nguoi-viet-noi-dat-nhu-tom-tuoi-5135963.html', 'CRAWLER', '2026-10-29 11:07:52.806605', '2026-10-29 11:07:52.806605');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1963, NULL, '2026-10-29 11:03:09.809022', 'Nhận được thông báo của tài xế trên đường Southern State Parkway (New York), các nhà chức trách đã có mặt để giúp gia đình thiên nga khỏi nguy hiểm.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/Document-1792652135-1899-1792653683.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=EWQ6KejIUX0gQhtaeLdcMQ', '2026-10-25 01:00:00', NULL, 'Cảnh sát giao thông chặn đường cao tốc giải cứu gia đình thiên nga', 'https://vnexpress.net/canh-sat-giao-thong-chan-duong-cao-toc-giai-cuu-gia-dinh-thien-nga-5135580.html', 29, 31, 'https://vnexpress.net/canh-sat-giao-thong-chan-duong-cao-toc-giai-cuu-gia-dinh-thien-nga-5135580.html', 'CRAWLER', '2026-10-29 11:07:52.812605', '2026-10-29 11:07:52.812605');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1964, NULL, '2026-10-29 11:03:09.817029', 'Nhờ kinh nghiệm, nhạy bén, khả năng quản lý tiền bạc, họ có cơ hội cải thiện thu nhập, tích lũy của cải, tận hưởng cuộc sống sung túc hơn.', 'https://i1-vnexpress.vnecdn.net/2026/10/24/gemini-generated-imagea09336a0-1872-9565-1792833868.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=vyAckru_0r_rIjD7ZfoNeQ', '2026-10-24 17:01:00', NULL, '4 con giáp đếm tiền mỏi tay ở tuổi trung niên', 'https://vnexpress.net/4-con-giap-dem-tien-moi-tay-o-tuoi-trung-nien-5136175.html', 29, 31, 'https://vnexpress.net/4-con-giap-dem-tien-moi-tay-o-tuoi-trung-nien-5136175.html', 'CRAWLER', '2026-10-29 11:07:52.816634', '2026-10-29 11:07:52.816634');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1965, NULL, '2026-10-29 11:03:09.825017', 'Nhờ sự chăm chỉ, nhạy bén cùng khả năng nắm bắt thời cơ, họ có thể mở ra những hướng phát triển tài chính đáng kỳ vọng.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/gemini-generated-image-j505j6j-9479-3680-1792752299.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=OP-t67CJu8mfaZahv2tUEQ', '2026-10-23 17:02:00', NULL, '3 con giáp thăng tiến vượt bậc về tài lộc vào cuối tuần', 'https://vnexpress.net/3-con-giap-thang-tien-vuot-bac-ve-tai-loc-vao-cuoi-tuan-5136161.html', 29, 31, 'https://vnexpress.net/3-con-giap-thang-tien-vuot-bac-ve-tai-loc-vao-cuoi-tuan-5136161.html', 'CRAWLER', '2026-10-29 11:07:52.820606', '2026-10-29 11:07:52.820606');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1966, NULL, '2026-10-29 11:03:09.833025', 'Thử thách tư duy hình ảnh dân gian cực kỳ thú vị, bạn có đủ tinh mắt để giải mã câu thành ngữ dự báo thời tiết nổi tiếng này?', 'https://i1-vnexpress.vnecdn.net/2026/10/23/d9d83f8f-f4f5-4628-8959-e7861b-4209-6265-1792727298.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=VtGcKluo1fga3PomYnMm0w', '2026-10-24 06:40:00', NULL, 'Đây là câu thành ngữ chỉ thời tiết nào?', 'https://vnexpress.net/day-la-cau-thanh-ngu-chi-thoi-tiet-nao-5135941.html', 29, 31, 'https://vnexpress.net/day-la-cau-thanh-ngu-chi-thoi-tiet-nao-5135941.html', 'CRAWLER', '2026-10-29 11:07:52.824621', '2026-10-29 11:07:52.824621');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1967, NULL, '2026-10-29 11:03:09.841022', 'Châu Á có dòng sông dài hơn 6.300 km, gắn với lịch sử, kinh tế và đời sống của hàng trăm triệu người, nhưng không phải ai cũng nhớ tên.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/3-1792548584-1329-1792548805.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=WW6CzRp-dh1BIStOjs3Ivw', '2026-10-24 05:00:00', NULL, 'Sông nào dài hơn 6.300 km, dài nhất châu Á?', 'https://vnexpress.net/crossword-giai-o-chu-o-chu-song-nao-dai-hon-6-300-km-dai-nhat-chau-a-5134910.html', 29, 31, 'https://vnexpress.net/crossword-giai-o-chu-o-chu-song-nao-dai-hon-6-300-km-dai-nhat-chau-a-5134910.html', 'CRAWLER', '2026-10-29 11:07:52.829606', '2026-10-29 11:07:52.829606');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1968, NULL, '2026-10-29 11:03:09.850041', 'Câu đố mẹo độc đáo kết hợp giữa ngôn ngữ dân gian và thực tế đời sống đang khiến cộng đồng mạng rủ nhau vò đầu bứt tóc suy đoán!', 'https://i1-vnexpress.vnecdn.net/2026/10/22/gemini-generated-image-oogrp1o-4317-7645-1792639937.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=xxE_EsyOl0s-QERswPrsEw', '2026-10-24 02:45:00', NULL, 'Loài lúa nào kỳ lạ đến mức ''ba năm không chín''?', 'https://vnexpress.net/loai-lua-nao-ky-la-den-muc-ba-nam-khong-chin-5131687.html', 29, 31, 'https://vnexpress.net/loai-lua-nao-ky-la-den-muc-ba-nam-khong-chin-5131687.html', 'CRAWLER', '2026-10-29 11:07:52.833617', '2026-10-29 11:07:52.833617');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1969, NULL, '2026-10-29 11:03:09.858025', 'Chú dê con sổng chuồng đã đến sân chơi của một trường tiểu học ở New York và đuổi theo các học sinh trước khi bị cảnh sát bắt giữ.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/ezgif4d26f423731c0e19-17926545-2083-1860-1792655086.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=0e3yPylLtj2a6o6MuNpNSw&t=image', '2026-10-24 01:00:00', NULL, 'Dê con sổng chuồng chạy vào trường tiểu học chơi cùng học sinh', 'https://vnexpress.net/de-con-song-chuong-chay-vao-truong-tieu-hoc-choi-cung-hoc-sinh-5135581.html', 29, 31, 'https://vnexpress.net/de-con-song-chuong-chay-vao-truong-tieu-hoc-choi-cung-hoc-sinh-5135581.html', 'CRAWLER', '2026-10-29 11:07:52.837626', '2026-10-29 11:07:52.837626');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1970, NULL, '2026-10-29 11:03:09.867021', 'Những nỗ lực bền bỉ, khả năng nắm bắt thời cơ và quyết định sáng suốt có thể giúp họ mở rộng cơ hội phát triển trong thời gian tới.', 'https://i1-vnexpress.vnecdn.net/2026/10/22/gemini-generated-images0sh82s0-1253-2515-1792665936.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=t7fVwZDLO1kDBqFCu66i_w', '2026-10-22 17:01:00', NULL, 'Ba con giáp trở nên giàu có từ ngày 22/10', 'https://vnexpress.net/ba-con-giap-tro-nen-giau-co-tu-ngay-22-10-5135689.html', 29, 31, 'https://vnexpress.net/ba-con-giap-tro-nen-giau-co-tu-ngay-22-10-5135689.html', 'CRAWLER', '2026-10-29 11:07:52.840624', '2026-10-29 11:07:52.840624');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1974, NULL, '2026-10-29 11:03:09.898932', 'Thử thách này mang tính quy luật cơ thể độc đáo khiến cư dân mạng rủ nhau suy đoán, bạn có đủ nhanh trí tìm ra lời giải chuẩn xác?', 'https://i1-vnexpress.vnecdn.net/2026/10/22/gemini-generated-imagefd52p9fd-5934-6171-1792640226.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=eN8Rys1JaYMXwRDI1s8Ppg', '2026-10-23 01:57:25', NULL, 'Cái gì đi cũng nằm, đứng cũng nằm, nhưng nằm lại... đứng?', 'https://vnexpress.net/cai-gi-di-cung-nam-dung-cung-nam-nhung-nam-lai-dung-5135501.html', 29, 31, 'https://vnexpress.net/cai-gi-di-cung-nam-dung-cung-nam-nhung-nam-lai-dung-5135501.html', 'CRAWLER', '2026-10-29 11:07:52.859612', '2026-10-29 11:07:52.859612');
