INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1999, NULL, '2026-10-29 11:03:10.183247', 'TP HCM trải qua chuỗi ngày mưa liên tục dồn vào cuối mùa với lượng mưa phá vỡ kỷ lục 46 năm, trái ngược với những tháng đầu mùa ít mưa bất thường.', 'https://i1-vnexpress.vnecdn.net/2026/10/15/Lark20261015201414-1792070080-3202-1792070158.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=7F8YlAmJG7SF-9G5W7_Ltg&t=image', '2026-10-15 22:00:00', NULL, 'Mùa mưa dị thường ở TP HCM', 'https://vnexpress.net/mua-mua-di-thuong-o-tp-hcm-5132888.html', 30, 32, 'https://vnexpress.net/mua-mua-di-thuong-o-tp-hcm-5132888.html', 'CRAWLER', '2026-10-29 11:07:53.094046', '2026-10-29 11:07:53.094046');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2000, NULL, '2026-10-29 11:03:10.190263', 'Sau hơn hai thập kỷ theo đuổi mục tiêu xóa ngập triệt để, trong tầm nhìn quy hoạch mới, TP HCM chuyển đổi tư duy sang "quản lý rủi ro ngập ở mức chấp nhận được".', 'https://i1-vnexpress.vnecdn.net/2026/10/06/top-1791271173-2026-1791271188.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=gHLmsRv-OZhkNN_grAuEeA', '2026-10-07 22:00:00', NULL, 'TP HCM định sống chung với ngập thế nào', 'https://vnexpress.net/tp-hcm-dinh-song-chung-voi-ngap-the-nao-5129043.html', 30, 32, 'https://vnexpress.net/tp-hcm-dinh-song-chung-voi-ngap-the-nao-5129043.html', 'CRAWLER', '2026-10-29 11:07:53.099045', '2026-10-29 11:07:53.099045');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2001, NULL, '2026-10-29 11:03:10.199263', '“Con ước có thể hát cho tía nghe, dù con hát chưa hay. Con ước có thể vẽ tranh cho tía ngắm, dù trình độ chưa có gì cao siêu. Con ước tía có thể thấy con đã trưởng thành hơn đến nhường nào. Ở trên cao, tía có biết không, tía?”.', 'https://i1-vnexpress.vnecdn.net/2026/09/08/20260908105319-1788839633-6756-1788839640.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=rWnXRcPm5efhlYjVWvFiuQ', '2026-09-07 22:00:00', NULL, 'Lời hứa trưởng thành của những đứa trẻ mồ côi', 'https://vnexpress.net/loi-hua-truong-thanh-cua-nhung-dua-tre-mo-coi-5117416.html', 30, 32, 'https://vnexpress.net/loi-hua-truong-thanh-cua-nhung-dua-tre-mo-coi-5117416.html', 'CRAWLER', '2026-10-29 11:07:53.103045', '2026-10-29 11:07:53.103045');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2002, NULL, '2026-10-29 11:03:10.207264', 'Khi ông Trương Gia Bình nêu ý tưởng mở ngôi trường nuôi dạy trẻ mồ côi do Covid, nhiều người nghi ngờ và phản đối. Họ tin rằng để các em bên người thân mới là cách tốt nhất để "chữa lành" nỗi đau Covid để lại.', 'https://i1-vnexpress.vnecdn.net/2026/09/07/Tau1-1788702233-7064-1788719453.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=CoLVTJXKlAR3FapYH5E86Q', '2026-09-06 22:00:00', NULL, '''Ván cược'' vì những đứa trẻ mồ côi', 'https://vnexpress.net/van-cuoc-vi-nhung-dua-tre-mo-coi-5117162.html', 30, 32, 'https://vnexpress.net/van-cuoc-vi-nhung-dua-tre-mo-coi-5117162.html', 'CRAWLER', '2026-10-29 11:07:53.107059', '2026-10-29 11:07:53.107059');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2003, NULL, '2026-10-29 11:03:10.216247', 'Trong phạm vi dưới 60 phút di chuyển, hành trình đi xe buýt đến bất kỳ ga Metro số 1 nào cũng chậm hơn xe máy, với thời gian trung bình gấp đôi.', 'https://i1-vnexpress.vnecdn.net/2026/08/03/20260803Thumb1-1785765126-3526-1785765235.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=OrzJwrMVtbrY5vHlmQs9MQ', '2026-08-03 22:00:00', NULL, 'Xe buýt đến metro chậm hơn xe máy bao nhiêu lần?', 'https://vnexpress.net/xe-buyt-den-metro-cham-hon-xe-may-bao-nhieu-lan-5100710.html', 30, 32, 'https://vnexpress.net/xe-buyt-den-metro-cham-hon-xe-may-bao-nhieu-lan-5100710.html', 'CRAWLER', '2026-10-29 11:07:53.113049', '2026-10-29 11:07:53.113049');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2004, NULL, '2026-10-29 11:03:10.223263', 'Trong vòng một giờ, xe buýt có thể kết nối người dân ở khu vực cách các ga Metro số 1 (Bến Thành - Suối Tiên) khoảng 6-7 km với nhà ga. Càng về tối, phạm vi kết nối này càng thu hẹp.', 'https://i1-vnexpress.vnecdn.net/2026/08/03/ScreenRecording20260803at06294-8108-7182-1785714241.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=_pr9Pa0R2L6-XsINQ-x1kA&t=image', '2026-08-02 22:00:00', NULL, 'Mạng lưới xe buýt ''phủ'' quanh metro thế nào', 'https://vnexpress.net/mang-luoi-xe-buyt-phu-quanh-metro-the-nao-5097624.html', 30, 32, 'https://vnexpress.net/mang-luoi-xe-buyt-phu-quanh-metro-the-nao-5097624.html', 'CRAWLER', '2026-10-29 11:07:53.118077', '2026-10-29 11:07:53.118077');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2005, NULL, '2026-10-29 11:03:10.23127', 'Tờ giám định ADN xác minh danh tính liệt sĩ khép lại ba mươi năm ròng vợ chồng ông Dương, bà Miến đi tìm hài cốt cha.', 'https://i1-vnexpress.vnecdn.net/2026/07/28/HUY-3969-6430-1785255438.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=YC18UKAwriokUATloJ6z2w', '2026-07-28 22:00:00', NULL, 'Tìm ẩn số ADN trong hài cốt liệt sĩ', 'https://vnexpress.net/tim-an-so-adn-trong-hai-cot-liet-si-5101927.html', 30, 32, 'https://vnexpress.net/tim-an-so-adn-trong-hai-cot-liet-si-5101927.html', 'CRAWLER', '2026-10-29 11:07:53.122068', '2026-10-29 11:07:53.122068');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2006, NULL, '2026-10-29 11:03:10.239262', 'Không họ, năm sinh, phiên hiệu đơn vị, hài cốt liệt sĩ "Tuyến" mất nửa thế kỷ mới có thể đoàn tụ cùng gia đình. Các mảnh ghép giúp lấp đầy danh tính ông nằm tại ba nơi, xa nhất cách nửa vòng trái đất.', 'https://i1-vnexpress.vnecdn.net/2026/07/28/20260728top2-1785196643-5150-1785196646.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=I-Wxw_UfnUF2a7rRkeQGxg', '2026-07-27 22:00:00', NULL, 'Những mảnh ghép trong danh tính liệt sĩ', 'https://vnexpress.net/nhung-manh-ghep-trong-danh-tinh-liet-si-5101774.html', 30, 32, 'https://vnexpress.net/nhung-manh-ghep-trong-danh-tinh-liet-si-5101774.html', 'CRAWLER', '2026-10-29 11:07:53.128051', '2026-10-29 11:07:53.128051');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2007, NULL, '2026-10-29 11:03:10.248278', 'Hầu hết cuộc tìm kiếm, quy tập hài cốt liệt sĩ bắt đầu từ một manh mối: ký ức của những nhân chứng đang già đi từng ngày.', 'https://i1-vnexpress.vnecdn.net/2026/07/26/Ba-i-1-9102-1785081720.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=lg9dd5uzryqc7XjgHiJb7A', '2026-07-26 22:00:00', NULL, 'Cuộc chạy đua với ký ức phai mờ để đưa liệt sĩ trở về', 'https://vnexpress.net/cuoc-chay-dua-voi-ky-uc-phai-mo-de-dua-liet-si-tro-ve-5101714.html', 30, 32, 'https://vnexpress.net/cuoc-chay-dua-voi-ky-uc-phai-mo-de-dua-liet-si-tro-ve-5101714.html', 'CRAWLER', '2026-10-29 11:07:53.134044', '2026-10-29 11:07:53.134044');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2008, NULL, '2026-10-29 11:03:10.256248', 'Ở tuổi U60, bà Devaki Murch vẫn tiếp tục cuộc tìm kiếm xuyên đại dương, nhặt nhạnh những mảnh ghép còn trống để lấp đầy câu hỏi về căn tính của mình.', 'https://i1-vnexpress.vnecdn.net/2026/07/21/20260721top22-1784629830-7399-1784629844.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=UXDsY6sVTkOg6JZi28ryFQ', '2026-07-21 23:00:00', NULL, 'Những ''đứa trẻ U60'' tìm nơi thuộc về', 'https://vnexpress.net/nhung-dua-tre-u60-tim-noi-thuoc-ve-5099166.html', 30, 32, 'https://vnexpress.net/nhung-dua-tre-u60-tim-noi-thuoc-ve-5099166.html', 'CRAWLER', '2026-10-29 11:07:53.13906', '2026-10-29 11:07:53.13906');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2010, NULL, '2026-10-29 11:03:10.272347', 'Cuối tháng 6 năm ngoái, ông Phan Ngọc Phúc - khi ấy là Phó giám đốc Sở Xây dựng TP HCM - được triệu tập gấp về trụ sở Thành uỷ TP HCM. Thông điệp được đưa ra: "Cán bộ trẻ có sẵn sàng về địa phương không?".', 'https://i1-vnexpress.vnecdn.net/2026/07/15/Xa-Nha-Be-19-2839-1784078045.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=DHytaX0YN64ZbmBAmdmHtA', '2026-07-13 22:00:00', NULL, 'Bình thường mới của cán bộ TP HCM', 'https://vnexpress.net/binh-thuong-moi-cua-can-bo-tp-hcm-5096761.html', 30, 32, 'https://vnexpress.net/binh-thuong-moi-cua-can-bo-tp-hcm-5096761.html', 'CRAWLER', '2026-10-29 11:07:53.150078', '2026-10-29 11:07:53.150078');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2011, NULL, '2026-10-29 11:03:10.281374', 'Từ giữa tháng tư đến khi các nghị quyết được ban hành, nhiều cán bộ các bộ, ngành gần như làm việc liên tục tại Bộ Tư pháp. Mỗi khi phát sinh một điểm vướng, họ tranh luận tại chỗ và phương án chỉnh sửa được đưa ra ngay trên bản dự thảo.', 'https://i1-kinhdoanh.vnecdn.net/2026/07/13/graphicDKKD-1783901652-2487-1783902261.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=yeybHczEvxz1LPfNURuOuw', '2026-07-13 00:25:08', NULL, 'Cuộc cải cách môi trường kinh doanh ''chưa từng có''', 'https://vnexpress.net/cuoc-cai-cach-moi-truong-kinh-doanh-chua-tung-co-5091182.html', 30, 32, 'https://vnexpress.net/cuoc-cai-cach-moi-truong-kinh-doanh-chua-tung-co-5091182.html', 'CRAWLER', '2026-10-29 11:07:53.153926', '2026-10-29 11:07:53.153926');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2012, NULL, '2026-10-29 11:03:10.288263', 'Cậu bé 14 tuổi vừa nhận kết quả nghi nhiễm HIV ngẩng lên hỏi Đỗ Duy Vị: "Tại sao anh không gặp em sớm hơn?" - Đó là một trong nhiều câu hỏi khiến Co-CEO Blue Dragon day dứt suốt gần hai thập kỷ làm công việc giải cứu trẻ em.', 'https://i1-vnexpress.vnecdn.net/2026/07/12/Thumb1800x1080-1783863277-7115-1783863352.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=rpRE9RSc95XQzJfNRWvxrg', '2026-07-12 23:00:00', NULL, 'Ước mơ thất nghiệp của CEO từng là trẻ đánh giày', 'https://vnexpress.net/uoc-mo-that-nghiep-cua-ceo-tung-la-tre-danh-giay-5096561.html', 30, 32, 'https://vnexpress.net/uoc-mo-that-nghiep-cua-ceo-tung-la-tre-danh-giay-5096561.html', 'CRAWLER', '2026-10-29 11:07:53.157919', '2026-10-29 11:07:53.157919');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2013, NULL, '2026-10-29 11:03:10.29725', 'Trong hơn 4.700 thủ tục hành chính công công khai trên Cổng dịch vụ công Quốc gia, Bộ Tài chính là cơ quan đảm nhiệm nhiều thủ tục nhất. Trong khi, Bộ Công an tiếp nhận nhiều nhiệm vụ, chức năng mới nhất.', 'https://i1-vnexpress.vnecdn.net/2026/07/09/20260709settop-1783530951-4767-1783530964.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=q24UTu_JFBotLoX_w14nxQ', '2026-07-09 22:00:00', NULL, '''Dòng chảy'' thủ tục hành chính sau một năm tinh gọn', 'https://vnexpress.net/dong-chay-thu-tuc-hanh-chinh-sau-mot-nam-tinh-gon-5094576.html', 30, 32, 'https://vnexpress.net/dong-chay-thu-tuc-hanh-chinh-sau-mot-nam-tinh-gon-5094576.html', 'CRAWLER', '2026-10-29 11:07:53.163918', '2026-10-29 11:07:53.163918');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2014, NULL, '2026-10-29 11:03:10.305351', 'Một năm sau cuộc sắp xếp, tinh gọn tổ chức bộ máy trên toàn quốc, cơ cấu hệ thống chính trị từ Trung ương đến địa phương đã có những thay đổi lớn nhất trong nhiều thập niên.', 'https://i1-vnexpress.vnecdn.net/2026/07/08/TopNewBO1-1783470167-9696-1783470170.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=_QvQysQJhOwyJ46qS0KPyw&t=image', '2026-07-07 23:00:00', NULL, 'Hệ thống chính trị thay đổi thế nào sau một năm tinh gọn?', 'https://vnexpress.net/he-thong-chinh-tri-thay-doi-the-nao-sau-mot-nam-tinh-gon-5091870.html', 30, 32, 'https://vnexpress.net/he-thong-chinh-tri-thay-doi-the-nao-sau-mot-nam-tinh-gon-5091870.html', 'CRAWLER', '2026-10-29 11:07:53.168913', '2026-10-29 11:07:53.168913');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2015, NULL, '2026-10-29 11:03:10.314249', 'Từ kỹ sư bị đối tác phớt lờ đến tổng công trình sư xây nên 600 nhân sự bán dẫn, đưa chi nhánh Việt Nam vào top 3 trung tâm R&D Marvell toàn cầu, ông Lê Quang Đạm tin vào giá trị từng bước tiến nhỏ thay vì bước nhảy vọt.', 'https://i1-vnexpress.vnecdn.net/2026/06/21/Thumb1800x1080-1782046260-3591-1782046309.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=P3V0_YPepE2zm7oF6JaOrw', '2026-06-21 23:00:00', NULL, 'Người đưa tập đoàn bán dẫn tỷ đô về Việt Nam: ''Chọn đi xa nhất thay vì nhanh nhất''', 'https://vnexpress.net/nguoi-dua-tap-doan-ban-dan-ty-do-ve-viet-nam-chon-di-xa-nhat-thay-vi-nhanh-nhat-5083110.html', 30, 32, 'https://vnexpress.net/nguoi-dua-tap-doan-ban-dan-ty-do-ve-viet-nam-chon-di-xa-nhat-thay-vi-nhanh-nhat-5083110.html', 'CRAWLER', '2026-10-29 11:07:53.172925', '2026-10-29 11:07:53.172925');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2016, NULL, '2026-10-29 11:03:10.322349', '12 tuổi nhặt bao nylon kiếm sống, tầm nhìn chỉ đóng khung trong miếng ăn, 60 năm sau anh Lương Việt Quốc sáng chế ra UAV đầu tiên xuất khẩu được sang Mỹ, đưa Việt Nam bước lên sân chơi công nghệ thế giới.', 'https://i1-vnexpress.vnecdn.net/2026/06/06/Thumb1800x1080Opt1-1780750621-2965-1780750664.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=jP06SHHjjXNDU83lI1p76g', '2026-06-07 23:00:00', NULL, 'Người Việt đầu tiên xuất khẩu UAV sang Mỹ: ''Với tôi, nghèo là lợi thế''', 'https://vnexpress.net/nguoi-viet-dau-tien-xuat-khau-uav-sang-my-voi-toi-ngheo-la-loi-the-5082785.html', 30, 32, 'https://vnexpress.net/nguoi-viet-dau-tien-xuat-khau-uav-sang-my-voi-toi-ngheo-la-loi-the-5082785.html', 'CRAWLER', '2026-10-29 11:07:53.179024', '2026-10-29 11:07:53.179024');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2017, NULL, '2026-10-29 11:03:10.332351', 'Khi nghề làm quạt ở Chàng Sơn ngày càng mai một, nghệ nhân Nguyễn Quang Hồng tìm cách cùng con trai đưa công nghệ vào làm mới quy trình sản xuất, giúp vực dậy và phát triển nghề truyền thống.', 'https://i1-vnexpress.vnecdn.net/2026/06/05/20260605224049ezgifcomresize-1-3394-8241-1780674312.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=XEzCPGiSsJwOsYUU6uyZ_w&t=image', '2026-06-05 23:00:00', NULL, 'Quạt Chàng Sơn: Vực dậy nghề thủ công bằng công nghệ', 'https://vnexpress.net/quat-chang-son-vuc-day-nghe-thu-cong-bang-cong-nghe-5080614.html', 30, 32, 'https://vnexpress.net/quat-chang-son-vuc-day-nghe-thu-cong-bang-cong-nghe-5080614.html', 'CRAWLER', '2026-10-29 11:07:53.185027', '2026-10-29 11:07:53.185027');
