INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2020, NULL, '2026-10-29 11:03:10.360254', 'Dữ liệu từ hồ sơ người dùng LinkedIn tại Việt Nam cho thấy lộ trình sự nghiệp phổ biến, từ ngành học đến ngành nghề đầu tiên và công việc hiện tại của 70 ngành nghề, cũng như các chứng chỉ thường được người lao động cập nhật.', 'https://i1-vnexpress.vnecdn.net/2026/05/08/20260508ngang-1778253026-9956-1778253164.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=peEZ9QbTvHunuwvOr0ZsnA', '2026-05-08 23:00:00', NULL, 'Con đường sự nghiệp từ ngành học đến ngành nghề', 'https://vnexpress.net/con-duong-su-nghiep-tu-nganh-hoc-den-nganh-nghe-5071511.html', 30, 32, 'https://vnexpress.net/con-duong-su-nghiep-tu-nganh-hoc-den-nganh-nghe-5071511.html', 'CRAWLER', '2026-10-29 11:07:53.199931', '2026-10-29 11:07:53.199931');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2021, NULL, '2026-10-29 11:03:10.369262', 'Hồ sơ của hơn 600.000 người dùng LinkedIn tại Việt Nam cho thấy Lập trình máy tính và Công nghệ thông tin là ngành có tốc độ phát triển bùng nổ nhất 40 năm qua, trong khi ngành Pháp luật và Kế toán đang sụt giảm nhân lực mới nhanh chóng.', 'https://i1-vnexpress.vnecdn.net/2026/05/05/top-1777998114-2787-1777998163.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=dwEEP3xyRmsgNCfnlULh3w', '2026-05-05 23:00:00', NULL, 'Dữ liệu LinkedIn tiết lộ gì về thị trường lao động Việt Nam?', 'https://vnexpress.net/du-lieu-linkedin-tiet-lo-gi-ve-thi-truong-lao-dong-viet-nam-5069953.html', 30, 32, 'https://vnexpress.net/du-lieu-linkedin-tiet-lo-gi-ve-thi-truong-lao-dong-viet-nam-5069953.html', 'CRAWLER', '2026-10-29 11:07:53.203979', '2026-10-29 11:07:53.203979');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2022, NULL, '2026-10-29 11:03:10.378253', 'Nếu việc làm khai sinh vẫn bế tắc, Anh Thư (9 tuổi, TP HCM) có thể phải dừng học, theo mẹ đi bán vé số - nghề không cần chứng minh danh tính.', 'https://i1-vnexpress.vnecdn.net/2026/04/27/Tre0danhtinhCover2-1777258281-6205-1777258284.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Rdm1ykJqlwOmVUqbad5uJg', '2026-04-27 23:00:00', NULL, 'Những đứa trẻ không danh tính', 'https://vnexpress.net/nhung-dua-tre-khong-danh-tinh-5065461.html', 30, 32, 'https://vnexpress.net/nhung-dua-tre-khong-danh-tinh-5065461.html', 'CRAWLER', '2026-10-29 11:07:53.207738', '2026-10-29 11:07:53.207738');
