INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2024, NULL, '2026-10-29 11:03:10.396254', 'Sau khi kiện toàn vào cuối tháng 4, tất cả bí thư, chủ tịch 34 tỉnh, thành đều là nam, trong đó có hai Ủy viên Bộ Chính trị, 43 Ủy viên Trung ương và ba Ủy viên dự khuyết.', 'https://i1-vnexpress.vnecdn.net/2026/04/24/2026042434tinhthanh-1776994824-8095-1776994827.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=k8yJ7gp-DPoBuJfSP5Iu-g', '2026-04-24 07:39:31', NULL, 'Bí thư và Chủ tịch 34 tỉnh thành sau kiện toàn', 'https://vnexpress.net/bi-thu-va-chu-tich-34-tinh-thanh-sau-kien-toan-5060343.html', 30, 32, 'https://vnexpress.net/bi-thu-va-chu-tich-34-tinh-thanh-sau-kien-toan-5060343.html', 'CRAWLER', '2026-10-29 11:07:53.218662', '2026-10-29 11:07:53.218662');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2025, NULL, '2026-10-29 11:03:10.405348', 'Quốc hội vừa bầu và phê chuẩn các chức danh lãnh đạo khối Nhà nước, góp phần hoàn thiện bộ máy lãnh đạo của hệ thống chính trị nhiệm kỳ 2026-2031 gồm Đảng, Nhà nước và Mặt trận Tổ quốc Việt Nam.', 'https://i1-vnexpress.vnecdn.net/2026/04/11/20260411settopbomaychinhtri-17-9931-6656-1775922506.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=tJs8-_W-GfzSZZrJqNgmYA', '2026-04-14 02:30:00', NULL, 'Bộ máy lãnh đạo hệ thống chính trị nhiệm kỳ 2026-2031', 'https://vnexpress.net/bo-may-lanh-dao-he-thong-chinh-tri-nhiem-ky-2026-2031-5051346.html', 30, 32, 'https://vnexpress.net/bo-may-lanh-dao-he-thong-chinh-tri-nhiem-ky-2026-2031-5051346.html', 'CRAWLER', '2026-10-29 11:07:53.222674', '2026-10-29 11:07:53.222674');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2026, NULL, '2026-10-29 11:03:10.414248', 'Từ một người luôn đạt kết quả nhờ tư duy logic, Nguyễn Trọng Tấn bước vào vai trò CEO và nhận ra chính cách làm việc đó lại đẩy đội ngũ ra xa. Bài kiểm tra lãnh đạo buộc anh đối diện với điểm yếu lớn nhất: không biết cách kết nối con người.', 'https://i1-vnexpress.vnecdn.net/2026/04/12/Thumb1800x1080-1775966592-4286-1775966627.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=xJhRNEKrkzWXoEqyBE1WBg', '2026-04-12 23:00:00', NULL, 'CEO Chợ Tốt từng đối mặt ''bài toán khó nhất'': con người', 'https://vnexpress.net/ceo-cho-tot-tung-doi-mat-bai-toan-kho-nhat-con-nguoi-5061385.html', 30, 32, 'https://vnexpress.net/ceo-cho-tot-tung-doi-mat-bai-toan-kho-nhat-con-nguoi-5061385.html', 'CRAWLER', '2026-10-29 11:07:53.228644', '2026-10-29 11:07:53.228644');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2027, NULL, '2026-10-29 11:03:10.422346', 'Từ vị trí nhà đầu tư tại quỹ mạo hiểm ở Singapore, Nguyễn Hoàng Hiệp rời “bên rót tiền” để bước sang phía gọi vốn cho startup và ngay lập tức bị ngó lơ bởi những người từng coi là bạn.', 'https://i1-vnexpress.vnecdn.net/2026/03/22/Thumb1800x10801-1774194301-7908-1774194307.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=M5CIH5dXwF2NKaF0jjynOA', '2026-03-22 23:00:00', NULL, 'Nguyễn Hoàng Hiệp - 24 lần bị từ chối và canh bạc AI Việt', 'https://vnexpress.net/nguyen-hoang-hiep-24-lan-bi-tu-choi-va-canh-bac-ai-viet-5053502.html', 30, 32, 'https://vnexpress.net/nguyen-hoang-hiep-24-lan-bi-tu-choi-va-canh-bac-ai-viet-5053502.html', 'CRAWLER', '2026-10-29 11:07:53.232673', '2026-10-29 11:07:53.232673');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2028, NULL, '2026-10-29 11:03:10.431371', 'Từ một thực tập sinh không lương đi xe đạp đến Chủ tịch FPT Retail, Nguyễn Bạch Điệp gần như luôn “đi lên” suốt 30 năm tại FPT. Nhưng năm 2019, khi vốn hóa FPT Shop bốc hơi hàng nghìn tỷ đồng, bà lần đầu rơi vào cảm giác “hết bài”.', 'https://i1-vnexpress.vnecdn.net/2026/03/08/Thumb1800x1080-1772986002-2017-1772986244.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=vO50d7NFzuNA3aKQZgOPNw', '2026-03-08 23:30:00', NULL, 'Chủ tịch chuỗi Long Châu: ''Từng tự hỏi mình có thật sự giỏi?''', 'https://vnexpress.net/chu-tich-chuoi-long-chau-tung-tu-hoi-minh-co-that-su-gioi-5048052.html', 30, 32, 'https://vnexpress.net/chu-tich-chuoi-long-chau-tung-tu-hoi-minh-co-that-su-gioi-5048052.html', 'CRAWLER', '2026-10-29 11:07:53.237645', '2026-10-29 11:07:53.237645');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2030, NULL, '2026-10-29 11:03:10.45', 'Bỏ nhà khi chưa ai tin, lăn lộn 16 năm để vào đoàn xiếc hàng đầu thế giới, anh Tuấn Lê vẫn rời đỉnh cao, quay về Việt Nam "đặt cược" vào giấc mơ lớn hơn.', 'https://i1-vnexpress.vnecdn.net/2026/02/21/Thumb1800x1080-1771660692-6474-1771661641.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=_7O8VeGUck3olq8dWyBMIA', '2026-02-22 22:00:00', NULL, 'Hai lần ''tất tay'' của người đưa xiếc Việt ra thế giới', 'https://vnexpress.net/hai-lan-tat-tay-cua-nguoi-dua-xiec-viet-ra-the-gioi-5042678.html', 30, 32, 'https://vnexpress.net/hai-lan-tat-tay-cua-nguoi-dua-xiec-viet-ra-the-gioi-5042678.html', 'CRAWLER', '2026-10-29 11:07:53.254641', '2026-10-29 11:07:53.254641');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2031, NULL, '2026-10-29 11:03:10.458764', 'Đinh Văn Bốp (10 tuổi, xã Sơn Hà, Quảng Ngãi) tưởng tượng Tết sẽ có thịt heo luộc ăn với mì tôm, và năm nay có đoàn từ thiện về, tặng hai anh em ba bộ quần áo như năm ngoái. Nhưng đó vẫn chỉ là điều ước.', 'https://i1-vnexpress.vnecdn.net/2026/02/05/Ve-sinh-ho-c-du-o-ng-137-1335-1770280635.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=L8CbtVYfVzjXDnyw9eF_Ww', '2026-02-05 23:00:00', NULL, 'Tết trong vòng lặp thiếu thốn', 'https://vnexpress.net/tet-trong-vong-lap-thieu-thon-5014143.html', 30, 32, 'https://vnexpress.net/tet-trong-vong-lap-thieu-thon-5014143.html', 'CRAWLER', '2026-10-29 11:07:53.262646', '2026-10-29 11:07:53.262646');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2032, NULL, '2026-10-29 11:03:10.467755', 'Hơn 36 năm kinh nghiệm tại môi trường học thuật quốc tế, GS Ngô Bảo Châu cho rằng để xây dựng nội lực khoa học, Việt Nam cần chủ động săn đón và mời gọi nhân tài về nước, kết hợp với đào tạo tại chỗ để nuôi dưỡng nguồn nhân lực từ bên trong.', 'https://i1-vnexpress.vnecdn.net/2026/02/05/484586226289574163059834335673-7229-5649-1770251567.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=YolpGKaJYSutUKuyCXDlGA', '2026-02-04 23:00:00', NULL, 'GS Ngô Bảo Châu: Thu hút nhân tài không thể chờ tự ứng cử', 'https://vnexpress.net/gs-ngo-bao-chau-thu-hut-nhan-tai-khong-the-cho-tu-ung-cu-5013395.html', 30, 32, 'https://vnexpress.net/gs-ngo-bao-chau-thu-hut-nhan-tai-khong-the-cho-tu-ung-cu-5013395.html', 'CRAWLER', '2026-10-29 11:07:53.267643', '2026-10-29 11:07:53.267643');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2033, NULL, '2026-10-29 11:03:10.477653', 'Hơn hai tháng ngủ tạm trong chuồng bò, gia đình chị Hồ Thị Ngọc Trân (30 tuổi, Đăk Lăk) vẫn giật mình mỗi khi mái tôn va vào gió - âm thanh gợi lại lúc nhà sập. Sau lũ, họ quyết dựng lại mái nhà mong kịp an cư đón Tết.', 'https://i1-vnexpress.vnecdn.net/2026/02/02/bul0379jpg17696575391191176965-4331-9642-1770045588.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=e_CtcIiOuKiKrha1_lnu0Q', '2026-02-02 23:00:00', NULL, '''Chạy Tết'' sau lũ', 'https://vnexpress.net/chay-tet-sau-lu-5011225.html', 30, 32, 'https://vnexpress.net/chay-tet-sau-lu-5011225.html', 'CRAWLER', '2026-10-29 11:07:53.272643', '2026-10-29 11:07:53.272643');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2034, NULL, '2026-10-29 11:03:10.486751', 'Sau lũ, ký ức của cụ Đinh Thị Thục (78 tuổi) dừng lại ở bữa cơm cuối với con. Mỗi sáng ra chợ, cụ mua và nấu đúng món ông thích, dọn mâm đặt trước di ảnh, như thể ông vẫn còn đâu đây.', 'https://i1-vnexpress.vnecdn.net/2026/01/28/BaThucJPG176921721051951769217-6675-2732-1769534938.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=GDflBRa4h6siUoVAZK1qKQ', '2026-01-27 23:00:00', NULL, 'Những căn nhà ''khuyết'' nơi rốn lũ', 'https://vnexpress.net/nhung-can-nha-khuyet-noi-ron-lu-5009376.html', 30, 32, 'https://vnexpress.net/nhung-can-nha-khuyet-noi-ron-lu-5009376.html', 'CRAWLER', '2026-10-29 11:07:53.279643', '2026-10-29 11:07:53.279643');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2035, NULL, '2026-10-29 11:03:10.495652', 'Trong 200 Ủy viên Trung ương khóa XIV có 19 người được bầu vào Bộ Chính trị. Khối địa phương có 67 Ủy viên, số còn lại công tác tại các cơ quan Trung ương.', 'https://i1-vnexpress.vnecdn.net/2026/01/23/20260123settop-1769129177-8237-1769129216.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=R4ToEQh2epXvao_NkX7Xfg', '2026-01-24 02:50:42', NULL, 'Tiểu sử 200 Ủy viên Trung ương; 19 Ủy viên Bộ Chính trị khoá XIV', 'https://vnexpress.net/tieu-su-200-uy-vien-trung-uong-19-uy-vien-bo-chinh-tri-khoa-xiv-5008899.html', 30, 32, 'https://vnexpress.net/tieu-su-200-uy-vien-trung-uong-19-uy-vien-bo-chinh-tri-khoa-xiv-5008899.html', 'CRAWLER', '2026-10-29 11:07:53.285642', '2026-10-29 11:07:53.285642');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2036, NULL, '2026-10-29 11:03:10.504664', 'Tưởng chấm dứt sự nghiệp ở tuổi 48, bà Ngô Thị Vân Hạnh nhận lời dẫn con tàu Yeah1 đang thua lỗ trong cuộc chơi “còn hoặc mất”. Ba tháng sản xuất “bán mạng”, bà Hạnh đã tạo nên những concert ken đặc khán giả.', 'https://i1-vnexpress.vnecdn.net/2026/01/18/Thumb1800x1080-1768712791-5288-1768712933.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=BZ0zlKLNbfeUmGP-RIBq0A', '2026-01-18 23:00:00', NULL, 'Nữ CEO và cú cược ''Anh trai vượt ngàn chông gai''', 'https://vnexpress.net/nu-ceo-va-cu-cuoc-anh-trai-vuot-ngan-chong-gai-5006335.html', 30, 32, 'https://vnexpress.net/nu-ceo-va-cu-cuoc-anh-trai-vuot-ngan-chong-gai-5006335.html', 'CRAWLER', '2026-10-29 11:07:53.290641', '2026-10-29 11:07:53.290641');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2037, NULL, '2026-10-29 11:03:10.51465', 'Bị bỏ trong bụi rậm khi mới hơn một tuần tuổi, Trương Thị Bích Diễm khóc đến nổ hai con ngươi mắt. Nhưng số phận mù loà không ngăn được đam mê đàn hát của chị.', 'https://i1-vnexpress.vnecdn.net/2026/01/13/Ho-i-ngu-o-i-mu-Tam-Ky-01-4377-1768294455.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=lu6OnV7tr-YKXj1pQXs3-Q', '2026-01-13 23:00:00', NULL, 'Phận mù trong định kiến', 'https://vnexpress.net/phan-mu-trong-dinh-kien-5004168.html', 30, 32, 'https://vnexpress.net/phan-mu-trong-dinh-kien-5004168.html', 'CRAWLER', '2026-10-29 11:07:53.296643', '2026-10-29 11:07:53.296643');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2038, NULL, '2026-10-29 11:03:10.522748', 'Là con gái đầu của nhà sáng lập Biti’s, Vưu Lệ Quyên từng kháng cự hoàn cảnh của mình, cho rằng áp lực từ gia đình quá khắc nghiệt, và rơi vào khủng hoảng hiện sinh khi nhận ra mình đã sống quá lâu theo kỳ vọng của người khác.', 'https://i1-vnexpress.vnecdn.net/2026/01/05/VuuLeQuyen-1767570866-9074-1767570870.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=WOF_50wirZWbiuB4QjLjjQ', '2026-01-04 23:00:00', NULL, 'Người kế nghiệp Biti''s: Cuộc thử lửa vượt bóng di sản', 'https://vnexpress.net/nguoi-ke-nghiep-biti-s-cuoc-thu-lua-vuot-bong-di-san-5001420.html', 30, 32, 'https://vnexpress.net/nguoi-ke-nghiep-biti-s-cuoc-thu-lua-vuot-bong-di-san-5001420.html', 'CRAWLER', '2026-10-29 11:07:53.301643', '2026-10-29 11:07:53.301643');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2039, NULL, '2026-10-29 11:03:10.532747', 'Trung ương yêu cầu phá đập Long Sơn để cứu hồ, nhưng nguyên Chủ tịch UBND Quảng Nam (cũ) Lê Trí Tập kiên quyết phản đối. Ông chấp nhận thế chấp sự nghiệp chính trị để tìm cách khác cứu dân.', 'https://i1-vnexpress.vnecdn.net/2025/12/30/20251230settopb3-1767085680-5962-1767085876.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=N9deVsZqzKsdPc1GWDPUSQ', '2025-12-30 23:00:00', NULL, 'Chuẩn bị cho tương lai thiên tai khắc nghiệt', 'https://vnexpress.net/chuan-bi-cho-tuong-lai-thien-tai-khac-nghiet-4999883.html', 30, 32, 'https://vnexpress.net/chuan-bi-cho-tuong-lai-thien-tai-khac-nghiet-4999883.html', 'CRAWLER', '2026-10-29 11:07:53.306642', '2026-10-29 11:07:53.306642');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2041, NULL, '2026-10-29 11:03:10.551141', 'Sắp tới 49 ngày của ba, nhưng gia đình anh Lê Tấn Đường (39 tuổi) không biết giờ, ngày chính xác ông qua đời để làm lễ cúng. Họ chỉ đoán ông đi vào đêm nước lớn 19/11 - lũ “đánh úp” khu phố Nam Bình 1, phường Đông Hoà, Đăk Lăk.', 'https://i1-vnexpress.vnecdn.net/2025/12/27/nhanvathoaxuan1987-1766848656-6765-7296-1766848695.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=c8mhzQgdgKwlV83h4-6PFg', '2025-12-27 23:00:00', NULL, 'Những vết sẹo tinh thần sau thiên tai', 'https://vnexpress.net/nhung-vet-seo-tinh-than-sau-thien-tai-4998104.html', 30, 32, 'https://vnexpress.net/nhung-vet-seo-tinh-than-sau-thien-tai-4998104.html', 'CRAWLER', '2026-10-29 11:07:53.320642', '2026-10-29 11:07:53.320642');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2042, NULL, '2026-10-29 11:03:10.560036', 'Năm 2025 khép lại với hàng loạt quyết sách và biến động mang tính bản lề, từ cải cách bộ máy hành chính, hoạch định chiến lược phát triển quốc gia, đến những chuyển động sâu rộng trong kinh tế, hạ tầng, khoa học công nghệ và đời sống xã hội.', 'https://i1-vnexpress.vnecdn.net/2025/12/23/settop10sukien-1766481927-1766-6368-8129-1766484004.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=o7h987h00EYVzisrWih9jA', '2025-12-24 17:00:00', NULL, '10 sự kiện chính trị - xã hội 2025', 'https://vnexpress.net/10-su-kien-chinh-tri-xa-hoi-2025-4996859.html', 30, 32, 'https://vnexpress.net/10-su-kien-chinh-tri-xa-hoi-2025-4996859.html', 'CRAWLER', '2026-10-29 11:07:53.325642', '2026-10-29 11:07:53.325642');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2043, NULL, '2026-10-29 11:03:10.570138', 'Bộ Chính trị khóa 13 hiện có 16 ủy viên, là cơ quan lãnh đạo cao nhất của Đảng giữa hai kỳ họp Trung ương; Ban Bí thư gồm 10 người, giúp Ban Chấp hành Trung ương và Bộ Chính trị chỉ đạo, tổ chức thực hiện nhiệm vụ.', 'https://i1-vnexpress.vnecdn.net/2025/12/25/20251225144300-1766648615-7353-1766648633.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=sRbpLJ27MYsw8HtPg3jZmQ', '2025-12-24 03:00:38', NULL, 'Danh sách Ủy viên Bộ Chính trị, Ban Bí thư khóa 13', 'https://vnexpress.net/danh-sach-uy-vien-bo-chinh-tri-ban-bi-thu-khoa-13-4997620.html', 30, 32, 'https://vnexpress.net/danh-sach-uy-vien-bo-chinh-tri-ban-bi-thu-khoa-13-4997620.html', 'CRAWLER', '2026-10-29 11:07:53.332642', '2026-10-29 11:07:53.332642');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2044, NULL, '2026-10-29 11:03:10.579034', 'Hàng chục đứa trẻ Hrê trên dưới 10 tuổi chia thành hai phe - trai và gái - đứng đối diện nhau giữa sân trường, thảo luận phân chia "lãnh thổ" vệ sinh.', 'https://i1-vnexpress.vnecdn.net/2025/12/22/nuocnia100-1766413817-17664138-6007-8521-1766419246.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=1tjNbN3TJKVIkS_tIa9JSQ', '2025-12-22 23:00:00', NULL, 'Những đứa trẻ sợ tè', 'https://vnexpress.net/nhung-dua-tre-so-te-4996621.html', 30, 32, 'https://vnexpress.net/nhung-dua-tre-so-te-4996621.html', 'CRAWLER', '2026-10-29 11:07:53.337643', '2026-10-29 11:07:53.337643');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2045, NULL, '2026-10-29 11:03:10.58813', 'Lê Hồng Minh - từ một “game thủ” mê công nghệ đến người sáng lập VNG - tin rằng tuổi trẻ có quyền thử và quyền sai. Ông vẫn khuyến khích con gái: “cứ yêu nhiều cho đến khi tự thấy đúng”.', 'https://i1-vnexpress.vnecdn.net/2025/12/22/ChutichVNGLeHongMinh-176638862-4189-2311-1766388626.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=256b4Cu4HF44J3q4s-13AQ', '2025-12-21 23:00:00', NULL, 'Chủ tịch VNG: ''Thử gì cũng được, miễn đừng chết''', 'https://vnexpress.net/chu-tich-vng-thu-gi-cung-duoc-mien-dung-chet-4993905.html', 30, 32, 'https://vnexpress.net/chu-tich-vng-thu-gi-cung-duoc-mien-dung-chet-4993905.html', 'CRAWLER', '2026-10-29 11:07:53.342642', '2026-10-29 11:07:53.342642');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2046, NULL, '2026-10-29 11:03:10.598147', 'Sau 5 năm xây dựng, dự án thành phần quan trọng nhất của sân bay Long Thành đạt gần 64% khối lượng và đang thi công ngày đêm để kịp khai thác thương mại vào tháng 6/2026.', 'https://i1-vnexpress.vnecdn.net/2025/12/18/top-1766044789-2896-1766044805.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=E19wJyXfjUxlioaHVOQ9ag&t=image', '2025-12-19 23:00:00', NULL, 'Tiến độ thi công sân bay Long Thành hiện ra sao?', 'https://vnexpress.net/tien-do-thi-cong-san-bay-long-thanh-hien-ra-sao-4995456.html', 30, 32, 'https://vnexpress.net/tien-do-thi-cong-san-bay-long-thanh-hien-ra-sao-4995456.html', 'CRAWLER', '2026-10-29 11:07:53.349374', '2026-10-29 11:07:53.349374');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2048, NULL, '2026-10-29 11:03:10.619858', 'Trong khi các đô thị ô nhiễm trên thế giới ngày càng cải thiện chỉ số PM2.5, Hà Nội liên tiếp xuất hiện trong top các thành phố có chất lượng không khí tệ nhất, dù nhiều chính sách kiểm soát được đặt ra trong hơn 10 năm qua.', 'https://i1-vnexpress.vnecdn.net/2025/12/02/20251202134825-1764658130-1764-2979-6186-1764658154.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=XORhtEW6CDgQ8prjJ4uQpg', '2025-12-02 23:00:00', NULL, 'Tại sao Hà Nội ‘mắc kẹt’ trong vòng xoáy ô nhiễm không khí?', 'https://vnexpress.net/tai-sao-ha-noi-mac-ket-trong-vong-xoay-o-nhiem-khong-khi-4955752.html', 30, 32, 'https://vnexpress.net/tai-sao-ha-noi-mac-ket-trong-vong-xoay-o-nhiem-khong-khi-4955752.html', 'CRAWLER', '2026-10-29 11:07:53.369377', '2026-10-29 11:07:53.369377');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2049, NULL, '2026-10-29 11:03:10.630761', 'Ô nhiễm không khí do bụi mịn PM2.5 khiến mỗi người dân Hà Nội chịu tổn hại sức khỏe tương đương việc hút thụ động hai điếu thuốc lá mỗi ngày.', 'https://i1-vnexpress.vnecdn.net/2025/12/02/hgn09927-2504-1764631212-17646-4971-6878-1764634305.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=-ysTGK34gU41wwVbVBIDHA', '2025-12-01 23:00:00', NULL, 'Người Hà Nội ''hút'' thụ động bao nhiêu điếu thuốc mỗi ngày do ô nhiễm?', 'https://vnexpress.net/nguoi-ha-noi-hut-thu-dong-bao-nhieu-dieu-thuoc-moi-ngay-do-o-nhiem-4988529.html', 30, 32, 'https://vnexpress.net/nguoi-ha-noi-hut-thu-dong-bao-nhieu-dieu-thuoc-moi-ngay-do-o-nhiem-4988529.html', 'CRAWLER', '2026-10-29 11:07:53.378377', '2026-10-29 11:07:53.378377');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2050, NULL, '2026-10-29 11:03:10.63986', 'Giữa màn đêm đen kịt, anh Nguyễn Văn Hần (42 tuổi) ngồi co ro trên nóc chuồng bò. Nhìn đàn bò 18 con chìm dần trong dòng nước lũ, anh không dám nghĩ đến cha mẹ và hai đứa con nhỏ ở nhà.', 'https://i1-vnexpress.vnecdn.net/2025/11/26/top-1764094946-6568-1764095710-5494-1382-1764118455.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=WoHQxkUYW1Heqng1Fa3Qiw', '2025-11-25 23:00:00', NULL, 'Đêm vô vọng ở rốn lũ Hòa Thịnh', 'https://vnexpress.net/dem-vo-vong-o-ron-lu-hoa-thinh-4947063.html', 30, 32, 'https://vnexpress.net/dem-vo-vong-o-ron-lu-hoa-thinh-4947063.html', 'CRAWLER', '2026-10-29 11:07:53.387377', '2026-10-29 11:07:53.387377');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1098, NULL, '2026-10-29 11:03:03.613022', 'Cố gắng rẽ trái khi xe container đang chuyển hướng, đầu xe con bị mắc và xé toạc, hôm 27/10 tại Đặng Kinh.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/download-1793149454-5409-1793150048.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=OiSo2_3FVwxgkefNFwqXXw&t=image', '2026-10-28 07:38:17', NULL, 'Cố rẽ cạnh xe container, ôtô con toạc đầu', 'https://vnexpress.net/co-re-canh-xe-container-oto-con-toac-dau-5137681.html', 12, 16, 'https://vnexpress.net/co-re-canh-xe-container-oto-con-toac-dau-5137681.html', 'CRAWLER', '2026-10-29 11:07:47.835988', '2026-10-29 11:03:03.613022');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1101, NULL, '2026-10-29 11:03:03.619991', 'Bản đặc biệt kỷ niệm 80 năm thành lập, giới hạn 1.946 xe toàn thế giới, trong đó bốn xe bán ở Việt Nam đánh số 396, 696, 796, 799.', 'https://i1-vnexpress.vnecdn.net/2026/10/27/vespagtsroma8010-1793087041-7767-1793087369.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=MViLrsbiVrsF07zRbulmLQ', '2026-10-27 22:00:00', NULL, '4 xe Vespa Edizione Ottantesimo về Việt Nam, giá 372 triệu đồng', 'https://vnexpress.net/4-xe-vespa-edizione-ottantesimo-ve-viet-nam-gia-372-trieu-dong-5137433.html', 12, 16, 'https://vnexpress.net/4-xe-vespa-edizione-ottantesimo-ve-viet-nam-gia-372-trieu-dong-5137433.html', 'CRAWLER', '2026-10-29 11:07:47.857985', '2026-10-29 11:03:03.619991');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1110, NULL, '2026-10-29 11:03:03.64099', 'Chủ chiếc X9 bức xúc vì túi khí không bung khi xe lật, nhưng Xpeng khẳng định các dữ liệu kỹ thuật cho thấy va chạm chưa đủ điều kiện.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/xpengx91-1793003768-1422-1793003777.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=NpZw3QpvoJvSqG4jH7XRrg', '2026-10-26 22:00:00', NULL, 'Túi khí không bung sau va chạm, hãng nói ''chưa đủ điều kiện''', 'https://vnexpress.net/tui-khi-khong-bung-sau-va-cham-hang-noi-chua-du-dieu-kien-5137047.html', 12, 16, 'https://vnexpress.net/tui-khi-khong-bung-sau-va-cham-hang-noi-chua-du-dieu-kien-5137047.html', 'CRAWLER', '2026-10-29 11:07:47.929988', '2026-10-29 11:03:03.64099');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2052, NULL, '2026-10-29 11:03:10.657858', 'Tính đến 23h, mục lũ tại trạm Củng Sơn và Phú Lâm trên sông Ba ở Đăk Lăk (Phú Yên cũ) đã vượt mức lịch sử năm 1993, và trạm Ninh Hoà trên sông Cái Dinh, Khánh Hoà, đã cao hơn lũ lịch sử năm 1986.', 'https://i1-vnexpress.vnecdn.net/2025/11/19/Screenshot20251119at220709-176-2392-4222-1763564964.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=DLhkb6Zlb8bLTGbdEGw-3w', '2025-11-19 02:32:11', NULL, 'Lũ sông ở Đăk Lăk, Khánh Hoà vượt mức lịch sử', 'https://vnexpress.net/lu-song-o-dak-lak-khanh-hoa-vuot-muc-lich-su-4962647.html', 30, 32, 'https://vnexpress.net/lu-song-o-dak-lak-khanh-hoa-vuot-muc-lich-su-4962647.html', 'CRAWLER', '2026-10-29 11:07:53.406375', '2026-10-29 11:07:53.406375');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2053, NULL, '2026-10-29 11:03:10.666846', 'Nhìn bụng con căng cứng như sắp nổ, chị Hồ Thị Giang (23 tuổi, Huế) tuyệt vọng. Nguồn tạng hiến từ người chết não khan hiếm, trong khi con bị xơ gan giai đoạn cuối. Vợ chồng chị giằng co quyết định ai là người hiến gan cho con.', 'https://i1-vnexpress.vnecdn.net/2025/11/10/hiengheptangnhi12-1762702798-1-7267-4855-1762708690.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=iKWUa5rlVkLz-0j_usEBWA', '2025-11-16 23:00:00', NULL, 'Những đứa trẻ mang ''quả bom nổ chậm''', 'https://vnexpress.net/nhung-dua-tre-mang-qua-bom-no-cham-4960363.html', 30, 32, 'https://vnexpress.net/nhung-dua-tre-mang-qua-bom-no-cham-4960363.html', 'CRAWLER', '2026-10-29 11:07:53.416376', '2026-10-29 11:07:53.416376');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2054, NULL, '2026-10-29 11:03:10.675857', 'Sau 12 tiếng vật lộn trong cơn bão, ông Phan Duy Quang (47 tuổi, Quảng Ngãi) cạn sức, quyết định buông tay người bạn đồng hành cuối cùng, phó mặc thân mình cho biển cả.', 'https://i1-vnexpress.vnecdn.net/2025/11/13/topdesign-1762968733-176296874-3285-3672-1762968757.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=hfshrJfUj8wHXJHflyrObg', '2025-11-12 23:00:00', NULL, '50 giờ sinh tử trên biển', 'https://vnexpress.net/50-gio-sinh-tu-tren-bien-4963130.html', 30, 32, 'https://vnexpress.net/50-gio-sinh-tu-tren-bien-4963130.html', 'CRAWLER', '2026-10-29 11:07:53.430375', '2026-10-29 11:07:53.430375');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2055, NULL, '2026-10-29 11:03:10.683856', 'Năm nay, Đồng bằng sông Cửu Long đón mực lũ cao hơn năm ngoái, nhưng dòng nước từ thượng nguồn đổ về ngày càng “nghèo” đi. Lượng phù sa chỉ còn khoảng 30% so với trước năm 2000, và nhiều loài cá quen thuộc dần biến mất.', 'https://i1-vnexpress.vnecdn.net/2025/11/11/thumblungheo-1762795574-3532-1762795600.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=B-0ZQBtqSHdgo6yXvxBoaQ&t=image', '2025-11-10 23:00:00', NULL, 'Lũ miền Tây ''nghèo'' đi thế nào', 'https://vnexpress.net/lu-mien-tay-ngheo-di-the-nao-4957999.html', 30, 32, 'https://vnexpress.net/lu-mien-tay-ngheo-di-the-nao-4957999.html', 'CRAWLER', '2026-10-29 11:07:53.443375', '2026-10-29 11:07:53.443375');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2056, NULL, '2026-10-29 11:03:10.691757', 'Nhìn mực nước sông Hương và sông Bồ lần lượt vượt báo động ba cả mét, Chủ tịch TP Huế Phan Thiên Định đã tính tới kịch bản xấu nhất. Một quyết định sai lúc này có thể khiến lịch sử năm 1999 lặp lại.', 'https://i1-vnexpress.vnecdn.net/2025/11/05/PCTOP-1762316886-3745-1762319119.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=EXaNXmlpGyntDIlREYPiTg', '2025-11-05 05:07:08', NULL, 'Cuộc chiến cân não ở ''rốn lũ'' miền Trung', 'https://vnexpress.net/cuoc-chien-can-nao-o-ron-lu-mien-trung-4960029.html', 30, 32, 'https://vnexpress.net/cuoc-chien-can-nao-o-ron-lu-mien-trung-4960029.html', 'CRAWLER', '2026-10-29 11:07:53.450373', '2026-10-29 11:07:53.450373');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2057, NULL, '2026-10-29 11:03:10.70085', 'Hệ thống phòng chống thiên tai lưu vực sông Cầu ở thế "vượt ngưỡng", trong khi hồ chứa không thể cắt lũ, đê điều phải chống tràn, còn máy bơm tiêu úng cũng không thể cứu nguy.', 'https://i1-vnexpress.vnecdn.net/2025/10/12/settop-1760201285-4201-1760202754.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=_eBUr0C20VkU53lJIi4EQg', '2025-10-12 01:40:09', NULL, 'Tại sao các lớp phòng thủ ngập của Thái Nguyên, Bắc Ninh không thể ''cứu nguy''', 'https://vnexpress.net/tai-sao-cac-lop-phong-thu-ngap-cua-thai-nguyen-bac-ninh-khong-the-cuu-nguy-4950247.html', 30, 32, 'https://vnexpress.net/tai-sao-cac-lop-phong-thu-ngap-cua-thai-nguyen-bac-ninh-khong-the-cuu-nguy-4950247.html', 'CRAWLER', '2026-10-29 11:07:53.455373', '2026-10-29 11:07:53.455373');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2058, NULL, '2026-10-29 11:03:10.708858', 'Viện Nghiên cứu hạt nhân Đà Lạt đang lên kế hoạch phát triển lò phản ứng hạt nhân module nhỏ, mục tiêu có 8-10 tổ máy trước năm 2035, và làm chủ công nghệ vào năm 2040, theo Viện trưởng Cao Đông Vũ.', 'https://i1-vnexpress.vnecdn.net/2025/09/29/vien-nghien-cuu-hat-nhan-dl-17-5702-5522-1759118432.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=o0xWUvBk0oT86LD9K1Fy3Q', '2025-09-29 23:00:00', NULL, '‘Việt Nam có thể làm chủ công nghệ lò hạt nhân công suất nhỏ vào năm 2040’', 'https://vnexpress.net/viet-nam-co-the-lam-chu-cong-nghe-lo-hat-nhan-cong-suat-nho-vao-nam-2040-4944813.html', 30, 32, 'https://vnexpress.net/viet-nam-co-the-lam-chu-cong-nghe-lo-hat-nhan-cong-suat-nho-vao-nam-2040-4944813.html', 'CRAWLER', '2026-10-29 11:07:53.461377', '2026-10-29 11:07:53.461377');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1114, NULL, '2026-10-29 11:03:03.652077', 'Tông vào xe tải đỗ ở lề đường, người lái xe máy ngã sang trái, ngay khi xe container đi tới, hôm 25/10 tại 420 Trần Tất Văn.', 'https://i1-vnexpress.vnecdn.net/2026/10/26/videoedit20261026104906731ezgi-8686-4676-1792990665.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=eCFVPD5UrPxFaerhdD9SKg&t=image', '2026-10-26 05:16:00', NULL, 'Húc vào xe tải đang đỗ, người đi xe máy thiệt mạng dưới bánh xe container', 'https://vnexpress.net/huc-vao-xe-tai-dang-do-nguoi-di-xe-may-thiet-mang-duoi-banh-xe-container-5136748.html', 12, 16, 'https://vnexpress.net/huc-vao-xe-tai-dang-do-nguoi-di-xe-may-thiet-mang-duoi-banh-xe-container-5136748.html', 'CRAWLER', '2026-10-29 11:07:47.959087', '2026-10-29 11:03:03.652077');
