INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1181, NULL, '2026-10-29 11:03:03.944055', 'Tần suất đi ngoài trong ngày thường do thực phẩm, đồ uống tiêu thụ nhưng đây có thể là dấu hiệu của một số bệnh tiêu hóa.', 'https://i1-suckhoe.vnecdn.net/2026/10/28/d1195bc4dc6f4408b75a2a94d3ca9d-3974-9584-1793154877.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=wkhlr2Yu5o8H27V80BDEhQ', '2026-10-28 11:00:00', NULL, 'Vì sao bạn đi ngoài nhiều lần trong ngày?', 'https://vnexpress.net/vi-sao-ban-di-ngoai-nhieu-lan-trong-ngay-5137726.html', 16, 17, 'https://vnexpress.net/vi-sao-ban-di-ngoai-nhieu-lan-trong-ngay-5137726.html', 'CRAWLER', '2026-10-29 11:07:48.352081', '2026-10-29 11:03:03.944055');
