INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1535, NULL, '2026-10-29 11:03:06.116724', 'Ông Hưng, 71 tuổi, đang chấp hành án tù, vẫn kiên quyết yêu cầu ly hôn sau 20 năm vợ chồng không còn chung sống hòa thuận, dù người vợ muốn giữ gia đình trọn vẹn cho con cháu.', 'https://i1-vnexpress.vnecdn.net/2026/10/25/geminigeneratedimageadjr8padjr-3977-8046-1792891175.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=fwJopGC33165BFLuPQUSyQ', '2026-10-25 01:19:35', NULL, 'Đang thụ án tù, cụ ông kiên quyết ly hôn sau 20 năm ly thân', 'https://vnexpress.net/dang-thu-an-tu-cu-ong-kien-quyet-ly-hon-sau-20-nam-ly-than-5136506.html', 21, 22, 'https://vnexpress.net/dang-thu-an-tu-cu-ong-kien-quyet-ly-hon-sau-20-nam-ly-than-5136506.html', 'CRAWLER', '2026-10-29 11:07:50.06794', '2026-10-29 11:03:06.116724');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1548, NULL, '2026-10-29 11:03:06.250901', 'Đầu năm 1998, tôi rời Thái Nguyên về Hà Nội trên một chuyến tàu hỏa dài năm tiếng đồng hồ. Khách ngồi chen chúc cùng lồng gà, lồng vịt. Đó là hình ảnh rất đỗi bình thường của Việt Nam thời bấy giờ.', 'https://i1-vnexpress.vnecdn.net/2026/10/16/20261016TranDangXuan-179213984-1882-3657-1792140230.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=kjyIfqpUWxY8TfWsO_V7Qg', '2026-10-16 08:32:21', NULL, '''Nhập khẩu'' kỳ tích', 'https://vnexpress.net/nhap-khau-ky-tich-5133241.html', 25, 23, 'https://vnexpress.net/nhap-khau-ky-tich-5133241.html', 'CRAWLER', '2026-10-29 11:07:50.217071', '2026-10-29 11:07:50.217071');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1561, NULL, '2026-10-29 11:03:06.330797', 'Hôm nay tôi không bắt đầu buổi dạy như thông thường. Thay vào đó, tôi hỏi sinh viên: “Các em có thể giải thích cho tôi điều gì đang diễn ra trong thành phố? Và tại sao nó lại diễn ra?”.', 'https://i1-vnexpress.vnecdn.net/2026/10/03/20261003NgoThiPhuongLe-1791045-2788-5564-1791045227.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Niz1-YuF_VFNNDFPhSt8MQ', '2026-10-03 17:00:18', NULL, 'Đòi được học tử tế', 'https://vnexpress.net/doi-duoc-hoc-tu-te-5128107.html', 25, 23, 'https://vnexpress.net/doi-duoc-hoc-tu-te-5128107.html', 'CRAWLER', '2026-10-29 11:07:50.265103', '2026-10-29 11:07:50.265103');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1565, NULL, '2026-10-29 11:03:06.354124', 'Nếu một người quan sát đứng tại ngã tư Hàng Xanh ở TP HCM hay Ngã Tư Sở ở Hà Nội vào giờ cao điểm, ấn tượng thị giác đập vào mắt không chỉ là dòng xe cuồn cuộn, mà là sự phân mảnh rõ rệt của bảng màu công nghiệp: xanh lá của Grab, vàng rực của Be và cam của ShopeeFood.', 'https://i1-vnexpress.vnecdn.net/2026/09/30/20260930MinhTruong-1790741558-8998-1790741563.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=UYdDRAB7qzrtNd6UNngJeQ', '2026-09-29 17:00:00', NULL, 'Bật app thì mệt, tắt app thì đói', 'https://vnexpress.net/bat-app-thi-met-tat-app-thi-doi-5126074.html', 25, 23, 'https://vnexpress.net/bat-app-thi-met-tat-app-thi-doi-5126074.html', 'CRAWLER', '2026-10-29 11:07:50.279072', '2026-10-29 11:07:50.279072');
