INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1911, NULL, '2026-10-29 11:03:09.311314', 'Tôi nhắc lại lời hứa trước đây, anh bảo không nhớ từng nói vậy, còn cho rằng hai đứa vẫn có điểm không hòa hợp, cần thêm thời gian.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/gemini-generated-image-d08fr6d-8006-9865-1792766989.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=rVymWiwZj35j1WQnUlmfpA', '2026-10-24 02:00:00', NULL, 'Xin quay lại với tôi nhưng bạn trai chẳng chịu cưới', 'https://vnexpress.net/xin-quay-lai-voi-toi-nhung-ban-trai-chang-chiu-cuoi-5136221.html', 28, 30, 'https://vnexpress.net/xin-quay-lai-voi-toi-nhung-ban-trai-chang-chiu-cuoi-5136221.html', 'CRAWLER', '2026-10-29 11:07:52.451878', '2026-10-29 11:07:52.451878');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1914, NULL, '2026-10-29 11:03:09.332413', 'Bố mẹ chồng biết chuyện cũng không có ý định giúp đỡ, chỉ bảo vợ chồng tôi lớn rồi, tự làm tự chịu, ông bà già rồi không giúp được.', 'https://i1-vnexpress.vnecdn.net/2026/10/23/GeminiGeneratedImageenx32wenx3-1925-5630-1792743560.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=vAOg23ML7ckP0QwG8b4vEw', '2026-10-23 08:00:00', NULL, 'Nhà chồng không giúp lúc hoạn nạn, giờ muốn chúng tôi góp tiền sửa nhà', 'https://vnexpress.net/nha-chong-khong-giup-luc-hoan-nan-gio-muon-chung-toi-gop-tien-sua-nha-5136074.html', 28, 30, 'https://vnexpress.net/nha-chong-khong-giup-luc-hoan-nan-gio-muon-chung-toi-gop-tien-sua-nha-5136074.html', 'CRAWLER', '2026-10-29 11:07:52.466884', '2026-10-29 11:07:52.466884');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1923, NULL, '2026-10-29 11:03:09.398438', 'Trước đây anh ngoại tình với đồng nghiệp, bị chị phát hiện nhưng anh vẫn tiếp tục với cô gái đó mặc kệ vợ con.', 'https://i1-vnexpress.vnecdn.net/2026/10/21/GeminiGeneratedImagecbfniycbfn-6626-6774-1792596709.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=eCd9NTOMoZKoqGR1lIphTQ', '2026-10-21 17:00:00', NULL, 'Có thai rồi tôi mới phát hiện bạn trai từng ly hôn vì phản bội vợ', 'https://vnexpress.net/co-thai-roi-toi-moi-phat-hien-ban-trai-tung-ly-hon-vi-phan-boi-vo-5135337.html', 28, 30, 'https://vnexpress.net/co-thai-roi-toi-moi-phat-hien-ban-trai-tung-ly-hon-vi-phan-boi-vo-5135337.html', 'CRAWLER', '2026-10-29 11:07:52.503883', '2026-10-29 11:07:52.503883');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1935, NULL, '2026-10-29 11:03:09.492155', 'Anh có luôn người yêu mới, cô ấy là cả tương lai tươi đẹp, anh sợ khi tôi giữ thai lại sẽ cản trở cuộc hôn nhân của anh.', 'https://i1-vnexpress.vnecdn.net/2026/10/20/gemini-generated-imageo01fb9o0-6882-4596-1792481237.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=6qB0M_Ozj6YF59rRKCV7Ig', '2026-10-20 07:33:15', NULL, 'Vừa chia tay tôi phát hiện có thai, anh ''phủi'' luôn trách nhiệm', 'https://vnexpress.net/vua-chia-tay-toi-phat-hien-co-thai-anh-phui-luon-trach-nhiem-5134653.html', 28, 30, 'https://vnexpress.net/vua-chia-tay-toi-phat-hien-co-thai-anh-phui-luon-trach-nhiem-5134653.html', 'CRAWLER', '2026-10-29 11:07:52.553826', '2026-10-29 11:07:52.553826');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (1947, NULL, '2026-10-29 11:03:09.660498', 'Hình ảnh những viên gạch ống nhét tờ giấy đứng ngơ ngác trên vỉa hè là ký hiệu quen thuộc nhưng lại khiến nhiều người đi đường khó hiểu!', 'https://i1-vnexpress.vnecdn.net/2026/10/27/document-1793077250-8929-1793077714.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=fz3lVO5e8_Izhh8kEXundQ', '2026-10-28 01:58:55', NULL, 'Những cục gạch nhét giấy ven đường dùng để làm gì?', 'https://vnexpress.net/nhung-cuc-gach-nhet-giay-ven-duong-dung-de-lam-gi-5137394.html', 29, 31, 'https://vnexpress.net/nhung-cuc-gach-nhet-giay-ven-duong-dung-de-lam-gi-5137394.html', 'CRAWLER', '2026-10-29 11:07:52.721611', '2026-10-29 11:07:52.721611');
