INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2019, NULL, '2026-10-29 11:03:10.351249', 'Vượt cửa tử sau biến cố ung thư tuổi 23, Trang Nguyễn dấn thân vào những đường dây buôn lậu ngà voi, sừng tê giác xuyên lục địa trong vai trò hỗ trợ điều tra.', 'https://i1-vnexpress.vnecdn.net/2026/05/10/Thumb1800x10801-1778406810-2766-1778406914.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=C8vRY0UXmR2mgGsgiSyWtQ', '2026-05-10 23:00:00', NULL, 'Nữ tiến sĩ bảo tồn: ''Thà chết trước họng súng còn hơn trên giường bệnh''', 'https://vnexpress.net/nu-tien-si-bao-ton-tha-chet-truoc-hong-sung-con-hon-tren-giuong-benh-5072187.html', 30, 32, 'https://vnexpress.net/nu-tien-si-bao-ton-tha-chet-truoc-hong-sung-con-hon-tren-giuong-benh-5072187.html', 'CRAWLER', '2026-10-29 11:07:53.194897', '2026-10-29 11:07:53.194897');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2029, NULL, '2026-10-29 11:03:10.440369', 'Từ căn phòng nhỏ với hơn 20 con người, giữa thời Internet còn chậm và đắt đỏ, VnExpress bước vào không gian mạng. Hai mươi lăm năm sau, giữa biến động công nghệ, hành trình ấy vẫn xoay quanh một giá trị: gìn giữ niềm tin độc giả.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/settop2-1772037862-6860-1772037869.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=n9sK9bhe07r5hXWcfLP9xQ', '2026-02-25 17:00:17', NULL, 'VnExpress tròn 25 tuổi', 'https://vnexpress.net/vnexpress-tron-25-tuoi-5006404.html', 30, 32, 'https://vnexpress.net/vnexpress-tron-25-tuoi-5006404.html', 'CRAWLER', '2026-10-29 11:07:53.247645', '2026-10-29 11:07:53.247645');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2040, NULL, '2026-10-29 11:03:10.541751', 'Nhật ký lũ trên cột nhà ông Nguyễn Văn Biên (82 tuổi) ở Hội An, Đà Nẵng, năm nay khắc thêm một dấu mốc mới - 2025, vượt tất cả năm lịch sử ông từng ghi dấu trước đó - 1964, 1999, 2007, và 2009.', 'https://i1-vnexpress.vnecdn.net/2025/12/29/20251229thumbbai-1767026998-9854-1767027003.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=uLKTrtEMD_b5bdv9nHlNTw', '2025-12-29 23:00:00', NULL, '2025 - Năm thiên tai cực hạn', 'https://vnexpress.net/2025-nam-thien-tai-cuc-han-4999742.html', 30, 32, 'https://vnexpress.net/2025-nam-thien-tai-cuc-han-4999742.html', 'CRAWLER', '2026-10-29 11:07:53.313645', '2026-10-29 11:07:53.313645');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2047, NULL, '2026-10-29 11:03:10.606071', 'Hà Nội hiện có ít nhất 61 trạm quan trắc chất lượng không khí từ Nhà nước và tư nhân, trong đó có 6 trạm "chuẩn". Tuy nhiên, nhiều trạm không hoạt động dẫn đến "khoảng trống" dữ liệu trong đánh giá ô nhiễm ở Thủ đô.', 'https://i1-vnexpress.vnecdn.net/2025/12/02/L1046378-JPG-5768-1764690703.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=UCS-n66RJo8MHPHAYRxSvg', '2025-12-03 23:00:00', NULL, '''Khoảng trống'' dữ liệu chất lượng không khí Hà Nội', 'https://vnexpress.net/khoang-trong-du-lieu-chat-luong-khong-khi-ha-noi-4988989.html', 30, 32, 'https://vnexpress.net/khoang-trong-du-lieu-chat-luong-khong-khi-ha-noi-4988989.html', 'CRAWLER', '2026-10-29 11:07:53.358379', '2026-10-29 11:07:53.358379');
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, source, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (2051, NULL, '2026-10-29 11:03:10.649854', 'Đăk Lăk hứng chịu lũ lịch sử 50 năm, nhưng hệ thống 5 hồ chứa điều tiết lũ dọc lưu vực sông Ba chỉ "giải cứu" được 26% lượng lũ cho hạ du khiến Phú Yên cũ chìm trong biển nước.', 'https://i1-vnexpress.vnecdn.net/2025/11/24/20251124topphongthusongba-1763-2974-9206-1763925641.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=L5VsW6W4_Ans2-fBMifskw', '2025-11-23 23:35:04', NULL, 'Hệ thống phòng lũ của Đăk Lăk mong manh thế nào', 'https://vnexpress.net/he-thong-phong-lu-cua-dak-lak-mong-manh-the-nao-4985259.html', 30, 32, 'https://vnexpress.net/he-thong-phong-lu-cua-dak-lak-mong-manh-the-nao-4985259.html', 'CRAWLER', '2026-10-29 11:07:53.398375', '2026-10-29 11:07:53.398375');
